window.WORLD_WARS={"version":"0.18.0","wars":[{"id":"ww1","name":"第一次世界大战","years":"1914—1918","subtitle":"从七月危机，到战壕与帝国的终局","coverage":"1914年7月—1918年11月，53个月连续；另列刺杀前史与1919年和会。","intro":"一场巴尔干危机为什么成为世界战争？联盟、动员、帝国竞争与决策失误互相推动；速胜失效后，战壕、封锁、工业与社会动员把战争拖入长期消耗。","start":"1914-07","end":"1918-11","default":"1914-07","phases":[["1914-06","危机与开战"],["1915-01","扩大与僵持"],["1916-01","消耗战之年"],["1917-01","革命与新力量"],["1918-01","攻势、崩溃与停战"],["1919-01","和平的难题"]],"months":[{"id":"ww1-1914-06","date":"1914-06","title":"萨拉热窝：刺杀并没有自动写下战争结局","theaters":["巴尔干","外交"],"countries":["ah","rs","de"],"people":["斐迪南","普林西普"],"story":["6月28日，奥匈皇储斐迪南与妻子在萨拉热窝遇刺。刺杀发生在民族主义、帝国边疆和塞尔维亚问题交织的地区，却并不意味着各国当日已经决定打一场世界大战。","斐迪南此行身处奥匈统治下的波斯尼亚，帝国的行政边界并不能消除当地民族认同的冲突。遇刺者是王朝继承人，行刺者却来自反对帝国统治的青年网络，两种政治未来在同一座城市迎面相撞。","此后真正重要的变化发生在各国政府之间。奥匈要决定如何惩罚塞尔维亚，德国要决定支持到何种程度，俄国又要判断是否必须介入。刺杀解释了危机从哪里开始，无法代替对后续决策的追究。","维也纳随后追究塞尔维亚责任，柏林的支持、俄国的保护姿态和各国对盟约信誉的判断，逐步放大危机。理解开战，应追踪接下来一个月的最后通牒与动员，而不是把全部责任归给一声枪响。"],"perspectives":[{"country":"ah","text":"奥匈统治者把塞尔维亚视为帝国边疆稳定的威胁。"},{"country":"rs","text":"塞尔维亚面临邻近大国的压力，刺客行为与政府责任不能直接画等号。"}],"sources":[{"id":"nam14","locator":"1914-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"欧洲已有联盟与边疆争议，刺杀把这些长期矛盾集中到一场外交危机。","after":"下一节点转入七月：追踪最后通牒如何把惩罚行动变成国家间战争。"},"relatedBattles":[]},{"id":"ww1-1914-07","date":"1914-07","title":"最后通牒与动员：局部危机越过门槛","theaters":["外交","巴尔干"],"countries":["ah","rs","de","ru","fr","uk"],"people":["威廉二世","尼古拉二世"],"story":["7月23日，奥匈向塞尔维亚提出最后通牒。塞方接受大部分要求，却未能消除奥匈发动战争的决心。28日奥匈宣战，俄国随后扩大动员，危机从巴尔干向欧洲联盟体系传导。","塞尔维亚对通牒作出的让步，没有让奥匈放弃军事行动。最后通牒中的调查与司法要求触及主权，接受大部分条件与接受全部条件，在强弱悬殊的谈判中产生了截然不同的解释。","铁路动员一旦扩大，军方就强调更改计划的危险，外交可用的时间不断缩短。但时间表本身由人制定，各国仍作出了支持、拒绝、宣战或保持距离的选择。危机升级的责任，必须在这些具体决定中辨认。","动员不仅是外交信号，也牵动铁路、兵员和作战时刻表。各国领导人担心迟动一步便失去优势，反而压缩了继续协商的空间。战争由一连串仍可辨认的政治选择扩展，绝非某个机械装置自行启动。"],"perspectives":[{"country":"de","text":"柏林支持奥匈，同时担心俄法夹击，军事部署愈加影响外交。"},{"country":"ru","text":"俄国维护巴尔干影响及塞尔维亚关系，却使德国把动员视为迫近的军事危险。"}],"sources":[{"id":"nam14","locator":"1914-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"六月的刺杀留下如何应对塞尔维亚的问题，七月的政府选择把它推向战争。","after":"八月将检验各国的速胜方案：宣战以后，军队能否实现政治承诺？"},"relatedBattles":[]},{"id":"ww1-1914-08","date":"1914-08","title":"欧洲开战：比利时、坦能堡与青岛被卷入","theaters":["西线","东线","亚洲"],"countries":["de","fr","uk","ru","jp","cn"],"people":["霞飞","兴登堡","鲁登道夫"],"story":["德国先后对俄、法宣战，并入侵比利时，企图经北方迅速击败法国。英国以比利时中立及欧洲安全为重要理由参战，法国边境攻势受挫，英法军向南撤退，速胜计划开始接受现实检验。","德国经比利时推进，使一个中立国成为入侵路线，列日等地的抵抗和占领中的暴力很快打碎了战争只是军队决斗的想象。法军最初在边境进攻，英国远征军则在蒙斯交战后撤退，军队不断调整原有计划。","东线俄军的提前进攻迫使德国应对另一方向。坦能堡的胜利建立在对俄军行动、通信与部队分离的利用上，却不能弥补德军在法国面临的时间与补给问题。各战场相连，但胜利无法简单相互兑换。","东线俄军进入东普鲁士，在坦能堡遭德军重创；日本又对德国宣战，准备进攻其在中国山东的据点。欧洲战争迅速牵动亚洲与殖民地，中立的中国也无法置身于列强争夺之外。"],"perspectives":[{"country":"fr","text":"法国必须在边境失利后保持军队完整，保卫本土成为紧迫任务。"},{"country":"cn","text":"山东成为交战方争夺的空间，中国中立未能保障当地免受战争影响。"}],"sources":[{"id":"nam14","locator":"1914-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"七月动员变成了八月的行军与战斗，联盟承诺开始产生实际军事后果。","after":"德军逼近巴黎，下一月的马恩河将决定速胜设想能否继续。"},"relatedBattles":[]},{"id":"ww1-1914-09","date":"1914-09","title":"马恩河：没有攻下巴黎的军队","theaters":["西线","东线"],"countries":["fr","uk","de","ru","ah"],"people":["霞飞","小毛奇"],"story":["9月，德军逼近巴黎，却在连续行军中拉长补给与部队间距。英法军抓住德军部署间隙反击，第一次马恩河战役迫使德军后撤，迅速结束西线战争的设想落空。","德军越向南走，补给与部队联络越难维持，右翼部队的行动也使阵线出现空隙。法国将兵力转向巴黎外围并发动反击，英国远征军进入德军之间的间隔，迫使进攻者重新考虑继续推进的风险。","退到埃纳河的德军利用高地构筑阵地，英法军正面进攻未能轻易将其赶走。双方随后都尝试从北边绕过去，结果不是绕到一片空地，而是把另一支也在北移的军队带进新的交战区。","德军在埃纳河一线据守，双方开始向北寻找能够迂回对手的空间。东线俄军则在加利西亚打击奥匈军。欧洲并未出现一个统一的胜负节奏：德国东线的胜利，无法替代奥匈承受的压力。"],"perspectives":[{"country":"de","text":"必须调整西线部署，在两线之间分配兵力。"},{"country":"fr","text":"守住巴黎方向并不等于收复失地，接下来仍需突破新形成的防线。"}],"sources":[{"id":"nam14","locator":"1914-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"八月的快速推进没有消灭英法主力，疲惫与联络裂缝在马恩河显露。","after":"双方继续向北寻求迂回，十月的海岸与伊普尔之争由此展开。"},"relatedBattles":[]},{"id":"ww1-1914-10","date":"1914-10","title":"奔向海岸，走进战壕","theaters":["西线","中东"],"countries":["de","uk","fr","ot","ru"],"people":["恩维尔帕夏"],"story":["双方试图从对方北翼绕过去，战线却不断向英吉利海峡延伸。伊普尔附近激战，使沿海通道成为争夺重点；越来越多部队掘壕自保，机枪与炮兵让开阔地上的进攻极为昂贵。","“奔向大海”并不是两军都把海岸当作终点的整齐竞赛，而是一连串试图包抄对方的行动。每次迂回都遇到新的部队，防线就又向北延长一段，最终把缺口逐步封住。","伊普尔附近关系到海峡港口及英国与大陆部队的联系。英国、法国及来自帝国其他地区的部队反复抵抗，德军也未能打出决定性出口。固定阵地逐渐增多，军队必须学习在火力面前修筑、轮换和生存。","月底，奥斯曼舰队袭击俄国黑海港口，帝国进一步卷入战争。西线尚未分出胜负，新的高加索与中东战场已经打开，海峡、帝国交通和宗教政治也被纳入战争。"],"perspectives":[{"country":"uk","text":"保住海峡港口关系到远征军运输和本土安全。"},{"country":"ot","text":"加入冲突后必须同时考虑俄国边境与英国控制的交通要道。"}],"sources":[{"id":"nam14","locator":"1914-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"马恩河阻止速胜后，双方仍试图通过侧翼行动打破平衡。","after":"西线难以突破之时，十一月的青岛与两河战场显示战争已扩大为全球争夺。"},"relatedBattles":[]},{"id":"ww1-1914-11","date":"1914-11","title":"青岛陷落，巴士拉被占：战争越出欧洲","theaters":["亚洲","中东","西线"],"countries":["jp","cn","de","uk","ot"],"people":["加藤定吉"],"story":["11月，青岛德军在日英进攻下投降，日本扩大对山东的控制。欧洲之外的据点争夺，改变了中国的外交处境，也为战后山东问题埋下争议。","青岛的德军基地位于中国领土上，交战方的军事行动却没有以中国意愿为前提。围攻、投降与其后权益交接，使局部基地的命运变成中国主权与战后外交问题。","巴士拉方向，英印军既是欧洲战争的参与者，也是英国帝国交通与区域利益的执行者。印度兵员被运往陌生地区，运输、疾病与地方社会关系跟着军队一起进入战争，所谓海外战果远不止一面旗帜的升降。","英印军在美索不达米亚登陆并占领巴士拉，英国与奥斯曼公开交战。西线第一次伊普尔战斗渐告结束，绵延战壕取代了夏季的机动作战；帝国士兵被运往远离故乡的前线，战争的全球性质更加清楚。"],"perspectives":[{"country":"jp","text":"借对德作战扩大东亚影响，目标并不限于欧洲盟友的需要。"},{"country":"uk","text":"动用印度等地兵力保护海路与波斯湾利益，殖民体系成为战争资源。"}],"sources":[{"id":"nam14","locator":"1914-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"十月奥斯曼介入扩大了战场，欧洲之外的据点和交通线成为实际目标。","after":"十二月海上胜负与西线局部停火并列，战争继续扩大而没有统一节奏。"},"relatedBattles":[]},{"id":"ww1-1914-12","date":"1914-12","title":"圣诞停火与仍在运转的战争","theaters":["西线","海战"],"countries":["uk","de","fr"],"people":["约翰·弗伦奇"],"story":["12月，西线部分地段出现非正式圣诞停火，士兵短暂停止射击，有的交换物品或掩埋遗体。它只发生于局部，不能被说成整条战线共同休战，更没有使各国政府停止战争。","圣诞停火中的短暂接触，依赖相距很近的阵地与局部默契，许多地段仍继续交火。后来把它讲成所有士兵共同决定终战，会掩盖前线差异，也会抹去军队组织对停火的限制。","与此同时，英德舰队在南大西洋和北海行动，证明海洋不是战壕之外的安静背景。海上运输可以把全球物资送进欧洲，也能把欧洲战争带到遥远海域，两条力量不断互相牵动。","同月，英军在福克兰群岛附近海战获胜，德国军舰又炮击英国沿海城镇。前线短暂相认与后方继续动员并存：普通人的接触可以打断敌意，却还不足以拆除正在扩大的人力与物资消耗体系。"],"perspectives":[{"country":"uk","text":"海军争夺交通线，沿海居民同时发现本土也可能直接遭袭。"},{"country":"de","text":"大陆战线僵持后，海上行动试图增加英国承受的压力。"}],"sources":[{"id":"nam14","locator":"1914-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"十一月的海外争夺没有结束战争，军队在冬季进入更长期的组织与消耗。","after":"新的一年，飞艇与潜艇将把危险进一步带到城市和商船航线上。"},"relatedBattles":[]},{"id":"ww1-1915-01","date":"1915-01","title":"飞艇飞向英国，战场伸向天空","theaters":["空战","海战"],"countries":["uk","de"],"people":["齐柏林"],"story":["1月，德国飞艇轰炸英国城镇，战争的危险越过海峡，进入平民生活。防空、警报和心理承受逐渐成为后方事务，天空不再只是侦察的辅助空间。","飞艇能越过舰队与海峡，却难以像地面炮兵那样辨认目标，天气、导航和防空都会影响行动。对于城镇居民，警报与遮光意味着国家安全第一次如此直接地进入夜间生活。","多格尔沙洲交战中，舰队通信与追击选择影响了哪些舰艇能够脱离。主力舰价格高昂、建造缓慢，各方既期待海战改变全局，又不愿冒失去整个舰队的风险，海军行动因此常带有试探性。","24日多格尔沙洲海战中，英国舰队与德国舰队交锋。海军争夺没有带来决定性的战略终局，双方仍须在保存主力、寻找出击机会和维持海上贸易之间权衡。"],"perspectives":[{"country":"de","text":"空袭与海上行动旨在把压力带到英国本土。"},{"country":"uk","text":"海军优势仍需维持，平民防护也成为战争治理的新问题。"}],"sources":[{"id":"nam15","locator":"1915-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-01相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"上一年战线固定后，各国寻找从空中与海上给对手增加压力的方法。","after":"二月的潜艇政策和达达尼尔行动，会把这些侧翼尝试扩大为战略选择。"},"relatedBattles":[]},{"id":"ww1-1915-02","date":"1915-02","title":"潜艇与海峡：寻找战壕之外的突破口","theaters":["海战","中东","东线"],"countries":["de","uk","ot","ru"],"people":["丘吉尔"],"story":["德国扩大潜艇对商船的威胁，试图打击英国的补给与贸易。海上封锁和反封锁不只影响军舰，商船乘员、旅客与中立国也逐渐陷入风险。","英国依赖海运获得粮食与工业原料，德国则把潜艇视为绕过英国水面舰队优势的工具。但商船可能载有中立国人员与货物，摧毁运输的军事目标不断碰撞国际法与外交关系。","海峡另一端，协约国希望借舰炮迫使奥斯曼要塞失效，打通航路并改变巴尔干局势。这个构想把一次行动寄予多重政治成果，却需要证明军舰真的能够穿过水雷、岸炮和狭窄水道。","英法舰队开始炮击达达尼尔海峡要塞，谋求打开通往俄国的海路。东线德军又在马祖里湖区重创俄军。各国都在寻找能够改变全局的侧翼，却必须面对新的地形、补给和外交代价。"],"perspectives":[{"country":"uk","text":"海峡行动希望以海军力量绕开西线僵局。"},{"country":"ru","text":"需要盟友支持和外部物资，东线损失进一步加大压力。"}],"sources":[{"id":"nam15","locator":"1915-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-02相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"一月的试探暴露海空威胁，二月开始把海上手段用于解决总体僵局。","after":"三月的海峡强攻与西线试验，将检验“突破一点便能打开全局”的判断。"},"relatedBattles":[]},{"id":"ww1-1915-03","date":"1915-03","title":"新沙佩勒与达达尼尔：突破为何没能延续","theaters":["西线","中东"],"countries":["uk","fr","de","ot"],"people":["丘吉尔","伊恩·汉密尔顿"],"story":["英印军在新沙佩勒一度攻入德国阵地，但通信、增援与火力衔接未能支持继续推进。打开第一道防线之后，如何及时把兵力和补给送进去，成为比最初突击更难的问题。","新沙佩勒最初的成功来自较集中准备，难题却在步兵越过原阵地之后出现。炮兵怎样跟进，后续部队何时进入，消息如何穿过被破坏的战场，决定了缺口能否成为真正突破。","达达尼尔海峡同样不是击坏几座要塞便可安全通行。军舰遭损后，需要扫雷、控制岸边与陆上配合，原本被想象为短捷径的行动，逐渐要求投入一支能够长期作战的远征军。","18日，英法舰队强行通过达达尼尔海峡的行动受挫，水雷与岸防使军舰遭受损失。海军未能独自完成任务，协约国转而准备登陆，最初希望缩短战争的行动开始走向漫长陆战。"],"perspectives":[{"country":"ot","text":"守住海峡可保护首都方向与重要交通。"},{"country":"uk","text":"必须在终止行动与扩大投入之间作出选择，沉没成本不能证明继续进攻必然正确。"}],"sources":[{"id":"nam15","locator":"1915-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-03相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"二月寄望海峡与潜艇改变战略平衡，三月却显示手段与目标间存在距离。","after":"海军受挫后转向登陆，四月加里波利将使这次扩大投入成为现实。"},"relatedBattles":[]},{"id":"ww1-1915-04","date":"1915-04","title":"毒气与登陆：战争跨过新的界限","theaters":["西线","中东"],"countries":["de","fr","uk","ot"],"people":["穆斯塔法·凯末尔","伊恩·汉密尔顿"],"story":["22日，德军在第二次伊普尔战役中大规模施放氯气，守军遭受突然打击，防毒装备与救护随之成为紧急需要。新武器带来恐怖，却没有自动解决突破和占领的问题。","在伊普尔，毒气造成突然惊恐与伤亡，后方随即寻找防护方法。进攻者却同样需要预备队、通信与后续行动才能利用缺口，新武器产生的短暂优势并不会自行变成占领成果。","加里波利登陆后，滩头、山脊与通向内陆的道路成为关键。奥斯曼守军利用地形与增援阻止深入，登陆军的每一箱弹药和饮水又必须从海上卸载、向前搬运，远征很快受到日常供给的束缚。","25日，协约国在加里波利登陆。凯末尔等组织的奥斯曼防御阻止登陆军迅速向纵深推进，滩头阵地逐渐变为消耗战。与此同时，奥斯曼当局对亚美尼亚人的迫害与驱逐升级，战争中的国家暴力不能被战役叙事遮蔽。"],"perspectives":[{"country":"ot","text":"军队防御海峡；政府针对亚美尼亚人的暴力则是另一条必须辨认的历史进程。"},{"country":"uk","text":"多国及帝国部队登陆后，需要面对补给、疾病与山地防御的持续压力。"}],"sources":[{"id":"nam15","locator":"1915-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"armenian","locator":"1915-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-04相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"三月未能以海军打开海峡，使陆军在四月承担更艰巨的任务。","after":"五月船舶遭袭、东线突破和意大利参战，将进一步扩大战争与外交的连锁反应。"},"relatedBattles":["gallipoli"]},{"id":"ww1-1915-05","date":"1915-05","title":"卢西塔尼亚与意大利参战","theaters":["海战","意大利","东线"],"countries":["de","uk","us","it","ah","ru"],"people":["威尔逊"],"story":["7日，德国潜艇击沉客轮卢西塔尼亚号，大量平民遇难，其中包括美国人。德国试图用潜艇削弱英国，却因此增加与美国决裂的风险，军事手段与外交后果紧密相连。","潜艇战略存在尖锐矛盾：若遵守事先警告与人员撤离程序，潜艇自身可能暴露；若不顾人员直接攻击，则更容易把美国推向敌方。德国此后时而限制、时而扩大潜艇战，始终受这一困境牵制，美国却并未因此立即参战。","西线战斗同时暴露炮弹供应不足等问题，英国国内围绕军需发生政治争论，新设军需部由劳合·乔治主持。工业生产逐步被更强地组织起来，工人的劳动、工厂安排和政府能力，开始更直接地决定前线能够使用多少炮火。","东线戈尔利采—塔尔努夫突破迫使俄军后撤；意大利则在伦敦条约承诺的领土利益推动下，于23日向奥匈宣战。奥匈必须增顾阿尔卑斯山和伊松佐河方向，协约国期待牵制兵力，意大利领导层则追求本国利益，新盟友并未使总体僵局立即结束。"],"perspectives":[{"country":"us","text":"政府仍维持中立，但本国公民遇难使对德关系进一步恶化。"},{"country":"it","text":"从中立转为协约国一方，期待领土收益，却将承受长期山地作战。"}],"sources":[{"id":"nam15","locator":"1915-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1915-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-05相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"四月的武器与登陆没有结束僵局，五月各国转而追加战线与外交压力。","after":"新盟友的参战承诺要在六月山地攻势中兑现，另一种消耗战由此开始。"},"relatedBattles":[]},{"id":"ww1-1915-06","date":"1915-06","title":"伊松佐河：新的战线，熟悉的消耗","theaters":["意大利","中东"],"countries":["it","ah","uk","ot"],"people":["卡多尔纳"],"story":["意大利军队在伊松佐河一线发动攻势，山地、河流和既设防御使进攻困难。参战时希望通过新战线牵动奥匈，实际却走向一场又一场代价高昂的重复攻击。","伊松佐一线，高处防御能够观察并打击进攻路线，山地道路又限制火炮与物资运输。夺取一处山头，需要先把人、弹药、食物和伤员救护组织起来，战术地图上看似接近的目标，实际距离很长。","西线与加里波利也在争夺有限阵地。士兵从受训、搭船、行军到进入战壕，耗费了巨大组织成本；一旦这些人短期内大量损失，国家便需要更长时间补足经验，而不仅是补齐人数。","加里波利的进攻也没有突破半岛。战线并非完全静止，局部阵地反复易手，但大量伤亡没有带来预想中的政治终局。观察这一月，要把战场推进的有限距离与持续消耗放在一起。"],"perspectives":[{"country":"it","text":"必须把参战承诺变成军事成果，地形却限制进攻。"},{"country":"ah","text":"在俄国与意大利两个方向分配兵力，防守成功仍意味着不断消耗。"}],"sources":[{"id":"nam15","locator":"1915-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"五月的参战扩大了协约国人力，也带来必须支持的新战线。","after":"七月的海外胜利与西线新武器会显示，扩大投入仍没有统一的胜利公式。"},"relatedBattles":[]},{"id":"ww1-1915-07","date":"1915-07","title":"殖民地投降，欧洲僵局仍在","theaters":["非洲","西线"],"countries":["de","uk"],"people":["博塔"],"story":["德属西南非洲守军于7月投降，南非军队的进攻改变了当地殖民控制。对欧洲政府而言这是战果，对当地居民而言则是统治关系继续重组，不能仅把殖民地写成地图上被换色的区域。","德属西南非洲与欧洲主战场相距遥远，守军难以获得稳定外援，区域力量对比因而比欧洲前线更快改变。殖民地居民却并非被动背景，他们面对征用、劳役与不同统治者的要求。","胡赫一带的火焰喷射器攻击，把近距离战斗的恐惧进一步放大。各方随即寻找掩护、反击与技术对策，武器竞赛不断升级，仍无法单独解决穿过防线以后怎样持续推进的问题。","西线仍围绕战壕与有限据点作战，德国在胡赫使用火焰喷射器等手段。新技术接连投入，却没有立即恢复开战时期待的快速机动；军队与工业之间的联系日益紧密。"],"perspectives":[{"country":"de","text":"海外据点逐步孤立，主战场仍在欧洲。"},{"country":"uk","text":"帝国体系提供兵员与区域力量，殖民战争的后果延续到停战之后。"}],"sources":[{"id":"nam15","locator":"1915-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-07相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"六月各处攻势代价高昂，七月出现的成果主要在不同条件下的海外战场。","after":"八月东线大撤退与加里波利增援，把战争的重点再次拉回联盟承受力。"},"relatedBattles":[]},{"id":"ww1-1915-08","date":"1915-08","title":"华沙失守，加里波利再押一注","theaters":["东线","中东"],"countries":["ru","de","ah","uk","ot"],"people":["尼古拉二世","穆斯塔法·凯末尔"],"story":["德军占领华沙，俄军在大撤退中放弃大片地区，运输、军需与难民问题彼此挤压。避免部队被围成为现实选择，领土损失则不断削弱政府威信。","俄军退却时，不只是战斗部队移动，铁路、仓库、行政人员和大量平民也被卷入迁移。避免被包围有其军事理由，撤退造成的损失与失序却会直接转化为对政府的不满。","加里波利新的登陆又面临从海滩向高处拓展的老问题。不同登陆点如果不能及时形成配合，就难以把最初的突然性扩大为统一攻势；增兵有时延长了战斗，却未能改变决定战局的地形与组织条件。","协约国在苏夫拉等处增兵登陆，试图打破加里波利僵局，但新的攻势仍受阻。一个战场上的困难促使人们期待另一个方向的突破，却也可能把有限资源分散到更多无法迅速取胜的前线。"],"perspectives":[{"country":"ru","text":"军事撤退与后方不满相互强化，战争负担进入政治核心。"},{"country":"ot","text":"守住半岛的代价持续累积，防御胜利并不意味着帝国其他方向安全。"}],"sources":[{"id":"nam15","locator":"1915-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-08相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"七月仍有局部胜利，八月却显示联盟内一些军队已承受越来越严重的危机。","after":"东线失败会进入九月俄皇亲掌统帅权的决定，西线则试图用新攻势减压。"},"relatedBattles":[]},{"id":"ww1-1915-09","date":"1915-09","title":"卢斯攻势与俄皇亲掌统帅权","theaters":["西线","东线"],"countries":["uk","fr","de","ru"],"people":["尼古拉二世","约翰·弗伦奇"],"story":["英军在卢斯、法军在香槟等地进攻，试图用协同压力打开西线。卢斯初期推进未能持续，增援和通信问题使局部机会流失，战场再度陷入相持。","在卢斯，英军使用毒气时仍受风向和施放条件限制，后续进攻又依赖预备队及时到达。攻入阵地只是数个环节中的一个，任何环节脱节都可能让已经付出的伤亡无法形成持续成果。","俄皇亲临统帅部，意味着留在首都的政治运转与军事指挥更加分离。战场责任被集中到君主身上，军需与铁路问题却不是个人在场就能修好，王朝因而更深地卷入战争成败。","尼古拉二世亲自担任俄军最高统帅，把皇室声望与战争成败绑得更紧。德国也调整潜艇政策，以缓解美国压力；作战选择、国内统治与中立国反应，已成为同一场战争的不同侧面。"],"perspectives":[{"country":"ru","text":"皇帝承担更直接的军事责任，却无法单靠更换统帅解决后勤与社会危机。"},{"country":"uk","text":"扩大军队之后，如何训练、指挥与协同仍需学习。"}],"sources":[{"id":"nam15","locator":"1915-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-09相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"八月的俄军撤退迫使领导层回应，协约国也希望西线进攻分担压力。","after":"十月保加利亚参战后，联盟将在巴尔干面对新的结构性危险。"},"relatedBattles":[]},{"id":"ww1-1915-10","date":"1915-10","title":"塞尔维亚遭夹击，巴尔干通道被改写","theaters":["巴尔干"],"countries":["rs","ah","de","uk","fr"],"people":["麦肯森"],"story":["德国、奥匈与新加入同盟国的保加利亚进攻塞尔维亚。塞军面临多方向压力，协约国在萨洛尼卡登陆，仍未能及时改变塞尔维亚本土的困境。","保加利亚从另一方向进攻，使塞军不能只盯住北面的德奥压力。道路与退路受到威胁时，保卫首都与保存军队之间出现冲突，小国领导人面对的选择越来越残酷。","萨洛尼卡登陆需要港口、铁路、政治许可与增援配合，不是部队上岸就能立刻救援塞尔维亚。盟国愿望与可执行军事行动之间的差距，在巴尔干的复杂地形和外交关系中尤其明显。","这一变化使同盟国与奥斯曼之间的陆上联系更加有利，巴尔干不再只是1914年开战的起点，而成为补给、联盟与帝国交通的持续争夺地。小国的生存与大国的战略安排之间，始终存在不对称。"],"perspectives":[{"country":"rs","text":"保全部队与国家存续成为紧迫问题。"},{"country":"de","text":"通过巴尔干改善与奥斯曼的联系，战略收益不限于占领塞尔维亚。"}],"sources":[{"id":"nam15","locator":"1915-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-10相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"九月西线进攻未能决定战争，同盟国把机会转向巴尔干。","after":"夹击会逼出十一月的艰难撤退，战争随军民一起进入山地与流亡。"},"relatedBattles":[]},{"id":"ww1-1915-11","date":"1915-11","title":"塞军撤退与两河远征的极限","theaters":["巴尔干","中东"],"countries":["rs","uk","ot"],"people":["汤森德"],"story":["塞尔维亚军队与部分平民在严酷条件下向亚得里亚海方向撤退，军事失败转为饥饿、疾病和流亡。保存下来的部队后来仍会回到战争，并非国家在地图上被占领便不再抵抗。","塞军撤退穿越阿尔巴尼亚方向，严寒、缺粮与运输困难使行军本身成为生死考验。海上接应保留了继续作战的力量，也说明盟国援助即使未能保住领土，仍可能影响国家未来。","库特方向的困难则来自另一种延伸：部队沿河流深入，需要河船、医疗与补给跟上。战斗受挫后，退回一座城并不等于获得安全，外围敌军一旦截断运输，营地就可能变为牢笼。","美索不达米亚方向，英印军在泰西封附近与奥斯曼军交战后退回库特。向巴格达推进的野心超出当地补给承受力，一次远征的边界开始显露。"],"perspectives":[{"country":"rs","text":"撤退也是继续抵抗的艰难选择，代价主要由军民承担。"},{"country":"uk","text":"帝国部队能推进多远，取决于河运、医疗和补给，而非地图上的箭头。"}],"sources":[{"id":"nam15","locator":"1915-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-11相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十月的巴尔干夹击和两河推进，在十一月分别变成撤退与回撤。","after":"十二月将形成鲜明对照：一支远征军撤离半岛，另一支开始被围。"},"relatedBattles":[]},{"id":"ww1-1915-12","date":"1915-12","title":"从加里波利撤离，在库特陷入围困","theaters":["中东","西线"],"countries":["uk","fr","ot"],"people":["伊恩·汉密尔顿","黑格"],"story":["协约国开始撤出加里波利的安扎克与苏夫拉阵地。数月消耗没有打开海峡，撤离意味着承认原计划失败；直到次年1月，半岛撤退才全部完成。","加里波利撤退需要掩饰兵力减少、安排船运并避免守军追击，组织得当使许多部队得以脱离。承认战略失败与完成一次复杂撤离并不矛盾，保存的人员此后仍能投入其他战区。","库特则在相反方向收紧：被围部队依靠有限储粮等待解救，外围军队必须沿受限制路线攻击。等待时间越长，食物、疾病与士气越难维持，解围的成本也会不断增加。","库特的英印军却在此时遭到围困，救援成为另一项艰难任务。西线黑格接替弗伦奇指挥英国远征军，来年的大规模进攻开始酝酿，指挥更替并没有使战争的结构性困局消失。"],"perspectives":[{"country":"ot","text":"成功抵御半岛进攻，同时继续在两河战场争夺主动。"},{"country":"uk","text":"结束一处远征时又需解救另一处被围部队，资源分配愈加困难。"}],"sources":[{"id":"nam15","locator":"1915-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam15deep","locator":"1915-12相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十一月已暴露两处远征的补给与战略边界，十二月必须处理后果。","after":"进入1916年，结束一处战场不能消除人力危机，英国转向更深的国内动员。"},"relatedBattles":[]},{"id":"ww1-1916-01","date":"1916-01","title":"撤离完成，征兵进入英国政治","theaters":["中东","后方"],"countries":["uk","ot"],"people":["阿斯奎斯"],"story":["加里波利最后一批协约国军撤走，奥斯曼守住海峡。英国原本希望通过侧翼远征改变战争，最终不得不把经历失败的部队和资源重新安排到其他方向。","英国此前依靠志愿报名扩大陆军，但战时工厂也需要熟练工人。把更多男子送往前线，并不总能增加整体战争能力，因为军队还要依赖留下的人生产炮弹、修船、运输和维持粮食供应。","强制征兵因此牵涉谁被征召、谁可豁免以及反战者如何被对待。动员将国家权力伸进职业、家庭与信仰领域，战争的持续不只改变军队规模，也改变公民必须承担什么义务。","英国通过军事服役法，逐步转向强制征兵。志愿报名已不足以持续支持大规模战争，国家与个人的关系随之改变；战斗力来自前线，也来自家庭、工厂和政府动员的承受限度。"],"perspectives":[{"country":"uk","text":"人员补充由个人志愿进一步转向国家强制。"},{"country":"ot","text":"海峡胜利提高信心，却没有解除高加索和两河压力。"}],"sources":[{"id":"nam16","locator":"1916-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"加里波利撤退保存了部分人员，却没有填平长期战争的人力缺口。","after":"二月凡尔登开战后，人员轮换与后方运输的重要性将更加明显。"},"relatedBattles":[]},{"id":"ww1-1916-02","date":"1916-02","title":"凡尔登：一座要塞城市为何成为消耗中心","theaters":["西线","东线"],"countries":["fr","de","ru","ot"],"people":["法尔肯海因","贝当"],"story":["21日，德军进攻凡尔登，猛烈炮火之后向法国阵地推进，杜奥蒙堡很快失守。法国组织增援与轮换，贝当参与稳住防御，补给道路成为维持战斗的生命线。","杜奥蒙堡失守使法国防御面临更大压力，围绕凡尔登的道路、山脊与堡垒都成为焦点。法国通过连续运输和部队轮换维持抵抗，让这场战斗不只由最早进入阵地的守军承担。","德军火力可以摧毁地表，却不能确保每一处隐蔽工事都失去作用。双方不断投入增援，进攻目的逐渐被守住声望、回应对手行动和避免此前牺牲白费的压力包围，撤出竞争变得越来越困难。","凡尔登的象征意义使撤退更难被接受，战斗由争夺要塞扩大为持续消耗。德方作战意图的具体解释仍有讨论，但两军实际陷入的兵员与炮弹消耗十分明确。同期俄军夺取埃尔祖鲁姆，奥斯曼高加索防线承压。"],"perspectives":[{"country":"fr","text":"保卫本土与军队士气叠加，补给和轮换关系到能否坚持。"},{"country":"de","text":"未能以一次猛攻结束战斗，必须不断追加资源维持压力。"}],"sources":[{"id":"nam16","locator":"1916-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"verdun","locator":"1916-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"西线长期僵持，双方都试图用集中火力和不断投入增援争取突破，凡尔登即将承受这一轮压力。","after":"战斗不会在一座堡垒易手后结束，三月争夺会扩到默兹河两岸。"},"relatedBattles":[]},{"id":"ww1-1916-03","date":"1916-03","title":"凡尔登两岸与库特救援","theaters":["西线","中东"],"countries":["fr","de","uk","ot"],"people":["贝当","汤森德"],"story":["凡尔登战斗向默兹河两岸扩大，山丘与村庄成为反复争夺的位置。防守不只是留在原地，部队还要轮换、修复阵地、运入弹药并把伤员送出。","默兹河两岸互相影响，守住一边的炮兵能够打击另一边的进攻路线。德军因而不能只沿单一轴线向城内推进，法国也必须把增援送到不断扩大的防御正面。","库特救援部队面对的不是一片可以自由展开的平原，而是被河道、堤岸和防御阵地限制的路线。正面进攻受挫之后，能够留给城内守军的时间更少，医疗与粮食困难开始左右军事决定。","美索不达米亚方向，英军又一次救援库特失败。战壕中的炮火和远征军的饥饿看似相距遥远，却共同显示工业战争的底层问题：战斗单位能否持续得到人、粮食、运输和医疗支持。"],"perspectives":[{"country":"fr","text":"防御强度取决于后方运输与军队组织。"},{"country":"uk","text":"解围攻势未能接通补给，被围部队的时间越来越少。"}],"sources":[{"id":"nam16","locator":"1916-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"二月两个战场都未得到速决，三月进一步证明补给与地形会反过来塑造目标。","after":"四月库特将走到投降，西线的持续抵抗则继续迫使盟友考虑援助行动。"},"relatedBattles":[]},{"id":"ww1-1916-04","date":"1916-04","title":"库特投降，爱尔兰起义：后方也在裂变","theaters":["中东","后方"],"countries":["uk","ot"],"people":["汤森德"],"story":["29日，库特被围英印军投降，英国的两河远征遭到严重挫折。投降之后的押送与战俘处境也属于战争历史，军队从战场消失并不意味着人员苦难随之结束。","库特被围者的结局，牵动英国在帝国内的声望，也引发对远征指挥和医疗准备的追问。一次失败不只损失军队，还会迫使组织检查自己为何让部队深入到难以持续供给的位置。","都柏林起义又显示战时国家面对的并非只有外部敌人。镇压可以在短期内恢复控制，处决和强制行动却可能改变更广泛的公众态度，使军事上的平定变成政治上长期的不稳定。","爱尔兰发生复活节起义，英国镇压及随后处决引起深远反响。对政府而言是战时安全问题，对民族主义者而言则是独立诉求；帝国在海外动员兵员时，本身的统治关系也受到挑战。"],"perspectives":[{"country":"uk","text":"必须同时处理海外战败和帝国内部反抗。"},{"country":"ot","text":"库特获胜暂时稳住两河局面，但英国此后仍会重新组织进攻。"}],"sources":[{"id":"nam16","locator":"1916-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"三月救援失败使库特处境难以逆转，战争也在帝国后方激起新的反抗。","after":"五月舰队与意大利战线都将试图改变局势，联盟仍未找到结束消耗的出口。"},"relatedBattles":[]},{"id":"ww1-1916-05","date":"1916-05","title":"日德兰：舰队交战，没有改写封锁","theaters":["海战","意大利"],"countries":["uk","de","it","ah"],"people":["杰利科","舍尔"],"story":["31日，英国大舰队与德国公海舰队在日德兰附近展开主力交锋。侦察、信号和舰队机动决定着交战机会，双方均有舰艇沉没，胜负不能仅用某一类损失数字判断。","日德兰交战中，侦察舰队与主力舰队并不总能共享同一幅战场图景。烟雾、距离、信号与对敌位置的判断，影响指挥官何时集中舰队、何时转向避险，海战不能只按舰炮口径解释。","主力舰队保留下来，意味着英国仍能维持对德国的海上压力；德国舰队未被消灭，却也难以自由改变北海交通。这种持续存在的威胁与封锁，比一日战果更直接影响接下来的粮食、原料与潜艇战略。","战斗延续到6月，德国舰队返回基地，英国总体海上控制与封锁仍然存在。意大利战线又遭奥匈特伦蒂诺攻势，协约国需要通过不同战场的行动互相减压。"],"perspectives":[{"country":"de","text":"战术战果未能打破英国对北海交通的总体控制。"},{"country":"uk","text":"保存并运用海军优势，比单次交锋的胜负宣称更影响长期战争。"}],"sources":[{"id":"nam16","locator":"1916-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"四月的陆上困局促使各方继续期待其他方向的突破，海战仍未给出速决。","after":"六月俄军大攻势尝试分担意大利等方向压力，再次把多战场协调推向前台。"},"relatedBattles":[]},{"id":"ww1-1916-06","date":"1916-06","title":"布鲁西洛夫攻势与阿拉伯起义","theaters":["东线","中东"],"countries":["ru","ah","de","ot","uk"],"people":["布鲁西洛夫","侯赛因"],"story":["4日，俄军布鲁西洛夫攻势在广阔正面展开，对奥匈阵地造成重大打击。准备与攻击方式改进带来突破，但继续利用成果仍依赖预备队、交通和其他方向的配合。","布鲁西洛夫在较广正面组织准备，避免只把一处显眼目标暴露给对手，俄军因此在若干方向取得突破。奥匈不得不依靠德国增援，原本用于其他战区的力量又被重新牵动。","阿拉伯起义的目标与英国支持并非完全一致。地方独立愿望、奥斯曼统治、战时承诺与英法对中东的设想交织，战场合作既可能削弱帝国，也可能把战后冲突提前埋入盟约之中。","阿拉伯起义在汉志展开，侯赛因方面反抗奥斯曼统治，并与英国发生合作。战时独立承诺、帝国利益和地方政治从此纠缠，不能把阿拉伯社会的不同选择简化为单一阵营。"],"perspectives":[{"country":"ru","text":"军事成功短期提振局势，却无法消除国家长期积累的危机。"},{"country":"ot","text":"欧洲与中东压力叠加，帝国既面对外敌，也面对统治内部的反抗。"}],"sources":[{"id":"nam16","locator":"1916-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"五月意大利战线承压，俄军攻势成为联盟互相减压的一次重要行动。","after":"凡尔登仍在消耗法国，七月索姆河攻势将在同一逻辑下承担更大期待。"},"relatedBattles":[]},{"id":"ww1-1916-07","date":"1916-07","title":"索姆河：炮击之后，突破没有如期到来","theaters":["西线"],"countries":["uk","fr","de"],"people":["黑格","罗林森"],"story":["1日，英法联军在索姆河发动进攻，意在突破德军阵地并缓解凡尔登压力。长时间炮击未能彻底摧毁深层防御，许多进攻部队走入仍可射击的机枪和炮火范围。","索姆河之所以被选中，也因为它位于英法军队相接的地区，有利于共同进攻。但凡尔登消耗法军，使英国承担比最初设想更重的任务，新编部队被推向工业火力最密集的战场。","炮击与步兵之间存在艰难的时间配合：炮火过早移走，守军可能重新进入射击位置；步兵跟得过近，又有遭己方炮火伤害的危险。铁丝网是否被打开、地下掩蔽部是否仍完整，都影响进攻者跨出阵地后面对什么。","此后攻击转向更有限的目标，炮兵、侦察和步兵协同不断改进。每一次学习都伴随人员损失，理解这些调整可以解释战争为何改变，却不能让此前造成的灾难被事后胜利抹平。","英国军队首日损失极其严重，法军在部分地段取得进展，但整个战线没有出现预想中的快速崩溃。进攻继续，目标逐渐转为争夺村庄、高地和磨损对手，战场行动与原先许诺的结果之间出现巨大距离。","索姆河将新组建军队、工业火力与指挥协同的问题集中暴露。理解它，不只应记住首日灾难，也要追踪为何明知代价高昂仍继续投入，以及后续战术究竟怎样调整。"],"perspectives":[{"country":"uk","text":"志愿军的大规模投入使损失直接进入众多家庭和地方社会。"},{"country":"de","text":"坚固防御承受持续压力，也需不断补充守军，消耗并非只有进攻方承担。"}],"sources":[{"id":"nam16","locator":"1916-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"六月多战场进攻未使法国脱离凡尔登消耗，索姆河承担了援助与突破的双重目标。","after":"八月新盟友参战、德国统帅更替，都会受到这一轮巨大消耗的影响。"},"relatedBattles":[]},{"id":"ww1-1916-08","date":"1916-08","title":"罗马尼亚入战与德国最高统帅更替","theaters":["东线","中东"],"countries":["ru","ah","de","uk","ot"],"people":["兴登堡","鲁登道夫"],"story":["罗马尼亚加入协约国，希望在战争中争取国家目标，却很快面对同盟国反击。新参战国打开一条战线，也需要盟友提供并不总能及时到达的支持。","德国新统帅部接手的是两线受压的局面，强化军需生产与劳动力安排，意味着更多社会活动都要为战争让路。生产目标提高并不自动解决粮食、运输和熟练工人的瓶颈。","罗马尼亚参战时，盟友期待新增军队牵制同盟国，但交通、装备与战略协同决定它能否承受反击。形式上扩大一个阵营的成员，可能同时增加该阵营必须保卫的脆弱方向。","兴登堡出任德国总参谋长，鲁登道夫权力上升；德国进一步强化战争动员。中东罗马尼战役中，奥斯曼进攻被击退，西奈方向的主动权逐步变化，多条战线同时索取有限资源。"],"perspectives":[{"country":"de","text":"军事领导层更替推动动员强化，战争与国内经济结合更深。"},{"country":"ru","text":"援助盟友又增加东线负担，局部胜利难以保证联盟整体稳定。"}],"sources":[{"id":"nam16","locator":"1916-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"索姆河与东线攻势的消耗加剧资源竞争，各国试图用新领导或新盟友回应。","after":"九月坦克参战带来技术希望，却仍受同样的组织与资源约束。"},"relatedBattles":[]},{"id":"ww1-1916-09","date":"1916-09","title":"坦克首次参战，技术尚不能独立取胜","theaters":["西线"],"countries":["uk","fr","de"],"people":["黑格"],"story":["15日，英军在索姆河的弗莱尔—库尔瑟莱特作战中首次把坦克投入战场。一些车辆帮助步兵突破，另一些却因故障、地形和行动困难未能发挥预期作用。","早期坦克内部炎热、视野受限，机械可靠性和跨越障碍的能力也有限。步兵如果依赖一辆中途停下的车辆，仍可能暴露在守军火力下，新的装备因此需要相应训练与配合方法。","有限成功给指挥官看到防御可能被打破的希望，但大量生产、维修和人员培训都需要时间。把第一次使用与后来成熟的装甲作战连成毫无波折的进步线，会错过军队在失败中调整的漫长过程。","坦克带来新可能，但数量、可靠性和步炮协同还不足以结束僵局。把它写成突然改变一切的奇迹，会遮蔽驾驶、维修、补给以及配合战术的长期磨合。"],"perspectives":[{"country":"uk","text":"试验新武器的同时，必须承受技术尚未成熟的局限。"},{"country":"de","text":"防御者面对新威胁，也在寻找火炮、障碍和战术应对。"}],"sources":[{"id":"nam16","locator":"1916-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"八月仍在追加军需与人力，九月尝试用新装备改善突破的条件。","after":"技术没有立即结束战斗，十月仍要靠炮兵准备和步兵反攻争夺具体要地。"},"relatedBattles":[]},{"id":"ww1-1916-10","date":"1916-10","title":"杜奥蒙堡收复，胜利被拆成小块","theaters":["西线"],"countries":["fr","de","uk"],"people":["尼韦尔","贝当"],"story":["法军反攻收复杜奥蒙堡，凡尔登方向的力量变化开始显现。曾经象征巨大危机的要塞重新易手，但收复据点并没有抹去此前数月的人命损失。","法军收复杜奥蒙堡，把火力准备与步兵行动结合起来，说明防线并非永远无法移动。真正困难的是这种成功能否被重复、能否扩大，以及下一次行动需要多少人员和弹药。","凡尔登与索姆河也在互相牵动德国预备队。一处阵地的坚守，可能意味着另一处兵力不足；战场上的主动与被动，常常不是当地指挥官单独能够决定的。","索姆河仍在艰苦推进，有限地段的得失成了作战成果的主要单位。战争评价也因而困难：战术进展、对敌消耗、己方损失和社会承受力，未必指向同一个答案。"],"perspectives":[{"country":"fr","text":"收复阵地改善战场与士气，却需要面对军队疲惫。"},{"country":"de","text":"在凡尔登与索姆河持续承压，防守同样消耗大量资源。"}],"sources":[{"id":"nam16","locator":"1916-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"九月的新装备只是尝试之一，十月的反攻继续依赖多兵种与战区间力量分配。","after":"进入十一月，攻势能否继续将越来越受天气、疲惫和国家政治变化影响。"},"relatedBattles":[]},{"id":"ww1-1916-11","date":"1916-11","title":"索姆河落幕，帝国开始寻找出口","theaters":["西线","后方"],"countries":["uk","fr","de","ah"],"people":["弗朗茨·约瑟夫一世","卡尔一世"],"story":["索姆河攻势在11月结束，没有实现决定性突破。战线移动有限，军队却被重新塑造：炮兵、步兵、侦察和后勤的协同经验，在巨大损失中逐步积累。","秋冬地面状况恶化，运送炮弹、拖曳火炮与救护伤员都更加困难。停止进攻并不是承认此前一切毫无价值，而是对下一次投入是否还能取得相称成果的重新判断。","奥匈王位更替又带来另一种时间压力：新君继承的战争已经深刻改变经济和各民族关系，维持联盟需要德国支持，寻求和平又可能触动盟友利益，帝国越来越难独立选择自己的出口。","奥匈皇帝弗朗茨·约瑟夫去世，卡尔一世继位。长期战争加重粮食和民族关系压力，新君面对的是一个必须依赖盟友、又越来越难承受战争的帝国。"],"perspectives":[{"country":"uk","text":"需要解释投入与成果之间的落差，并准备下一年的行动。"},{"country":"ah","text":"王位更替无法自动修复社会、经济和多民族统治的裂缝。"}],"sources":[{"id":"nam16","locator":"1916-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"十月仍有局部反攻成果，十一月却必须面对继续作战的物质与政治限度。","after":"十二月军政领导层继续调整，平民饥饿让这些限度从前线蔓延到社会。"},"relatedBattles":[]},{"id":"ww1-1916-12","date":"1916-12","title":"凡尔登结束，饥饿延续","theaters":["西线","后方"],"countries":["fr","de","uk"],"people":["劳合·乔治","尼韦尔"],"story":["凡尔登的大规模战斗阶段告终，法军收复部分失地。两军在这一年投入的人力与火力，已使战争远离最初设想的短期决战。","粮食短缺不是只有封锁一个原因，还与收成、肥料、劳动力流失及运输分配有关。国家可以优先保障军队，却不能让城市居民无限期在匮乏中维持生产与信任。","凡尔登结束后，法国需要整顿部队并筹备来年行动。新的统帅仍承受取得决定性突破的期待；如果没有正视战场的实际限制，更换领导人也可能重复给士兵过高承诺的过程。","劳合·乔治成为英国首相，法国也调整军事指挥。德国平民进入食品匮乏的严冬，封锁、农业困难和分配问题叠加；战争的承受力，越来越取决于战壕之外的人是否还能继续生活。"],"perspectives":[{"country":"de","text":"后方粮食危机削弱社会承受力，不能被前线宣传取代。"},{"country":"uk","text":"领导层希望改善战争统筹，仍需协调陆军、海军、工业与盟友。"}],"sources":[{"id":"nam16","locator":"1916-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"十一月攻势停顿与帝国政治变化之后，战争的社会成本越来越难隐藏。","after":"德国将把解决困境的希望更多押在潜艇上，1917年初的决策由此更冒险。"},"relatedBattles":[]},{"id":"ww1-1917-01","date":"1917-01","title":"一封电报与潜艇战争的赌注","theaters":["外交","海战"],"countries":["de","us","uk"],"people":["齐默尔曼","威尔逊"],"story":["德国决定恢复无限制潜艇战，希望在美国形成有效军事力量之前切断英国海运。它把争取时间与冒险扩大敌人绑在一起，海上战略成为一场政治赌博。","德国担心美国终将加入战争，于是试图抢在美军形成力量之前击垮英国。这一判断把尚未发生的危险当作必须立即冒险的理由，短期胜利的希望反而推动国家主动扩大敌人。","齐默尔曼电报涉及墨西哥与美国边境问题，将欧洲战争与美洲安全连接起来。英国掌握电报后，也必须处理怎样公开而不暴露情报能力的问题，信息并非一经截获就会自动产生政治效果。","齐默尔曼电报向墨西哥提出在美德开战时合作的设想，被英国截获并在随后公开。美国舆论对德国意图的认识进一步改变，但从愤怒到宣战仍要经过国内政治程序。"],"perspectives":[{"country":"de","text":"寄望潜艇先迫使英国屈服，低估了长期增加敌手的风险。"},{"country":"us","text":"仍在中立与介入之间权衡，本土安全与海上权益逐渐连在一起。"}],"sources":[{"id":"nam17","locator":"1917-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-01相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"1916年的消耗与饥饿没有解决，德国领导层希望从海上找到更快的出口。","after":"二月无限制潜艇战实施后，风险将从设想变为美国断交与商船损失。"},"relatedBattles":[]},{"id":"ww1-1917-02","date":"1917-02","title":"海运遭袭，旧外交关系断裂","theaters":["海战","外交"],"countries":["de","us","uk"],"people":["威尔逊"],"story":["德国从2月起实施无限制潜艇战，不再按原有限制对待许多航区内船舶，美国与德国断交。商船、粮食与燃料成为战争手段的直接目标，海运损失关系到英国能坚持多久。","潜艇袭击使英国必须把海军任务从寻找敌主力舰，进一步转向保护分散的运输船。护航需要组织出发时间、航路、舰艇和港口，商船主与海军的习惯也要改变，这不是一种装备即可完成的转型。","美国断交保留了最后一段外交距离，却没有消除海上冲突。每一艘继续航行的美国商船，都可能使政策争论获得新的伤亡证据，德国的短期赌博正在不断扩大政治后果。","此时美国尚未正式参战，英国也不能只等待援助。护航、反潜和运输组织逐渐成为回应，技术与制度的组合，比单纯计算潜艇数量更能说明后来的变化。"],"perspectives":[{"country":"uk","text":"海上生命线承压，必须保护贸易船队。"},{"country":"us","text":"断交并非宣战，但已显著缩小恢复正常关系的空间。"}],"sources":[{"id":"nam17","locator":"1917-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-02相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"一月德国已决定押注潜艇，二月开始承受军事行动反噬外交的结果。","after":"三月俄国革命改变另一条战线，协约国将同时面对新希望与新危机。"},"relatedBattles":[]},{"id":"ww1-1917-03","date":"1917-03","title":"俄国革命与德国后撤","theaters":["东线","西线","后方"],"countries":["ru","de","fr","uk"],"people":["尼古拉二世","克伦斯基"],"story":["俄国首都抗议、粮食困难与军队反应汇聚，尼古拉二世退位，临时政府成立。按俄国旧历称二月革命，按公历主要发生在3月；名称与日期口径必须区分。","俄国首都的示威与罢工得到部分士兵响应，使政府失去只靠武力恢复秩序的条件。退位之后，临时政府与工兵代表苏维埃等力量并存，谁能代表国家、谁能控制军队并没有立刻得到统一答案。","德军退向兴登堡防线则是主动缩短防守正面，而非仓促溃逃。毁坏道路、水井与建筑，让追击者即使得到土地也难以马上利用，平民又为这类有计划的军事调整付出代价。","西线德军主动退到兴登堡防线，缩短战线、加强防御，也在撤退中破坏设施并迁移居民。俄国革命没有立即结束其参战，西线后撤也不等于德国接受失败，各方仍在重新配置战争。"],"perspectives":[{"country":"ru","text":"新政府继承战争与社会诉求，继续作战的决定将面临考验。"},{"country":"de","text":"用有计划后撤改善防守条件，把空间换成兵力和工事优势。"}],"sources":[{"id":"nam17","locator":"1917-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-03相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"二月大西洋冲突仍在扩大，三月俄国政治崩溃又打乱了盟国联合进攻的预期。","after":"四月美国参战增加长期力量，但法国攻势与俄国政治将让近期形势依旧危险。"},"relatedBattles":[]},{"id":"ww1-1917-04","date":"1917-04","title":"美国参战，法国攻势受挫","theaters":["外交","西线"],"countries":["us","fr","uk","de","ru"],"people":["威尔逊","尼韦尔","列宁"],"story":["6日美国对德国宣战，潜艇袭击与外交冲突终于转化为正式战争。美国的工业、金融与兵员潜力重要，但部队训练、运输和投入前线仍需时间，不能把宣战日当作美军已经全面到场。","英国在阿拉斯、加拿大部队在维米岭等处取得部分战术成果，炮兵定位与有限目标作战有所改善。法国在埃纳河的主要进攻却未达到预期，说明同一场联合行动的各部分可能产生很不相同的结果。","尼韦尔承诺的快速突破落空后，士兵的不满不只是抽象厌战，也针对不断重复的无望攻击。美国宣战带来的希望尚在未来，法国眼前必须先保住一支愿意并能够继续防守的军队。","法国尼韦尔攻势未能实现许诺的突破，严重伤亡引发军队不满，之后出现哗变。列宁返回俄国，主张与临时政府不同的政治路线；联盟力量增加的同时，旧成员的内部稳定却在动摇。"],"perspectives":[{"country":"us","text":"必须把参战决议转换为军队、运输和动员体系。"},{"country":"fr","text":"军队拒绝无望进攻的情绪，需要通过指挥调整、休整和待遇改善应对。"}],"sources":[{"id":"nam17","locator":"1917-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-04相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"三月的俄国革命削弱联合进攻前景，四月协约国试图在西线取得决定性成果。","after":"失败引发的军心危机会在五月迫使法国改变继续战争的方法。"},"relatedBattles":[]},{"id":"ww1-1917-05","date":"1917-05","title":"军心、护航与继续战争的条件","theaters":["西线","海战"],"countries":["fr","uk","us","de"],"people":["贝当"],"story":["贝当接掌法国军队指挥，面对的首要问题是恢复信任与作战秩序。他限制缺乏把握的大规模进攻，改善休假和补给，同时维持军纪，军队危机不能只靠一纸命令解决。","许多参与哗变的部队并非拒绝防守法国，而是拒绝继续投入缺乏前景的进攻。把这种复杂反应一律写成怯懦或背叛，会错过士兵对指挥可信度的判断，以及部队在疲惫中仍然保持的边界。","贝当通过休整、休假、供给与军纪等多种方式处理危机。英国扩大护航也同样依赖制度协调：战时韧性不是要求每个人无条件坚持，而是让组织真正改善继续承担风险的条件。","大西洋护航逐步扩大使用，把商船组织成有保护的船队。战争的关键不总是新的决战，也可能是让运输损失降下来、让部队愿意继续执行任务的制度改变。"],"perspectives":[{"country":"fr","text":"保存军队与恢复士气成为争取未来行动能力的前提。"},{"country":"uk","text":"保障粮食和物资抵达，比单次击沉敌艇更关系长期生存。"}],"sources":[{"id":"nam17","locator":"1917-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-05相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"四月过高承诺与重大损失破坏了信任，五月首先需要修复可持续作战的基础。","after":"六月的有限目标进攻与美军到来，将提供更务实的未来选择。"},"relatedBattles":[]},{"id":"ww1-1917-06","date":"1917-06","title":"梅西讷：有限目标能否换来可靠成果","theaters":["西线"],"countries":["uk","de","us"],"people":["普卢默","潘兴"],"story":["英军在梅西讷通过长期准备的地道爆破、炮火与步兵协同夺取高地。行动目标相对有限，成果显示精心准备能够改善战术表现，却并未证明西线整体突破已经容易实现。","梅西讷的行动围绕可准备、可控制的目标展开，地道爆破与后续火力配合服务于夺取高地，而不是许诺一举结束战争。其成果使人看到，进攻并非只能在全面失败与奇迹突破之间二选一。","美军抵达后还要建立营地、仓库、铁路和训练体系，潘兴也重视保持美国部队的独立组织。盟国需要共同作战，却并不天然同意怎样分配指挥权和何时让新部队上阵。","美军人员开始抵达法国，潘兴建立远征军体系。新力量需要训练、装备与组织，联盟也需决定美军如何与既有部队协同，未来的优势正在形成，尚未全部兑现。"],"perspectives":[{"country":"uk","text":"有限目标作战提供经验，随后是否扩大攻势仍是另一项判断。"},{"country":"us","text":"从抵达欧洲到形成独立作战能力，需要跨越漫长的后勤与训练过程。"}],"sources":[{"id":"nam17","locator":"1917-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"五月的整顿为保存力量争取空间，六月开始探索有限成功与新增兵力的结合。","after":"七月俄军再度进攻和佛兰德新攻势，仍会检验这些经验是否被真正吸收。"},"relatedBattles":[]},{"id":"ww1-1917-07","date":"1917-07","title":"俄军攻势失败，佛兰德再度开战","theaters":["东线","西线"],"countries":["ru","de","uk","fr"],"people":["克伦斯基","黑格"],"story":["俄国临时政府发动新的攻势，未能扭转战局，军队瓦解和社会不满进一步扩大。继续战争的政策与民众对和平、土地和生活的要求越来越难调和。","俄国临时政府希望用军事进展恢复信誉，士兵与社会的期待却更多指向结束战争。攻势受挫使政府无法兑现任何一端，前线纪律、政治信任和国家供给之间的裂缝继续扩大。","佛兰德炮击破坏排水系统后，弹坑与积水影响步兵、坦克和运输。战场不是一张保持不变的地图，军队自己的火力也在改变接下来必须穿越的环境，作战计划需要不断回应这种反馈。","31日，第三次伊普尔战役开始。英军希望向比利时方向推进，炮火破坏排水后，降雨与地形逐步加重困难。准备突破的战场，正变成既消耗军队又阻碍运输的泥泞空间。"],"perspectives":[{"country":"ru","text":"军事失利削弱临时政府合法性。"},{"country":"uk","text":"战略目标必须通过极为不利的地形和补给条件才能实现。"}],"sources":[{"id":"nam17","locator":"1917-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-07相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"六月的局部改进没有消除更大规模进攻的诱惑，七月两处攻势再次暴露承受力问题。","after":"八月中国参战与跨国劳工投入，将使人看到大战所依靠的全球人力网络。"},"relatedBattles":[]},{"id":"ww1-1917-08","date":"1917-08","title":"中国参战，世界战争中的弱国处境","theaters":["外交","西线"],"countries":["cn","de","ah","uk","fr"],"people":["段祺瑞"],"story":["14日，中国对德国、奥匈宣战。参战既与国内政治有关，也包含争取战后国际地位、处理列强权益的期待。此前和此后赴欧的华工承担运输、修筑与清理等繁重劳动，是中国参与战争的重要部分。","华工在欧洲并非都承担同一种工作，也并非都在中国正式参战后才出发。修路、搬运、工场劳动以及战后清理等任务，使他们进入军需体系，却往往没有获得与贡献相称的叙述位置。","中国的参战决策还受到国内权力关系影响。希望借国际参与处理列强在华权益，与能否在战后获得平等对待不是一回事；国家外交、劳工经历和山东问题，要放在同一条线索中观察。","佛兰德攻势仍在继续，华工与帝国劳工在战线后方维持战争机器。国家宣布加入胜方阵营，并不保证战后诉求会自动得到满足；中国的经历将延伸到巴黎和会及山东问题。"],"perspectives":[{"country":"cn","text":"参战被寄予改善国际地位的希望，实际谈判能力仍受强权关系限制。"},{"country":"uk","text":"前线依赖跨国劳工体系，战争贡献并不限于持枪作战。"}],"sources":[{"id":"nam17","locator":"1917-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1917-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-08相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"七月战场继续吞噬人力，八月的新参与者显示后方劳工同样支撑前线。","after":"九月仍有局部战术推进，而俄国内部的权力危机正在进一步积累。"},"relatedBattles":[]},{"id":"ww1-1917-09","date":"1917-09","title":"有限推进与和平希望的破灭","theaters":["西线","东线"],"countries":["uk","de","ru"],"people":["普卢默","克伦斯基"],"story":["英军在第三次伊普尔的部分阶段采取有限目标推进，在梅宁路等处获得局部成果。战术调整可以减少某些困难，却无法让已经破坏的地形、持续伤亡和总目标之间的矛盾消失。","英军在梅宁路等行动中强调炮兵掩护与有限推进，试图避免步兵跑出支援范围。这样的做法能够改善部分战斗，却也要求运输把火炮和弹药不断送到新的出发位置，推进速度不可能无限加快。","俄国军政冲突则进一步削弱临时政府对秩序的控制。主张继续战争的人必须解释为何仍有胜利希望，主张退出的人也要回答如何应对敌军，政治口号正走向即将发生的现实抉择。","俄国经历科尔尼洛夫事件，临时政府与军队高层的冲突加深，布尔什维克影响上升。战争的结局正被军队内部、城市政治和后方供给共同改变，而不只取决于前线谁又占领一处阵地。"],"perspectives":[{"country":"uk","text":"局部进展仍需接受成果与代价的比较。"},{"country":"ru","text":"政治权威继续分裂，维持原有战争路线更加困难。"}],"sources":[{"id":"nam17","locator":"1917-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-09相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"八月的全球动员并未修复俄国危机，也没有让佛兰德轻易脱离泥泞。","after":"十月意大利防线崩开，将把联盟的有限预备队再拉向一个新方向。"},"relatedBattles":[]},{"id":"ww1-1917-10","date":"1917-10","title":"卡波雷托：一条战线突然崩开","theaters":["意大利","西线"],"countries":["it","ah","de","uk","fr"],"people":["卡多尔纳","迪亚兹"],"story":["24日，德奥军在卡波雷托发起进攻，意军防线遭到突破。部队快速后撤，民众流离失所，失败不只是战术问题，也暴露指挥、士气和组织体系的脆弱。","卡波雷托的突破利用山地通道、突然性和对薄弱环节的攻击，意军一些部队在失去联系后难以统一行动。退却时军队、车辆与居民挤向有限道路，局部失败因组织失序而迅速放大。","指挥更替和盟军援助帮助意大利重建防线，但援军从别处调来，也会影响西线与其他计划。所谓联盟资源是一张相互牵动的网，一条线崩紧，其他方向就必须重新计算风险。","意大利随后退到皮亚韦河方向，协约国增援帮助稳定局面。佛兰德战斗仍在继续，加拿大等部队参与帕斯尚达尔攻坚；同一联盟内部，一处成功也无法补偿另一处突然出现的危机。"],"perspectives":[{"country":"it","text":"保住军队与重新组织防御比继续争取领土更迫切。"},{"country":"ah","text":"借德军协同取得突破，却未能一举迫使意大利退出战争。"}],"sources":[{"id":"nam17","locator":"1917-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-10相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"九月仍在追求局部改进，十月的突然崩溃提醒盟军不能只盯住自己希望突破的方向。","after":"十一月最高战争委员会的建立，正是在这些协调困难下寻求更统一的回应。"},"relatedBattles":[]},{"id":"ww1-1917-11","date":"1917-11","title":"革命、坦克与盟军新协调","theaters":["东线","西线","外交"],"countries":["ru","de","uk","fr","it"],"people":["列宁","克列孟梭","黑格"],"story":["布尔什维克在俄国夺取政权，主张退出战争；十月革命的名称采用旧历，主要行动按公历在11月。新政权开始推动和平交涉，东线力量配置即将变化。","康布雷把坦克集中到适宜地形，配合较短准备炮击，试图保留突然性。最初的推进表明强固防线可以被穿入，后续预备队、通信与火力却未能保证持续扩大战果。","德国反攻也利用渗透与快速突击恢复局面，又遇到把增援送进复杂战场的同类困难。两军正在从对方和自身失败中学习，1918年恢复机动的部分方法，就在这些反复试验中逐步形成。","英军在康布雷集中使用坦克，一度突破德国防御，德军反攻又收回大片阵地。法国克列孟梭执政，盟国建立最高战争委员会；技术创新和政治协调都重要，却都无法独立替代持续作战能力。"],"perspectives":[{"country":"ru","text":"和平承诺必须在德国压力、国内革命和国家生存之间兑现。"},{"country":"fr","text":"希望加强联盟统筹，准备应对俄国退出后的兵力变化。"}],"sources":[{"id":"nam17","locator":"1917-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-11相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十月意大利危机推动联盟协调，俄国政治与西线技术变化又同时重塑战争。","after":"十二月俄德停战将释放德国的希望，也把康布雷展示的新战法带进最后攻势的准备。"},"relatedBattles":[]},{"id":"ww1-1917-12","date":"1917-12","title":"东线停战，耶路撒冷易手","theaters":["东线","中东"],"countries":["ru","de","uk","ot"],"people":["列宁","艾伦比"],"story":["俄德签订停战安排，谈判进一步展开。德国开始看到从东线腾出力量的可能，俄国则希望结束军队与社会无法继续承受的战争。停战仍不等于已有可接受的最终和平条件。","俄德停战并没有让谈判双方拥有对等地位。俄国军队的疲惫与国内政治压力，使新政权难以用继续作战作为可靠筹码，德国则希望把军事优势转为领土和战略收益。","英军进入耶路撒冷后，如何管理占领地区、回应不同社群与战时承诺成为新问题。一个城市被夺取，既改变作战线路，也会把过去的外交承诺带到当地居民眼前，胜利并不减少政治责任。","英军进入耶路撒冷，巴勒斯坦战局改变。战争前景在两端同时变化：德国准备在西线争取机会，奥斯曼则在中东继续丧失主动，盟国的得失并不总能同步。"],"perspectives":[{"country":"de","text":"希望利用东线变化，在美国力量全面到达前改变西线。"},{"country":"ot","text":"领土与交通受压，帝国需要应对越来越不利的区域局势。"}],"sources":[{"id":"nam17","locator":"1917-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam17deep","locator":"1917-12相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十一月革命提出立即和平，十二月必须面对和平条件由谁决定。","after":"1918年一月的十四点原则，将以另一套语言争取和平与战争目标的解释权。"},"relatedBattles":[]},{"id":"ww1-1918-01","date":"1918-01","title":"十四点原则与欧洲社会的疲惫","theaters":["外交","后方"],"countries":["us","de","ru","uk","fr"],"people":["威尔逊"],"story":["威尔逊提出十四点和平原则，试图以公开外交、国际组织和民族问题安排构建战后秩序。它为和平赋予新语言，却没有消除各盟国在领土、赔偿和帝国利益上的差异。","十四点把公开外交、军备限制与国际组织纳入和平主张，却还需要处理具体边界和殖民利益。原则越普遍，各地受压迫群体越可能把它用于自身诉求，强国也就越难只在方便自己的地方兑现。","德国后方罢工表明军工产量不能脱离工人的食品、工资与政治信任。前线准备新攻势时，后方已经经历多年匮乏，国家对最后一轮动员的要求正在碰到社会的边界。","德国等地出现罢工与不满，俄德谈判也因苛刻条件陷入困境。前线仍在准备下一次攻势，后方却越来越追问战争还要持续多久，社会承受力成为战略的一部分。"],"perspectives":[{"country":"us","text":"以和平主张争取国际影响，并为美国参战解释目标。"},{"country":"de","text":"需要维持生产和兵员，后方不满使速胜愿望更加迫切。"}],"sources":[{"id":"nam18","locator":"1918-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"fourteen","locator":"1918-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-01相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十二月俄德谈判改变力量配置，一月各方也在争取对“怎样的和平”的主导。","after":"二月德国恢复东线进攻，将显示和平语言仍必须面对军事强弱的现实。"},"relatedBattles":[]},{"id":"ww1-1918-02","date":"1918-02","title":"谈判破裂后，德国再向东推进","theaters":["东线","外交"],"countries":["ru","de"],"people":["列宁","托洛茨基"],"story":["布列斯特谈判未能带来双方都可接受的条件，德国恢复进攻，俄国新政权面对更直接的军事危险。革命者关于战争与和平的分歧，此时必须接受军队战斗力和领土现实的检验。","俄方试图退出战争又不接受德国全部要求，但停止作战意愿并不能阻止对方继续前进。德军恢复进攻时，俄国新政权必须判断保存革命中心是否比继续控制边疆更紧迫。","接受和约的主张在布尔什维克内部也有分歧。这里的“和平选择”不是一张没有代价的选票，而是在军队失去战斗能力、国内仍不稳定时，对哪种损失能够承受的艰难比较。","列宁推动接受严苛和约，优先保住政权与喘息机会。退出大战并不意味着俄国社会获得稳定和平，国内战争和外部干预仍将延续，战场之间的边界并不整齐。"],"perspectives":[{"country":"ru","text":"在屈辱条件与继续无力作战之间作出艰难选择。"},{"country":"de","text":"利用军事优势扩大谈判要求，同时准备把主要机会押向西线。"}],"sources":[{"id":"nam18","locator":"1918-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-02相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"一月的和平主张没有消除谈判实力差距，二月把这种差距直接呈现在地图上。","after":"三月和约签订后，德国会把更大的赌注押向西线，但东部占领仍需兵力维持。"},"relatedBattles":[]},{"id":"ww1-1918-03","date":"1918-03","title":"布列斯特和约与德国春季攻势","theaters":["东线","西线"],"countries":["ru","de","uk","fr"],"people":["列宁","鲁登道夫","福煦"],"story":["3日，苏维埃俄国签署布列斯特—立托夫斯克和约，付出重大领土与政治代价退出对德战争。德国随后在21日发动西线春季攻势，试图在美军大量投入之前击败英法。","米夏埃尔攻势以强大炮击和突击部队攻击英军防线，试图利用部队衔接及较薄弱地段打开缺口。前沿据点可能被绕过，守军通信遭打断后，很难准确判断相邻部队是否仍在坚持。","德军深入后，火炮与补给车不易跟上，最先投入的精锐也不断损耗。与此同时，盟军在危机中把国家间协调推向更高程度，福煦的统筹作用逐步形成，进攻者与防御者都在边打边改造组织。","德军运用新的突击方式取得快速进展，英法面临严重危机。但突破之后，补给、预备队和明确战略目标仍然决定推进能否持续。盟国也在危机中加强统一指挥，福煦的统筹地位逐渐确立。"],"perspectives":[{"country":"de","text":"把时间压力转换为进攻压力，寄望最后的大规模机会。"},{"country":"uk","text":"必须保持与法军联系，避免撤退演变为联盟战线分裂。"}],"sources":[{"id":"nam18","locator":"1918-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-03相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"二月东线优势让德国期待腾出力量，三月试图在美国兵力成熟前取得西线决定性结果。","after":"四月将显示一次突破为何未能自动切断英法联系、迫使盟军结束战争。"},"relatedBattles":[]},{"id":"ww1-1918-04","date":"1918-04","title":"德军继续进攻，却离终局仍远","theaters":["西线"],"countries":["de","uk","fr","us"],"people":["鲁登道夫","福煦"],"story":["德军在利斯河方向继续进攻，英军和盟军承受巨大压力。前线重新出现大幅移动，战争似乎回到1914年的机动状态，但补给道路和部队损耗并未随战线移动而改善。","德军继续选择不同方向进攻，希望迫使盟军预备队顾此失彼。但每一次转换也需要重新组织炮兵、弹药与交通，战术上抢到时间，并不等于战略上能够不断免费重来。","英法军被迫后退时，仍力图保住彼此联系与关键交通节点。只要主要军队没有被消灭，退却就可能为整顿与增援创造空间；土地移动很大，战争的决定性条件却未必同样改变。","德国夺取土地，却难以把多次局部突破合成决定性结果。美国兵力持续增加，盟军统一协调也在加强；一方通过进攻消耗最后的精锐，另一方则在等待新增力量成熟。"],"perspectives":[{"country":"de","text":"攻击次数增加，能够用于下一轮作战的精锐却不断减少。"},{"country":"us","text":"运输与训练正把潜在资源转为逐步可用的战场力量。"}],"sources":[{"id":"nam18","locator":"1918-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-04相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"三月攻势打开战线，却没有消灭英法主力，四月必须继续寻找新的破口。","after":"五月马恩河方向的再次推进，会同时扩大德国战果与自身战线的负担。"},"relatedBattles":[]},{"id":"ww1-1918-05","date":"1918-05","title":"埃纳河突破，把危险带回巴黎方向","theaters":["西线"],"countries":["de","fr","uk","us"],"people":["鲁登道夫","潘兴"],"story":["德军在埃纳河方向突破，将战线再次推向马恩河与巴黎方向。突然成功制造巨大压力，却也使德国部队展开到更长的战线上，难以同时维持所有方向的主动。","德军在埃纳河利用突然性取得进展，一些防守部队来不及撤向更安全位置。进攻后来向马恩河扩展，最初作为转移压力的行动又吸引更多投入，成功本身也可能让原计划目标发生漂移。","美军逐步进入前线，既带来兵力，也带来不同训练和指挥习惯。盟军合作需要让新部队适应已经持续多年的战争，而德国则希望赶在这套体系完善之前，再挤出一次机会。","美军开始承担更明显的战斗任务。盟军需要把新兵力与已有防御结合，而德国则必须在持续进攻与逐渐不足的补给之间选择，战场上的势头与长期力量对比正相互背离。"],"perspectives":[{"country":"fr","text":"保卫巴黎方向与维持军队衔接同时变得紧迫。"},{"country":"de","text":"占领更多土地并未解决击垮盟军的核心目标。"}],"sources":[{"id":"nam18","locator":"1918-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-05相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"四月未能迫使盟军决裂，五月进攻更靠近巴黎，却仍未解决消灭主力的问题。","after":"六月美军作战和皮亚韦防御，将进一步改变德国及盟友可期待的时间窗口。"},"relatedBattles":[]},{"id":"ww1-1918-06","date":"1918-06","title":"美军投入，意大利守住皮亚韦河","theaters":["西线","意大利"],"countries":["us","fr","de","it","ah"],"people":["潘兴","迪亚兹"],"story":["美军在贝洛森林等处参与激烈战斗，显示新的协约国力量已经进入前线。美军仍在学习现代战争，但数量、工业和运输支持使其作用不断扩大。","美军部队投入法国战场时，并不是一到就熟悉炮火密集的作战环境。士兵与军官需要迅速学习掩护、协同和补给，人员充足的优势只有通过组织才能发挥，经验的获得仍伴随真实伤亡。","意大利经过卡波雷托后的重整，更重视防御准备和部队士气。奥匈攻势受挫不仅是失去一些阵地机会，还会影响粮食匮乏和民族关系紧张背景下的军队信心，盟友越来越难互相支撑。","奥匈在皮亚韦河发动攻势受挫，意大利在卡波雷托后的防御整顿取得效果。德国与奥匈都需要决定性成果，却越来越难以承受失败后的再次投入，联盟内部的疲惫相互传递。"],"perspectives":[{"country":"us","text":"开始用实际作战承担联盟任务，经验和伤亡也随之增长。"},{"country":"ah","text":"进攻未果加剧军需与社会压力，帝国回旋空间继续缩小。"}],"sources":[{"id":"nam18","locator":"1918-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"五月德军扩大进攻，却未能阻断美军增加与意大利恢复。","after":"七月最后一轮马恩河进攻将面对更有准备、也更能组织反击的盟军。"},"relatedBattles":[]},{"id":"ww1-1918-07","date":"1918-07","title":"第二次马恩河：主动权开始换手","theaters":["西线"],"countries":["de","fr","us","uk"],"people":["福煦","鲁登道夫"],"story":["德国在马恩河一线再次进攻，盟军防御与反击挫败其意图。18日起的反攻把德军逐渐推回去，法国、美国等军队的协同作用开始更加明显。","苏瓦松等方向的盟军反击，结合炮兵、步兵与坦克行动，使德军马恩河突出部面临更大压力。突出部可以看起来深入敌方，却也可能因两侧受攻而变成必须撤出的危险位置。","德国此前连续攻势消耗的精锐难以迅速补充，盟军则在统一协调中积累连续行动能力。主动权并不是一次交火后被宣布移交，而是在谁还能组织下一轮有效行动的问题上逐渐发生变化。","这并不是某一瞬间所有德国部队同时败退，而是战略进攻能力逐渐耗尽的转折。德国难以补足损失，盟军却能组织连续行动，战争从寻找最后突破转向如何应对持续后退。"],"perspectives":[{"country":"de","text":"必须接受攻势未能赢得战争，并开始防守越来越不利的局面。"},{"country":"fr","text":"经过长期消耗后，获得组织反攻与收复失地的条件。"}],"sources":[{"id":"nam18","locator":"1918-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-07相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"六月盟军新增力量与防御恢复，使德国的最后进攻面临更不利条件。","after":"八月亚眠将把局部反攻扩大为接连不断的压力，德国再也难以充分休整。"},"relatedBattles":[]},{"id":"ww1-1918-08","date":"1918-08","title":"亚眠与百日攻势：连续压力取代单次豪赌","theaters":["西线"],"countries":["uk","fr","us","de"],"people":["福煦","黑格"],"story":["8日，盟军在亚眠发动攻击，结合突然性、坦克、炮兵和步兵协同取得进展。德军的俘虏与损失反映士气和组织承受力的下降，鲁登道夫将这一天视为严重打击。","亚眠进攻强调突然性与多兵种配合，守军在一些地段被打乱，难以及时恢复有组织防御。盟军随后没有始终只在同一处追加兵力，而是逐步把压力转移到其他战段。","这种连续行动依靠道路、铁路、车辆、工程与补给体系支撑。德国若把预备队送到刚受攻击的地方，新的战段又可能遭到进攻，局部守住阵地越来越难换来整体喘息。","此后的百日攻势并非一场连续不歇的冲锋，而是相互衔接的多次行动。盟军调整攻击方向，不断迫使德军放弃阵地；资源优势与战术学习开始转化为较持续的成果。"],"perspectives":[{"country":"uk","text":"部队经验与多兵种协同改善，但仍需支付伤亡代价。"},{"country":"de","text":"难以再通过局部坚守扭转总体资源与士气的劣势。"}],"sources":[{"id":"nam18","locator":"1918-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-08相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"七月德国失去进攻主动，八月盟军尝试用连续行动让其无法重新建立稳定局面。","after":"九月坚固防线与同盟国其他成员都将受到考验，军事压力开始转为政治退出。"},"relatedBattles":[]},{"id":"ww1-1918-09","date":"1918-09","title":"兴登堡防线承压，盟友开始退出","theaters":["西线","巴尔干","中东"],"countries":["de","uk","fr","us","ot"],"people":["福煦","艾伦比"],"story":["盟军攻击兴登堡防线，美军在圣米耶勒及默兹—阿尔贡方向作战，德军后退压力加大。防御工事并非不可突破，关键在于守军是否还能获得足够兵员、物资和信心。","兴登堡防线拥有纵深工事与障碍，盟军仍需炮兵、工程和步兵逐段解决，突破并不是因为德国士兵突然都不再抵抗。真正变化在于守军已难不断补足损失，而进攻者能从更多方向维持压力。","保加利亚退出和奥斯曼军在巴勒斯坦的失利，使德国不能再只按西线地图判断前景。联盟成员各自寻求生存，任何一国的停战都会改变其他国家的交通、边境与继续战争的信心。","巴尔干战线突破后保加利亚停战，中东米吉多作战重创奥斯曼军。德国最高统帅部要求寻求停战，前线困难终于以政治形式进入决策，盟友退出又进一步压缩德国的选择。"],"perspectives":[{"country":"de","text":"军事领导层开始要求政治当局寻找战争出口。"},{"country":"ot","text":"中东主力受挫，继续战争的基础迅速削弱。"}],"sources":[{"id":"nam18","locator":"1918-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-09相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"八月连续攻势削弱德军恢复能力，九月压力同时撞向防线和联盟体系。","after":"十月德国必须把停战要求转成外交交涉，也会面对军事服从与国内政治的裂缝。"},"relatedBattles":[]},{"id":"ww1-1918-10","date":"1918-10","title":"帝国瓦解，停战接连到来","theaters":["外交","意大利","后方"],"countries":["de","ah","ot","us","it"],"people":["卡尔一世","威尔逊","迪亚兹"],"story":["奥斯曼签署穆德罗斯停战协定，奥匈在民族运动、军队疲惫和意大利攻势中迅速失去整体控制。战争不是只由德国一国的决定结束，同盟国体系正在逐步解体。","德国改革政府，希望由更具议会基础的政治力量承担谈判，却无法让军事败势与社会困境暂时停住。谁负责把战争带到这一步，谁又必须签下结束它的文件，后来成为责任争论的核心。","海军人员反对最后冒险出击，既与厌战有关，也与不愿在已寻求停战时继续付出生命有关。军队内部的秩序并非抽象存在，当指挥目标失去可信度，服从关系就可能快速转成政治行动。","德国与威尔逊交涉停战条件，政府改革与军队危机并行。海军内部拒绝最后冒险行动的反抗很快扩大，军事服从的裂缝开始影响政体本身，停战与革命相互推动。"],"perspectives":[{"country":"ah","text":"多民族帝国的政治框架已难维持，各民族政治力量寻找独立出路。"},{"country":"de","text":"改革与停战交涉赶不上社会危机扩大的速度。"}],"sources":[{"id":"nam18","locator":"1918-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-10相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"九月统帅部要求寻找出口，十月却发现和平交涉与体制稳定无法各自独立。","after":"十一月革命、退位与停战会集中到来，而结束战斗仍不是建立和平秩序的终点。"},"relatedBattles":[]},{"id":"ww1-1918-11","date":"1918-11","title":"十一点停火之后，和平尚未完成","theaters":["外交","后方"],"countries":["de","uk","fr","us","ah"],"people":["福煦","威廉二世"],"story":["德国革命扩大，威廉二世退位，新的政府承担停战责任。11日，德国代表与协约国签订停战安排，西线于上午十一点停止交火，长期战争终于出现清晰的军事终点。","停战要求撤离占领区、交出部分装备并落实军事限制，目的是让德国不能轻易恢复战争。它与后来正式和平条约不同，却已经深刻影响德国战后军政权力与国内舆论。","停火消息也需要传到不同战区，远方部队并不会在同一时刻都自动停止行动。伤员、战俘和流离失所者更需要运输与照护，现代战争的组织机器必须从制造战斗转向帮助人回到生活。","许多人因此获救，另一些人的伤残、丧亲、饥饿与流亡却不会随钟声消失。停战条款、复员、俘虏回返和封锁问题仍待处理，战后政治边界也尚未谈妥。","战场失败、国内革命与停战签署之间的关系，后来被极端民族主义歪曲。理解真正的因果，需要把军队此前的持续败退、资源困境和盟友瓦解一起看，而不能接受把失败全部归罪于后方的神话。"],"perspectives":[{"country":"de","text":"新政权接下战争遗产，停战责任后来成为政治攻击对象。"},{"country":"fr","text":"本土战事结束，却要面对重建、损失与未来安全安排。"}],"sources":[{"id":"nam18","locator":"1918-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"peace","locator":"1918-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nam18deep","locator":"1918-11相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"十月政权与军队危机已经扩大，十一月的停战承认了此前长期形成的军事困境。","after":"1919年和会将决定领土、安全与赔偿，胜利者之间的分歧开始成为新主线。"},"relatedBattles":[]},{"id":"ww1-1919-01","date":"1919-01","title":"巴黎和会：胜利者之间也有不同的和平","theaters":["外交"],"countries":["us","uk","fr","it","cn","jp"],"people":["威尔逊","克列孟梭","劳合·乔治"],"story":["巴黎和会开幕，战后安全、赔偿、领土和国际组织成为议题。法国重视防止德国再次进攻，英国权衡欧洲均势与帝国利益，威尔逊则推动国际联盟和新的和平原则。","所谓胜利者并不是目标一致的集团。法国希望避免再次被入侵，英国顾虑欧洲力量过度失衡，美国试图把新国际组织置于和平架构中心，意大利和日本又各有战时承诺与地区要求。","中国代表的山东诉求触及日本既得控制与列强之间的协议，原则语言难以自动压倒强权交易。谈判席位的存在与实际影响力的大小，需要分开观察，才看得到战后秩序如何同时包含希望与不平等。","这些目标并不总能兼容，战败国与许多弱小民族也没有同等发言权。中国希望解决山东权益问题，却发现战时秘密协议与列强利益仍然有力，战场贡献并没有自动变成谈判平等。"],"perspectives":[{"country":"fr","text":"遭受入侵与破坏的经验，使安全保障成为核心诉求。"},{"country":"cn","text":"期待恢复主权，面对的却是日本和其他强国既有安排。"}],"sources":[{"id":"peace","locator":"1919-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1919-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"停战只解决停止作战的问题，一月开始争论怎样防止重演、怎样分配胜利成果。","after":"六月和约将把妥协写成条文，也把未解决的主权与安全冲突留给社会。"},"relatedBattles":[]},{"id":"ww1-1919-06","date":"1919-06","title":"凡尔赛：签下一份条约，没有解决所有问题","theaters":["外交","后方"],"countries":["de","fr","uk","us","cn","jp"],"people":["威尔逊","克列孟梭"],"story":["28日，凡尔赛条约签署，对德国领土、军备、赔偿责任等作出安排，并纳入国际联盟框架。德国社会的不满与各国对安全的追求同时存在，条约不能只用胜利者惩罚或失败者受辱一个角度解释。","和约对德国军备与领土作出限制，却仍需要执行、监督与各国长期合作。条文能改变法律位置，不能保证每个签署国始终愿意为维护它承担成本；和平秩序从成立时起就有政治条件。","山东问题引发中国国内广泛抗议，拒签既是外交行动，也与社会对民族独立和平等的要求相连。从赴欧华工到和会，参与世界大战的人群发现自己并未共同进入一个真正平等的新世界。","中国因山东问题拒绝在对德和约上签字。美国后来也未批准条约加入国际联盟。一战通向二战不是一条注定的直线，还需结合经济危机、法西斯政治、侵略选择与集体安全失效，才能理解其间的变化。"],"perspectives":[{"country":"de","text":"条约争议成为国内政治动员的重要材料，却不能为后来侵略开脱。"},{"country":"cn","text":"拒签体现主权诉求，也显示战后国际秩序的平等承诺存在限度。"}],"sources":[{"id":"peace","locator":"1919-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1919-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"一月的各国诉求经过数月交涉形成妥协，六月留下的争议不会因为签字而消失。","after":"回看二战前史时，还要接入经济危机、独裁政治与侵略决策，不能把两次大战视作命定连续剧。"},"relatedBattles":[]}]},{"id":"ww2","name":"第二次世界大战","years":"1939—1945","subtitle":"从侵略扩张，到全球抵抗与艰难和平","coverage":"1939年9月—1945年9月，73个月连续；另列1931年以来亚洲与欧洲前史。","intro":"侵略并非不可避免的自然灾害。独裁、种族主义、帝国扩张与集体安全失效，逐步把各地区战争连成全球冲突；抵抗、联盟与社会动员最终击败轴心国，却留下巨大的平民灾难与未解的战后问题。","start":"1939-09","end":"1945-09","default":"1939-09","phases":[["1931-09","前史：侵略的扩张"],["1939-09","欧洲开战与轴心推进"],["1941-06","战争全球化"],["1942-11","转折与同盟合作"],["1944-01","多线反攻"],["1945-06","终战与战后秩序"]],"months":[{"id":"ww2-1931-09","date":"1931-09","title":"从沈阳开始的侵略：亚洲前史不能略去","theaters":["中国","外交"],"countries":["cn","jp"],"people":["张学良"],"story":["9月18日，日本关东军制造柳条湖事件并进攻沈阳，随后扩占中国东北。地方军事行动很快改变整个地区的政治形势，侵略并未因国际社会的交涉而停止。","侵略的开端不只是一个铁路爆炸现场。关东军把局部事端转成占领行动，继而向东北各地扩张；军事上的既成事实不断压缩外交交涉的空间。东北丰富的土地、工业与交通资源，又被纳入日本扩大侵略的体系。","本卷把1939年9月至1945年9月作为全球大战主时间轴，同时把中国抗战的1931年起点及1937年全面抗战单列前史。不同战争分期需要说明，不能因欧洲开战较晚而让亚洲长期战争消失。","此后的国际调查能够指出侵略，却缺少有效制止侵略的共同措施。东北民众的抵抗没有因主要城市失陷而结束，义勇军与后来的抗日武装使占领始终面对反抗。理解1937年的全面战争，需要先看见这六年不断扩大的侵略与抵抗。"],"perspectives":[{"country":"cn","text":"失土、流亡与抵抗使战争进入东北军民生活。"},{"country":"jp","text":"军部扩张与既成事实侵蚀外交约束，也推动帝国继续走向侵略。"}],"sources":[{"id":"china","locator":"1931-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本在中国东北的权益扩张、军部行动与国际秩序的软弱，构成事变前的背景。","after":"局部侵略被长期化、制度化；欧洲的扩张者也将在集体安全失效中寻找机会。"},"relatedBattles":[]},{"id":"ww2-1933-01","date":"1933-01","title":"希特勒上台：侵略与迫害需要追溯政治起点","theaters":["德国","后方"],"countries":["de","fr"],"people":["希特勒"],"story":["30日，希特勒被任命为德国总理。纳粹随后利用国家权力摧毁政治竞争，排斥与迫害犹太人及其他群体，逐步把德国改造成独裁体制。","希特勒出任总理并不意味着德国选民一致授权建立独裁。纳粹借助保守派的政治交易进入政府，随后利用国会纵火案等契机压制反对派，以紧急措施和《授权法》逐步摧毁议会制约。政治警察、集中营和宣传体系共同扩大恐怖统治。","战争并非1939年突然从无到有。反民主政治、种族主义与扩军政策相互支撑，国家机器既被用于准备对外征服，也被用于针对本国居民的制度性迫害。","对外扩张与对内迫害由此获得国家机器支持。犹太人被逐步排除出公共生活，工会与反对党遭到镇压；重新武装则以突破凡尔赛体系、追求所谓生存空间为方向。战争尚未爆发，但能够约束战争决策的制度正在被拆除。"],"perspectives":[{"country":"de","text":"国家并非单一意志，政权通过镇压、宣传和组织控制压缩反对空间。"},{"country":"fr","text":"邻国政治转向与军备问题，逐渐改变法国面对的安全环境。"}],"sources":[{"id":"holocaust","locator":"1933-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"经济危机、战败后的政治冲突与保守精英的误判，使纳粹获得掌权机会。","after":"独裁巩固后，德国将通过重整军备和一连串对外冒险检验其他大国的反应。"},"relatedBattles":[]},{"id":"ww2-1935-10","date":"1935-10","title":"意大利侵略埃塞俄比亚，集体安全遭考验","theaters":["非洲","外交"],"countries":["it","uk","fr"],"people":["墨索里尼"],"story":["意大利军队入侵埃塞俄比亚，殖民扩张冲击国际联盟维护和平的承诺。制裁和外交讨论未能及时阻止征服，弱国很难仅凭制度承诺获得有效保护。","意大利从厄立特里亚和意属索马里方向进攻埃塞俄比亚。埃塞俄比亚军民抵抗装备更强的侵略军，意军还使用化学武器。战争体现的不是抽象的强弱竞争，而是一个独立国家遭到殖民征服，以及平民被卷入暴力的过程。","英国、法国既担心意大利倒向德国，也要顾及各自帝国利益。对侵略的应对因此被利益权衡削弱，这种失败并不意味着战争必然发生，却使继续冒险的代价看起来更低。","国联认定侵略并实施部分制裁，却没有形成足以阻止战争的约束。英国、法国既担心意大利倒向德国，又不愿承担全面对抗的代价。这种妥协使集体安全的承诺与实际行动进一步脱节，也为轴心国之间的靠拢提供条件。"],"perspectives":[{"country":"it","text":"法西斯政权以帝国扩张追求声望，侵略给当地造成深重苦难。"},{"country":"uk","text":"制止侵略与维护欧洲联盟之间的矛盾暴露出政策局限。"}],"sources":[{"id":"prewar","locator":"1935-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本侵略东北已暴露国际制裁的局限，意大利又把殖民野心变成公开战争。","after":"埃塞俄比亚的遭遇加深了国际秩序危机；下一次对条约的挑战发生在莱茵兰。"},"relatedBattles":[]},{"id":"ww2-1936-03","date":"1936-03","title":"莱茵兰进军：既成事实再次改变规则","theaters":["欧洲","外交"],"countries":["de","fr","uk"],"people":["希特勒"],"story":["德国军队进入莱茵兰非军事区，挑战战后条约安排。英法没有以军事行动驱离德军，德国在西部边境的战略地位因此改善。","德军进入《凡尔赛条约》和《洛迦诺公约》规定的莱茵非军事区。希特勒把行动包装成恢复主权，但实质上是单方面破坏安全安排。德国当时尚未完成战争准备，英法如何应对，本可能影响纳粹继续冒险的判断。","这一行动后来常被写成必然成功的冒险，实际上当时仍有风险与政策选择。其后果在于侵略者从外部反应中判断约束力度，欧洲安全秩序进一步依赖对下一次承诺的相信。","法国不愿在缺乏英国支持时单独采取军事行动，英国也倾向于通过谈判处理德国的要求。行动成功强化了希特勒在国内的威望，并改变了法国东部安全环境。此后德国向中东欧施压时，更少担心西线立即遭到干预。"],"perspectives":[{"country":"de","text":"重整军备与违约行动获得政治收益，增强政权继续扩张的信心。"},{"country":"fr","text":"边境安全形势恶化，又受国内政治、联盟与战争恐惧影响。"}],"sources":[{"id":"prewar","locator":"1936-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国重整军备后，需要试探战后条约及英法承诺是否仍有实际约束力。","after":"一次未遭有效制止的冒险增加了下一次冒险的信心，西班牙内战又给外部干涉打开空间。"},"relatedBattles":[]},{"id":"ww2-1936-07","date":"1936-07","title":"西班牙内战：欧洲战争的前奏之一","theaters":["欧洲","外交"],"countries":["de","it","su","uk","fr"],"people":["弗朗哥"],"story":["西班牙军人叛乱引发内战，德国、意大利支持叛军，苏联援助共和国，不同国家的志愿者也前来作战。西班牙人的内战由此与欧洲政治对抗交织。","西班牙军队中的叛乱没有迅速推翻共和国政府，而把全国拖入内战。不同政治力量在共和国阵营内合作又发生分歧，佛朗哥则逐步集中叛军领导权。德国和意大利给予叛军重要军事支持，苏联援助共和国，国际纵队也来到西班牙。","外部介入提供武器、飞机和作战经验，不干涉政策却未能隔绝外国影响。它是理解法西斯扩张、空袭和平民处境的重要前史，但不能把西班牙社会本身的矛盾全部解释为大国代理竞争。","这场战争既有西班牙自身的社会与政治根源，又被欧洲反法西斯与法西斯力量的对立深刻影响。轰炸城市、外军介入和英国法国的“不干涉”政策，显示国际秩序的困境。它不能简单称作二战的预演，却确实让未来参战者积累了战争经验。"],"perspectives":[{"country":"it","text":"介入内战服务于法西斯影响与地区利益。"},{"country":"su","text":"援助共和国，国际反法西斯合作同时夹杂自身政策目标。"}],"sources":[{"id":"prewar","locator":"1936-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"欧洲对侵略的共同应对已日益松散，西班牙内部冲突又给外部强国提供干涉机会。","after":"欧洲危机持续发酵的同时，日本在中国的侵略将从局部扩展为全面战争。"},"relatedBattles":[]},{"id":"ww2-1937-07","date":"1937-07","title":"卢沟桥：全面抗战展开","theaters":["中国"],"countries":["cn","jp"],"people":["蒋介石"],"story":["7日夜，日军在卢沟桥附近挑起冲突，中国守军抵抗。危机没有被限制在局部，日军进攻扩大，中国抗战进入全国性、长期性的阶段。","卢沟桥位于北平西南的重要交通线上。日军借演习中士兵失踪提出进入宛平城搜查，要求遭拒后发生交火；此后增兵与进攻不断使局面升级。中国守军的抵抗，面对的是日本长期驻军、蚕食华北及不断扩大军事要求的背景。","对中国而言，这是国家生存与主权的战争；对日本军部而言，扩大军事行动被寄望于压服中国，却把自身进一步拖入无法迅速结束的战争。此后理解太平洋战争，必须把中国持续抵抗纳入资源与战略背景。","局部交涉未能阻止侵略扩展，平津相继陷落。中国抗战由局部走向全民族抗战，国共合作抗日的条件也随之加强。战争从一座桥附近扩散到更广阔的国土，如何动员军队、社会与资源，成为此后八年的核心问题。"],"perspectives":[{"country":"cn","text":"地方冲突扩为全面战争，需要动员军队、经济与社会。"},{"country":"jp","text":"不断扩大目标，使有限行动逻辑走向长期占领与消耗。"}],"sources":[{"id":"china","locator":"1937-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1937-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"东北沦陷后，日本继续向华北扩张，地方妥协始终未能换来侵略停止。","after":"平津战事未止，上海很快成为新的大战场，中国开始同时承受华北与华东的压力。"},"relatedBattles":[]},{"id":"ww2-1937-08","date":"1937-08","title":"上海会战：把抵抗带到国际都市","theaters":["中国"],"countries":["cn","jp"],"people":["张治中","谢晋元"],"story":["13日起，上海发生大规模交战，中国投入主力，日军通过增兵与登陆扩大攻势。城市、村镇与交通节点反复争夺，工业和人口密集区承受战争破坏。","上海既是工业、金融和港口中心，也有外国租界与国际舆论的注视。中国军队在这里投入精锐部队抵抗日军，战斗从城区街巷扩大到沿江与外围阵地。日本依靠海空优势和持续增援，中国守军则在火力不利的条件下反复争夺阵地。","持续到11月的会战消耗中国精锐，也打破日方迅速迫使中国屈服的设想。难民、工厂迁移与政府西迁，使抗战从战场行动逐渐转为整个社会重组生存条件的过程。","数月抵抗并非没有代价的战略选择：部队严重损耗，城市和平民遭到巨大破坏。日军从杭州湾方向登陆后，中国军队侧后受到威胁，被迫撤退。上海失守后南京暴露在日军攻势之下，而抗战继续向内地延伸，速战解决中国问题的企图未能实现。"],"perspectives":[{"country":"cn","text":"以持续抵抗争取时间，同时承受军队和城市社会的重大损失。"},{"country":"jp","text":"战场胜利没有转化为中国停止抵抗，侵略范围继续扩大。"}],"sources":[{"id":"china","locator":"1937-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"全面抗战开始后，上海成为双方集中兵力、争夺战争主动权的重要地区。","after":"淞沪会战的撤退把战线带向南京，也使保存实力与坚持长期抵抗的问题更加紧迫。"},"relatedBattles":["battle-shanghai-1937"]},{"id":"ww2-1937-12","date":"1937-12","title":"南京陷落与大屠杀：必须正视的战争罪行","theaters":["中国","平民"],"countries":["cn","jp"],"people":["松井石根"],"story":["13日，日军攻占南京，随后对平民及放下武器人员实施大规模杀害，并发生强奸、抢掠等严重暴行。南京大屠杀是有充分史料与战后审判支持的战争罪行，不能被淡化为普通攻城附带事件。","南京失陷发生在中国军队连续撤退、防御组织与撤离混乱的背景下。日军进入南京后，对放下武器的军人和平民进行大规模屠杀，并实施强奸、抢掠等暴行。这里必须区分军事战斗的结束与占领后的犯罪，不能用战场混乱掩盖侵略者的责任。","中国政府继续在西部组织抗战，军事失利没有结束国家抵抗。记录屠杀、保护幸存者证言并辨别否认和歪曲，是理解这场战争不可缺少的部分，不能只沿着将领与军队的胜负阅读历史。","留在城内的中国民众和南京安全区工作人员竭力救助受害者，幸存者证言、日记、影像与审判材料保存了罪行证据。南京的灾难没有使中国停止抵抗，国民政府此前已迁都重庆，军民继续向纵深组织战争与社会生活。"],"perspectives":[{"country":"cn","text":"国家抵抗与民众避难并行，丧亲、创伤和流亡延续多年。"},{"country":"jp","text":"军队占领与对平民犯罪必须分别追究，理解行为不等于为其辩解。"}],"sources":[{"id":"china","locator":"1937-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nanjing","locator":"1937-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"上海失守后日军向南京推进，中国的沿海和长江下游防御遭到重创。","after":"占领首都不等于征服中国；1938年的徐州、武汉战事继续检验双方承受长期战争的能力。"},"relatedBattles":[]},{"id":"ww2-1938-03","date":"1938-03","title":"吞并奥地利：扩张以统一之名推进","theaters":["欧洲"],"countries":["de","uk","fr"],"people":["希特勒"],"story":["德国进入并吞并奥地利，纳粹政权扩大领土与资源，并迅速把迫害政策推向当地。所谓民族统一的宣传掩盖了强制、反对者受压和犹太居民遭难。","德国先以政治压力干预奥地利政府，再在3月派军进入奥地利并宣布合并。随后举行的投票处于纳粹控制和恐吓之下，不能当作自由选择的证明。德军没有经过大规模作战便控制一个国家，也取得了进一步向中欧扩张的地理条件。","欧洲其他国家未能有效制止，德国下一步把压力转向捷克斯洛伐克。一次扩张既改变军事位置，也使更多人口进入独裁与种族迫害的统治体系。","合并立即伴随对犹太人和政治反对者的迫害。英法没有采取足以改变结果的行动，希特勒的下一步目标转向捷克斯洛伐克。将所谓民族统一口号与实际强制手段分开观察，才能看清扩张如何披上合法性的外衣。"],"perspectives":[{"country":"de","text":"政权把兼并包装为民意与民族目标，继续扩大对外野心。"},{"country":"uk","text":"避免再次大战的愿望影响政策，却没有消除扩张带来的安全风险。"}],"sources":[{"id":"prewar","locator":"1938-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1938-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"莱茵兰行动的成功和德国军力增长，使纳粹更敢于用威胁改变邻国地位。","after":"奥地利被吞并后，捷克斯洛伐克在地理和外交上更加孤立，苏台德危机接踵而至。"},"relatedBattles":[]},{"id":"ww2-1938-04","date":"1938-04","title":"台儿庄告捷，长期抵抗仍需继续","theaters":["中国"],"countries":["cn","jp"],"people":["李宗仁","孙连仲"],"story":["台儿庄战斗中，中国军队以庄内坚守和外线攻击配合，击退日军，振奋全国抗战信心。巷战中的坚持并非孤立行动，需要周围部队牵制、增援和补给共同支撑。","台儿庄位于徐州东北，日军企图沿交通线南下，贯通南北战场。李宗仁指挥第五战区组织防御，孙连仲部坚守城内，汤恩伯等部在外围作战。守军利用城镇和近距离战斗削弱日军火力优势，外围部队则威胁其侧后与补给。","胜利没有终止徐州地区的战事，也没有让日军停止进攻。将局部战果放进长期抗战，才能理解它既显示抵抗能力，又无法独自扭转全部战局的意义。","胜利来自坚守、机动与协同，也依靠当地军民支援，并非某一种单一武器或个人勇敢即可解释。它打破日军不可战胜的宣传，振奋全国抗战信心，但徐州地区的总体兵力态势并未根本逆转。中国军队后来撤出徐州，仍要保存力量继续作战。"],"perspectives":[{"country":"cn","text":"胜利提振士气，但必须保存和组织继续作战的力量。"},{"country":"jp","text":"局部受挫未改变侵略政策，随后仍扩大攻势。"}],"sources":[{"id":"china","locator":"1938-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日军企图把华北、华中的占领区连接起来，徐州一带成为交通与战略争夺焦点。","after":"局部胜利证明抵抗的可能，随后的长期战略讨论则要回答怎样把抵抗坚持下去。"},"relatedBattles":["battle-taierzhuang"]},{"id":"ww2-1938-05","date":"1938-05","title":"怎样理解长期战争：《论持久战》的判断","theaters":["中国","后方"],"countries":["cn","jp"],"people":["毛泽东"],"story":["毛泽东在延安作《论持久战》讲演，反对亡国论和速胜论，分析敌我力量、战争性质与发展阶段，强调通过持久抵抗和人民动员改变力量对比。","《论持久战》把中国抗战放在敌强我弱、国土广大、战争性质与国际条件中分析。它反对迅速亡国和轻易速胜两种判断，提出战争将经历战略防御、战略相持、战略反攻，强调时间不是自动带来胜利，必须依靠组织与斗争改变力量对比。","这一论述不是预先写好每一场战役的剧本，而是为长期战争提供战略认识。把战场失败、局部胜利、人口动员和外部条件联系起来，才能理解中国为何仍能在日军占领大量城市后继续抵抗。","这一认识涉及的不是单一战术，而是军队、群众、根据地、政治动员与国际援助的配合。游击战与运动战需要联系正规战场理解；长期抵抗也意味着人民承担沉重代价。把理论与此后武汉会战、敌后战场及国际局势对照，才能看到判断如何接受战争实践检验。"],"perspectives":[{"country":"cn","text":"正面与敌后作战、社会动员和争取外援共同构成长期抗战条件。"},{"country":"jp","text":"占领城市无法自动消灭抵抗，日方需要承担越来越大的控制和补给成本。"}],"sources":[{"id":"mao38","locator":"1938-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"沿海大城市相继失守、台儿庄又取得胜利，社会迫切需要判断战争究竟会走向何处。","after":"持久抗战的思路将在武汉失守后的相持局面中更加鲜明，战争重心也逐渐深入社会基层。"},"relatedBattles":[]},{"id":"ww2-1938-09","date":"1938-09","title":"慕尼黑：用谁的领土交换和平","theaters":["欧洲","外交"],"countries":["de","uk","fr"],"people":["希特勒","张伯伦","达拉第"],"story":["英法德意领导人在慕尼黑达成协议，允许德国取得捷克斯洛伐克苏台德地区，受影响国家没有平等参与决定。英法希望通过让步避免战争，捷克斯洛伐克却失去重要防线与资源。","捷克斯洛伐克拥有防御工事、工业和作战力量，但它的命运却在没有本国代表平等参与的会议中被决定。英法同意德国取得苏台德地区，试图以领土让步换取和平；这同时削弱了捷克斯洛伐克的边防、经济和继续抵抗的条件。","协议带来短暂松懈，没有使希特勒停止扩张。它的教训不仅是后来证明承诺不可信，也在于把弱国安全当作可以由强国处置的筹码，会侵蚀共同规则和防务基础。","慕尼黑协定并未解决纳粹扩张目标。所谓保护德意志人的理由，很快被对更多领土的占领突破。对当时决策者而言，一战记忆、军备状况与政治压力都影响选择；理解这些顾虑，仍不能忽视让受威胁国家承担代价的后果。"],"perspectives":[{"country":"uk","text":"张伯伦希望争取和平和时间，但对德国目标的判断存在严重局限。"},{"country":"de","text":"侵略威胁换得让步，为继续破坏欧洲秩序创造条件。"}],"sources":[{"id":"prewar","locator":"1938-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"吞并奥地利后，希特勒把压力集中到苏台德地区，英法再次面对战争与退让的抉择。","after":"半年后的布拉格将证明，扩张要求并未在慕尼黑停步。"},"relatedBattles":[]},{"id":"ww2-1938-10","date":"1938-10","title":"武汉失守，抗战转入更长的相持","theaters":["中国"],"countries":["cn","jp"],"people":["蒋介石"],"story":["广州、武汉先后失守，中国失去重要交通和经济中心。此前台儿庄等地的胜利并未阻止日军总体推进，局部战果与全国战局的艰难必须同时看到。","武汉三镇是内陆交通、工业与抗战动员中心。日军从长江和陆路多方向进攻，中国军队在外围广大地区抵抗，田家镇、万家岭等战斗都是会战的一部分。防御持续数月，为人员、设备和物资进一步向西转移争取了时间。","政府、学校和工业向内地迁移，正面战场与敌后抵抗继续展开。日本占领更多城市，却仍不能控制广阔社会空间、迫使中国投降，战争由夺取中心城市进一步转为长期消耗。","广州、武汉相继失守使中国处境更加困难，但日军战线与占领负担也不断扩大，无法凭占领中心城市结束战争。正面战场继续抵抗，敌后根据地逐步发展，侵略军需要同时应付交通线、占领区与前线作战，战争日益呈现长期相持特征。"],"perspectives":[{"country":"cn","text":"迁移与重建成为继续抵抗的基础，社会承受能力受到持久考验。"},{"country":"jp","text":"占领范围扩大，也带来更多守备、运输和统治成本。"}],"sources":[{"id":"china","locator":"1938-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日军在华中持续推进，武汉成为南京之后试图迫使中国屈服的又一个目标。","after":"大城市的失守没有终止抗战，接下来决定战争的不只是城市归属，还有社会动员与持续补给。"},"relatedBattles":[]},{"id":"ww2-1938-11","date":"1938-11","title":"反犹暴行升级，迫害不再隐蔽","theaters":["德国","平民"],"countries":["de","us"],"people":["希特勒"],"story":["9日至10日，纳粹组织针对犹太人的大规模暴行，犹太会堂、商店与住宅遭袭，大批人员被捕。制度性排斥进一步转向公开暴力，受害者生活与逃离空间急剧收缩。","11月9日至10日的反犹暴行并非自发冲突。纳粹利用外交官遇刺事件煽动攻击，犹太会堂、商铺和住宅遭到焚毁破坏，大批犹太男性被捕并送进集中营。受害群体随后还被迫承担罚款与财产损失，迫害进一步制度化。","这不是孤立骚乱，而是政权推动迫害的组成部分。把它与后来的占领、隔都、驱逐和屠杀连接起来，才能看清种族灭绝如何通过不断升级的行政与社会暴力形成。","此前以法律排斥和财产剥夺为主的政策，越来越公开地诉诸大规模暴力。许多犹太人急于离境，却面对签证、资金与接收国限制。战争爆发后，迫害的空间和手段继续扩大；回看这个节点，应看到一步步升级的政策选择，而不是把种族灭绝描述成突然发生的事件。"],"perspectives":[{"country":"de","text":"政权和参与者的责任需要辨明，居民面对迫害也有服从、获利、旁观与抵抗等不同选择。"},{"country":"us","text":"难民问题更加迫切，但各国接纳政策仍存在重大限制。"}],"sources":[{"id":"holocaust","locator":"1938-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"纳粹掌权后的歧视立法、宣传与国家暴力，已逐步剥夺犹太人的权利与安全。","after":"对内迫害与对外侵略互相推动，1939年占领更多领土后，更多人将被置于纳粹统治之下。"},"relatedBattles":[]},{"id":"ww2-1939-03","date":"1939-03","title":"布拉格被占，慕尼黑承诺破产","theaters":["欧洲","外交"],"countries":["de","uk","fr","pl"],"people":["希特勒","张伯伦"],"story":["德国占领捷克地区，说明扩张已明显超出统一德语人口的说辞。慕尼黑协议没有保护剩余国家，希特勒继续以武力重塑欧洲。","德国占领捷克地区，建立波希米亚和摩拉维亚保护国；斯洛伐克则在德国压力下成为受其支配的政权。行动已无法用统一德意志居民解释，明确显示纳粹追求的远超慕尼黑所宣称的有限要求。捷克工业和军备资源也落入德国控制。","英国随后向波兰作出安全保证，英法政策开始转向更明确的遏制。然而保证怎样转为实际军事帮助仍是问题，波兰的地理位置与盟军部署使承诺和即时救援之间存在距离。","英国此后向波兰提供安全保证，对德政策发生转变，但保证如何落实仍是难题。法国、英国和苏联之间的互疑妨碍建立有效共同阵线，波兰自身也有安全顾虑。德国下一步行动因此与一场复杂而失败的外交博弈相连。"],"perspectives":[{"country":"uk","text":"对德意图的判断发生变化，准备承担更明确的安全义务。"},{"country":"pl","text":"获得外部保证，却仍面临德苏之间的严峻地缘处境。"}],"sources":[{"id":"prewar","locator":"1939-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"慕尼黑让出的边防与领土使捷克斯洛伐克极度脆弱，德国继而吞噬剩余国家。","after":"英法转向保证波兰安全，欧洲的危机中心随之东移。"},"relatedBattles":[]},{"id":"ww2-1939-08","date":"1939-08","title":"德苏协定：公开互不侵犯与秘密划界","theaters":["外交"],"countries":["de","su","pl","uk","fr"],"people":["希特勒","斯大林","莫洛托夫"],"story":["23日，德国与苏联签订互不侵犯条约，秘密议定书划分东欧势力范围。德国因此降低进攻波兰时立即两线作战的顾虑，苏联则谋求安全缓冲与自身领土利益。","德苏互不侵犯条约使德国暂时减少两线作战顾虑；秘密议定书则划分双方在东欧的势力范围，把波兰等国的命运变成大国交易对象。苏联争取时间与缓冲空间的计算，不能抹去秘密安排及此后占领行动对当地人民造成的后果。","条约不是两国根本目标一致的证明，更不使随后侵略和占领成为正当行为。英法与苏联未能形成有效协作，波兰等国却将承受强国交易带来的直接后果，欧洲战争的门槛已经极近。","英法苏谈判失败、波兰问题和彼此不信任，共同构成签约背景。条约不是两国意识形态和解，更不是持久和平保证。希特勒的侵略准备已进入最后阶段，外交文件在这里为军事行动扫清障碍，而不是阻止战争。"],"perspectives":[{"country":"de","text":"获得暂时的东方保障，准备以武力解决波兰问题。"},{"country":"su","text":"通过协议争取空间与时间，同时参与划分他国领土的安排。"}],"sources":[{"id":"prewar","locator":"1939-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"英法对波兰的承诺与集体安全谈判未能形成足以遏制德国的共同安排。","after":"德苏暂时妥协后，德国进攻波兰，欧洲战争在9月爆发。"},"relatedBattles":[]},{"id":"ww2-1939-09","date":"1939-09","title":"波兰被夹击，欧洲大战爆发","theaters":["欧洲","外交"],"countries":["de","pl","su","uk","fr"],"people":["希特勒","斯大林","张伯伦"],"story":["1日，德国入侵波兰，3日英法对德宣战。德国以空地协同和机动部队迅速推进，波兰军队持续抵抗，但难以及时获得西方盟国直接救援。17日，苏军又从东部进入波兰。","德国从多个方向进攻波兰，装甲、航空兵与地面部队协同实施突破，波军在不利的部署和装备条件下抵抗。英法对德宣战，却未能及时从西线给予足以解围的压力；9月17日苏军从东部进入波兰，使波兰面临两面夹击。","华沙围城、平民逃亡与军事崩溃同时发生，波兰被德苏分割占领。国家被占不等于抵抗终止，流亡政府、地下组织和海外军队随后继续作战，战争也从一场侵略扩展为欧洲多国的长期冲突。","华沙在轰炸与围困中坚持到月底，政府和部分军队转移海外，抵抗并未随国土被瓜分而消失。此后的流亡政府、地下组织与海外波军，都是波兰战争经历的重要部分。欧洲战争从一开始就伴随着占领、驱逐和对平民的暴力，远不只是机动作战的展示。"],"perspectives":[{"country":"pl","text":"面临两面进军与盟援不足，保全国家政治和抵抗组织成为后续任务。"},{"country":"uk","text":"宣战意味着承担长期战争，却没有立即改变波兰战场力量对比。"}],"sources":[{"id":"ww2dates","locator":"1939-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"8月的秘密势力范围安排降低了德国发动侵略的外交风险。","after":"波兰战役结束后，西线暂时沉寂，占领区却迅速进入恐怖统治。"},"relatedBattles":[]},{"id":"ww2-1939-10","date":"1939-10","title":"占领秩序建立，西线仍在等待","theaters":["欧洲","平民"],"countries":["de","pl","uk","fr"],"people":["希特勒"],"story":["波兰有组织的大规模抵抗在10月初进一步告终，纳粹占领当局开始分区统治、强制迁移与镇压。军事胜利迅速转化为针对社会与人口的统治工程，犹太人及其他居民受到越来越严厉的迫害。","德国与苏联在各自占领区重建边界和统治秩序。纳粹在波兰实施驱逐、处决与针对精英阶层的打击，并开始扩大对犹太人的隔离迫害。对生活在占领区的人而言，战争并没有因为主要会战结束而暂停，反而进入更长期的生存危机。","西线英法与德国未展开决定性陆战，后来被称为假战时期。但海上作战、经济封锁和军队集结都在继续，表面安静不是和平，只是在为下一阶段冲突积累力量。","英法联军在西线防御，海上封锁、潜艇袭击和军备生产继续进行。所谓“假战”只是对西线缺乏大规模地面进攻的概括，不能代表整个欧洲的处境。双方都在准备下一阶段战争，而德国开始筹划突破西方防线。"],"perspectives":[{"country":"de","text":"占领不只是驻军，而是实施掠夺、迫害与人口政策。"},{"country":"fr","text":"防御和动员持续进行，却仍需判断德国下一步主攻方向。"}],"sources":[{"id":"ww2dates","locator":"1939-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1939-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"波兰被击败并被瓜分，军事胜利迅速转化为占领统治。","after":"西线的等待与东欧的暴力同时持续，北欧也很快被卷入战火。"},"relatedBattles":[]},{"id":"ww2-1939-11","date":"1939-11","title":"冬季战争与美国中立法的变化","theaters":["东线","外交"],"countries":["su","us","uk"],"people":["斯大林","罗斯福"],"story":["30日，苏联进攻芬兰，试图以军事手段改变边境安全条件。随后的芬兰抵抗、严寒地形和苏军组织问题，使这场战争比进攻者预想的困难，强国的兵力优势并不保证低成本取胜。","苏联以列宁格勒安全和边境安排为由向芬兰提出要求，谈判失败后于11月30日发动进攻。芬军利用森林、湖泊与冬季地形抵抗，苏军初期暴露出指挥、协同与补给问题。实力悬殊没有自动变成迅速胜利，战争也不能简化成气候决定一切。","美国修改中立法，允许在现购自运条件下向交战国出售武器。它仍未参战，却逐步从严格限制转向为英法获得物资提供渠道，法律中立与政策倾向开始分离。","美国修改中立法，允许交战国按“现购自运”条件购买军需品，实际上更有利于控制海路的英法。美国公众仍不愿直接参战，但经济援助和中立边界已开始变化。北欧战事与大西洋贸易，正在把更多国家的安全利益连到一起。"],"perspectives":[{"country":"su","text":"军事行动暴露训练和组织缺陷，也造成新的国际压力。"},{"country":"us","text":"避免直接参战的同时，扩大对抗侵略国家的物资支持空间。"}],"sources":[{"id":"neutral","locator":"1939-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"winter","locator":"1939-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德苏划分东欧势力范围后，苏联进一步谋求西北边境安全，芬兰拒绝接受全部要求。","after":"冬季战争继续，英国与德国对北欧航道、资源和港口的关注也不断增加。"},"relatedBattles":[]},{"id":"ww2-1939-12","date":"1939-12","title":"拉普拉塔河口：海上战争已遍及远方","theaters":["海战","东线"],"countries":["uk","de","su"],"people":["朗斯多夫"],"story":["英国等舰艇在南大西洋追击德国装甲舰施佩伯爵海军上将号，交战后该舰进入蒙得维的亚，最终自沉。远洋袭商与追击把中立港口、情报和外交都卷入海战。","德国装甲舰“施佩伯爵海军上将”号在南大西洋袭击商船，英国巡洋舰队于拉普拉塔河口附近将其截住。交战后德舰进入中立的乌拉圭蒙得维的亚港，修理、停泊期限与外界情报判断又成为新的战场，舰长最终选择将舰自沉。","芬兰战场上，苏军继续付出高昂代价，冬季战争尚未结束。欧洲西线的等待不能代表整个世界，海路与北方边境的战事正在塑造各国对自身能力的判断。","这场海战说明战争已伸向远离欧洲陆地的航线。英国需要保护遍布全球的海运，德国则试图用有限水面舰艇和潜艇扰乱运输；中立港口也被交战规则与外交压力牵动。海上交通的争夺将贯穿整个战争，而非只是陆战之间的插曲。"],"perspectives":[{"country":"uk","text":"保护全球贸易航线，需要分散部署并依靠情报协同。"},{"country":"de","text":"袭商舰的活动能制造压力，却难以长期对抗广泛的海上追踪体系。"}],"sources":[{"id":"sea","locator":"1939-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"winter","locator":"1939-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国试图打击英国依赖的海运体系，英国则以巡逻和护航维持贸易与帝国联系。","after":"海战与封锁把战争带到全球，接下来英国后方的配给与北欧争夺都与资源供应相连。"},"relatedBattles":[]},{"id":"ww2-1940-01","date":"1940-01","title":"配给开始，漫长战争进入餐桌","theaters":["后方","东线"],"countries":["uk","de","su"],"people":["张伯伦"],"story":["英国开始实施部分食品配给，把有限进口与国内供应纳入更有组织的分配。对居民而言，战争不再只是报纸上的战报，而是购买、劳动和家庭生活方式的改变。","英国开始实行部分食品配给，战争由新闻和动员口号进一步进入家庭日常。配给试图在进口受威胁、军需增长的情况下分配有限物资，政府同时鼓励生产替代、节约和扩大国内供应。后方能够持续生活，是长期作战的条件之一。","芬兰方面继续抵抗苏军，英法讨论援助与北欧战略。军事与资源问题交织，使斯堪的纳维亚的重要性上升；所谓等待期，正酝酿新的战场。","西线部队仍在等待，训练、筑垒和运输准备却没有停止。英法对战争节奏的判断，与德国不断修改进攻计划形成反差。眼前的平静容易让人把上一场战争的防线经验当作安全保证，而下一轮攻势将从不同方向检验这些假设。"],"perspectives":[{"country":"uk","text":"公平分配和持续供给关系到社会能否接受长期动员。"},{"country":"su","text":"前线困难迫使军队调整战法，依靠更集中的火力与兵力推进。"}],"sources":[{"id":"winter","locator":"1940-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1940-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"波兰战役后的西线沉寂没有解除英国海运和资源压力。","after":"资源与航道将把注意力引向北欧，芬兰的战事也继续牵动英法决策。"},"relatedBattles":[]},{"id":"ww2-1940-02","date":"1940-02","title":"北欧冰雪中的突破与海上冲突","theaters":["东线","海战"],"countries":["su","uk","de"],"people":["斯大林"],"story":["苏军集中力量进攻芬兰防线，逐步取得突破，芬兰继续作战的条件越来越困难。战场经验说明，初期失败不能简单等同于军队此后始终无能。","苏军在冬季战争中调整部署，集中火力突破曼纳海姆防线，芬兰面临越来越难以弥补的人员和物资消耗。前期成功抵抗没有改变长期力量差距，政府开始寻找结束战争的可能，但避免国家灭亡与接受领土损失之间并无轻松选择。","英国海军在挪威水域截获德国补给船阿尔特马克号并解救被俘船员，引发中立与海上行动争议。德国和英国都更加关注挪威沿岸与运输线，北欧的中立处境进一步受压。","英国军舰在挪威水域截获德国补给船“阿尔特马克”号，释放其关押的英国商船船员。行动涉及中立权利争议，也暴露挪威难以单独保障水域不被交战国利用。德国和英法对北欧的战略计算由此更加紧迫。"],"perspectives":[{"country":"su","text":"以增援和战术调整扭转战场，但损失与外交代价已经发生。"},{"country":"uk","text":"海上行动的军事收益，也会牵动中立国和德国的下一步判断。"}],"sources":[{"id":"winter","locator":"1940-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1940-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"冬季战争久拖不决，北欧已同时成为人道关注、资源运输和军事部署的焦点。","after":"芬兰将以割地换取停战，但挪威与丹麦很快面对另一场入侵。"},"relatedBattles":[]},{"id":"ww2-1940-03","date":"1940-03","title":"芬兰议和，战争危机却未解除","theaters":["东线","中国"],"countries":["su","cn","jp"],"people":["斯大林","汪精卫"],"story":["苏芬签署莫斯科和约，芬兰保住国家独立，却割让领土并承担大规模人口迁移。战争在军事优势与国家生存之间形成妥协，边境居民必须承受地图改动的现实后果。","苏芬和约使芬兰割让包括卡累利阿地峡在内的领土，大批居民离开家园，国家独立得以保全。苏联赢得领土与战略位置，却付出沉重代价。德国对苏军表现的轻视，此后影响其发动东线战争的判断，但那并不是苏军能力永远不变的证明。","中国南京建立汪精卫伪政权，日本试图把军事占领转化为政治控制。中国的抗战继续，合作政权的存在并不意味着被占领社会已经接受侵略，抵抗与统治争夺进入日常治理层面。","南京的汪精卫政权在日本扶植下成立，试图以“和平”名义为占领提供政治外衣。中国抗战因而不仅面对日军军事压力，还面对占领区的合作政权和社会控制。重庆国民政府与中共领导的抗日力量继续抵抗，所谓和平并未结束侵略。"],"perspectives":[{"country":"su","text":"取得部分安全与领土目标，战争暴露的问题仍待解决。"},{"country":"cn","text":"侵略者扶植政权加剧政治分裂，但未能结束正面及敌后抵抗。"}],"sources":[{"id":"winter","locator":"1940-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1940-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"北欧的战争接近停战，中国则在相持阶段面对侵略者扩大政治控制。","after":"北欧并未恢复安全，德军下一步将夺取丹麦与挪威；中国的长期抵抗仍在继续。"},"relatedBattles":[]},{"id":"ww2-1940-04","date":"1940-04","title":"丹麦、挪威遭侵：战争绕过预想正面","theaters":["欧洲","海战"],"countries":["de","uk","fr"],"people":["希特勒"],"story":["9日，德国进攻丹麦和挪威，以空降、海运和地面行动夺取要点。英法随后介入，挪威战役把港口、铁矿运输与海上补给的战略意义集中呈现。","德国希望保障铁矿运输、控制北海及大西洋出入口，也担心英法先进入挪威。4月9日德军同时侵入丹麦和挪威，把海空运输、港口突袭与地面推进结合起来。丹麦迅速被占领，挪威军民与英法援军则继续抵抗。","盟军在北欧的行动没有迅速扭转局面，德国也付出舰船损失。战争表明，控制狭长海岸与远距离增援极为复杂，政治上宣布援助并不等于已有可执行的军事方案。","挪威战役给德国海军造成损失，但最终使德国获得重要沿海基地。英国援挪行动的挫折激化国内对政府指挥战争能力的质疑，张伯伦的领导地位动摇。北欧失败与接踵而至的西线危机，促成英国政府更换领导人。"],"perspectives":[{"country":"de","text":"意在保障北方战略位置及运输，仍需承担长期占领成本。"},{"country":"uk","text":"行动失误引发国内批评，为政府更替积累压力。"}],"sources":[{"id":"ww2dates","locator":"1940-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"挪威中立不足以隔绝双方对资源与基地的争夺，冬季战争又使干涉计划不断变化。","after":"北欧战事尚未结束，德国5月发动西线攻势，英国也在危机中迎来丘吉尔政府。"},"relatedBattles":[]},{"id":"ww2-1940-05","date":"1940-05","title":"阿登突破与敦刻尔克：退回去才能继续打","theaters":["西线"],"countries":["de","fr","uk"],"people":["希特勒","丘吉尔","古德里安"],"story":["5月10日，德国进攻荷兰、比利时和卢森堡，英法主力按照预想向比利时推进。但德军主要装甲突击力量经过阿登山区，逼近默兹河，在色当等处突破后向英吉利海峡疾进。盟军把最有力的部队送向北方，通向后方的联系却从南侧被切开。","突破并非坦克单独完成。航空火力、步兵渡河、工兵架桥与装甲推进相互配合，法国指挥、通信和预备队运用的问题又放大了危机。德国抓住了短暂机会，却也承受推进过快、侧翼暴露的风险；结果不能解释为进攻者天生更勇敢。","盟军北翼逐渐被压向敦刻尔克，英国组织撤运。海军舰艇、商船与民间船只共同参与，皇家空军在更广阔空域作战，法国等部队继续防御掩护撤退。海上撤离得以进行，来自许多环节同时支撑，而不是海滩上忽然出现一个奇迹。","大量英法军人得以撤出，却留下重装备，许多人仍遭俘虏。英国保存了继续战争的重要力量，法国北部战役却已经失败。丘吉尔刚接替张伯伦，必须一面承认灾难，一面组织英国继续抵抗；撤退的终点，正是下一阶段防御的起点。"],"perspectives":[{"country":"uk","text":"保存军队后仍需重建防御，撤离成功并非已经赢得战争。"},{"country":"fr","text":"主力被分割与后方失序叠加，国家防御迅速恶化。"}],"sources":[{"id":"ww2dates","locator":"1940-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"dunkirk","locator":"1940-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"挪威战役削弱了英国政府威信，德军又把主要攻势转向英法最关键的西线。","after":"人员得以撤回，法国本土战局却继续恶化，英国即将失去最主要的陆上盟友。"},"relatedBattles":[]},{"id":"ww2-1940-06","date":"1940-06","title":"法国停战，继续抵抗出现两条道路","theaters":["西线","外交"],"countries":["fr","de","uk","it"],"people":["贝当","戴高乐","墨索里尼"],"story":["德军进入巴黎，法国政府在军事崩溃中选择停战，22日签订对德协定。意大利也加入战争，欧洲力量格局骤变，英国失去重要大陆盟友。","德军突破法国北部防线后继续南下，法国政府撤离巴黎，对是否继续战争发生分歧。贝当主张停战并建立维希政权，戴高乐则从伦敦号召继续抵抗。法国没有一个统一而轻松的选择，军队、殖民地、舰队与海外人员都面对不同的政治和军事压力。","贝当政权在维希建立统治并走向合作，戴高乐从伦敦号召继续抵抗。法国既有占领与合作，也有流亡力量和地下抵抗，不能以政府停战概括所有法国人的选择。","英国必须考虑法国舰队是否落入德国控制，以及自身能否抵抗入侵。意大利此时参战，又把地中海和北非变成更直接的战场。法国停战改变了力量分布，却没有使战争结束；海空优势、殖民资源与抵抗组织成为继续作战的新支点。"],"perspectives":[{"country":"fr","text":"停战把国家带入占领、合作与抵抗并存的局面。"},{"country":"uk","text":"面对更直接的空袭和入侵威胁，继续战争需要守住本土与海运。"}],"sources":[{"id":"ww2dates","locator":"1940-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"敦刻尔克保存了部分盟军力量，却没有阻止德国向法国纵深推进。","after":"英国将独自承受德国西线压力，法国舰队问题与不列颠上空的争夺随即成为焦点。"},"relatedBattles":[]},{"id":"ww2-1940-07","date":"1940-07","title":"不列颠上空与盟友之间的裂痕","theaters":["空战","海战"],"countries":["uk","de","fr"],"people":["丘吉尔","戈林"],"story":["德国空军逐步扩大对英国的攻击，不列颠空战展开。雷达、地面观察、指挥网络、飞行员轮换和飞机维修共同支撑英国防御，不能把胜负只归功于某一种战斗机。","德国若要跨海入侵英国，必须先削弱英国皇家空军并争取海空行动条件。英国依靠雷达预警、地面观察、指挥中心与战斗机部队组成防御体系，把有限兵力调向真正的威胁方向。空战因此也是情报、生产、维修和组织效率的较量。","英国攻击米尔斯克比尔港法国舰队，防止军舰落入敌手的考虑造成昔日盟友人员伤亡。坚持对德作战与处理法国舰队的安全忧虑交织，也留下深刻政治裂痕。","英国攻击米尔斯克比尔的法国舰队，造成法国海军人员重大伤亡。丘吉尔政府把阻止舰队落入轴心国控制视为生死问题，法国人却承受来自旧盟友的炮火。它暴露了联盟瓦解后的残酷困境，也使自由法国争取支持更加困难。"],"perspectives":[{"country":"uk","text":"防御本土同时承担艰难且有争议的海军决策。"},{"country":"fr","text":"法国不同政治力量对英国的行动作出不同反应，合作与抵抗之路更加复杂。"}],"sources":[{"id":"ww2dates","locator":"1940-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1940-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"法国停战使英国失去大陆主力伙伴，并对法国舰队的未来充满疑虑。","after":"不列颠空战逐步升级，中国敌后战场也将在8月展开大规模破袭。"},"relatedBattles":[]},{"id":"ww2-1940-08","date":"1940-08","title":"空战高峰与华北交通破袭","theaters":["空战","中国"],"countries":["uk","de","cn","jp"],"people":["休·道丁","彭德怀"],"story":["德国空军加强攻击英国机场、设施与航空力量，英国战斗机部队在高强度出动中维持防御。损失必须通过训练、生产和维修补足，空战同样是一场组织与资源的较量。","德军加紧攻击英国雷达、机场和飞机工业，希望迫使英国战斗机升空并消耗其力量。英国飞行员承受高强度出动，但地面维修、飞行员补充和指挥调度使防空体系没有被击垮。战斗结果不能只用王牌飞行员的个人战绩解释。","20日，八路军发起百团大战，破袭华北铁路和据点体系，试图削弱日军分割根据地的能力。正面空战与敌后交通战发生在不同空间，却都指向持续作战依赖的运输和组织网络。","中国华北的百团大战以破袭铁路、公路和据点为重要内容。八路军试图打破日军利用交通线与据点分割根据地的控制，军民共同承担运输、破路与掩护任务。战役打击日军交通和据点体系，也伴随伤亡及随后更加残酷的报复与“扫荡”。"],"perspectives":[{"country":"uk","text":"保护指挥与航空力量，是阻止德国取得制空优势的关键。"},{"country":"cn","text":"破袭交通为敌后抵抗争取空间，也会面对日军报复性进攻。"}],"sources":[{"id":"ww2dates","locator":"1940-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1940-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"英国空中防御与中国敌后抵抗都围绕一个问题展开：怎样使优势敌军无法顺利使用其力量。","after":"德国9月把轰炸重点转向伦敦，日本则扩大南进布局，战争各条线开始靠近。"},"relatedBattles":["battle-hundred-regiments"]},{"id":"ww2-1940-09","date":"1940-09","title":"伦敦遭轰炸，三国同盟成形","theaters":["空战","外交","亚洲"],"countries":["de","uk","it","jp","cn"],"people":["希特勒","丘吉尔"],"story":["德国把轰炸重点更多转向伦敦等城市，平民避难、消防与救援成为日常。英国未被迫退出战争，德国跨海入侵计划被推迟，空袭却持续制造伤亡与破坏。","德军大规模轰炸伦敦，城市居民面对避难、消防、医疗与持续劳动的压力。攻击城市造成巨大灾难，却没有达到迫使英国屈服的目的；皇家空军仍保有作战能力，德国跨海入侵计划推迟。平民承受的代价，是“不列颠坚持下来”这一结论不可省略的一部分。","德意日签订三国同盟条约，日本又向法属印度支那北部推进。轴心国并非一支统一指挥的军队，但各自扩张开始更紧密牵动欧洲、东亚与美国的政策。","德意日签订三国同盟条约，日本军队进入法属印度支那北部，试图切断中国的外援交通并扩大在东南亚的地位。美国等国随之强化对日经济压力。欧洲战争、对华侵略和太平洋对抗由资源、殖民地及海运通道逐渐连接。"],"perspectives":[{"country":"uk","text":"社会韧性建立在防空、救援和供应组织之上，不能浪漫化居民承受的恐惧。"},{"country":"jp","text":"借欧洲殖民宗主国受挫扩大南方影响，也加剧美日矛盾。"}],"sources":[{"id":"ww2dates","locator":"1940-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1940-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国未能摧毁英国空军，日本又企图利用法国战败扩大在亚洲的控制。","after":"英国没有退出战争，轴心国转而在地中海与东南欧寻求新的突破。"},"relatedBattles":[]},{"id":"ww2-1940-10","date":"1940-10","title":"意大利攻希腊，扩大战争未必带来收益","theaters":["欧洲","空战"],"countries":["it","de","uk"],"people":["墨索里尼"],"story":["意大利从阿尔巴尼亚方向进攻希腊，希望取得独立军事成果。希腊抵抗和地形、补给问题使进攻受挫，意军很快面临反击，轴心国在巴尔干制造了新的战略负担。","墨索里尼从阿尔巴尼亚进攻希腊，企图以独立战果提升意大利在轴心国中的地位。意军准备不足，山地、道路和补给限制又放大困难，希腊军队抵抗后转入反攻。战争很快偏离罗马预想的短期胜利。","英国继续承受轰炸，不列颠空战的主要白昼阶段渐告结束，夜间空袭仍未停止。没有被入侵与没有遭受灾难，是两件不同的事。","意大利在希腊和北非的处境，迫使德国重新考虑东南欧与地中海安全。英国则获得支援希腊、牵制轴心国的机会，但资源本已紧张。一个盟国的失败会成为另一个盟国的负担，轴心合作的内部问题由此进入大战进程。"],"perspectives":[{"country":"it","text":"政治声望目标超出准备与后勤能力，进攻反使自身陷入困境。"},{"country":"uk","text":"本土防御稳定后仍需考虑地中海、希腊与北非的援助分配。"}],"sources":[{"id":"ww2dates","locator":"1940-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"法国战败和三国同盟带来轴心国气势，意大利急于把政治声势变成领土战果。","after":"希腊战事受挫，意大利舰队又将在塔兰托遭到攻击，地中海力量对比继续变化。"},"relatedBattles":[]},{"id":"ww2-1940-11","date":"1940-11","title":"塔兰托夜袭与城市火灾","theaters":["海战","空战"],"countries":["uk","it","de"],"people":["安德鲁·坎宁安"],"story":["英国舰载机夜袭塔兰托，重创意大利舰艇，展示航空兵威胁停泊舰队的能力。地中海补给与舰队行动条件因此变化，但这并未立即结束意大利海军的作用。","英国航空母舰派出的鱼雷机夜袭塔兰托港，对意大利主力舰造成重大打击。舰艇停在港内并不意味着安全，空中攻击能够改变传统舰队均衡。地中海航运此后仍然危险，但英国护送马耳他和北非补给的条件有所改善。","德国猛烈轰炸考文垂，城市工业与居民区遭破坏。将工厂、交通与居民生活混在一起的空袭，显示总体战如何消解前线与后方的界线，军事效果与伦理代价必须同时审视。","德国轰炸考文垂，工业设施和居民区遭到严重破坏。城市防空与工厂生产彼此交织，轰炸者宣称的军事目标无法消除对普通人的伤害。技术和工业成为战争关键，也使劳动者及其生活空间更直接地暴露于战争。"],"perspectives":[{"country":"uk","text":"既运用航空兵攻击敌舰，也在本土承受空袭。"},{"country":"it","text":"舰艇损失压缩行动选择，地中海战争更依赖基地与补给保障。"}],"sources":[{"id":"sea","locator":"1940-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1940-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利陆上进攻不顺，海军力量与英国工业城市又成为相互打击的对象。","after":"英国将在北非发动反击，而美国逐渐从军需供应者走向更明确的援英立场。"},"relatedBattles":[]},{"id":"ww2-1940-12","date":"1940-12","title":"北非反攻与“兵工厂”的承诺","theaters":["北非","后方"],"countries":["uk","it","us"],"people":["韦维尔","罗斯福"],"story":["英军在北非发动罗盘行动，击退进入埃及的意军，攻势随后向利比亚推进。沙漠战看似适合机动，燃料、运输与港口却始终限制军队能走多远。","英军“罗盘”行动从有限进攻发展为对意军的连续打击，机动部队穿插据点之间，迫使大批意军投降。北非广阔战场给机动创造空间，也使燃料、车辆维修和补给线格外重要；推进越快，并不意味着能够无限向前。","罗斯福向美国公众强调为抵抗轴心国提供军需的重要性。英国财力吃紧，美国如何在尚未参战时扩大援助，逐渐成为战略问题，战场得失与跨大西洋生产线开始更紧密连接。","罗斯福提出美国应成为“民主国家的兵工厂”，把英国能否继续抵抗与美国自身安全联系起来。英国购买军需的资金越来越紧张，传统买卖方式已难以维持。如何在尚未参战的条件下扩大援助，成为美国政府需要跨越的国内政治和法律门槛。"],"perspectives":[{"country":"it","text":"北非失利迫使其向德国寻求更多军事支持。"},{"country":"us","text":"援助理念向大规模制度安排发展，为此后的租借法铺路。"}],"sources":[{"id":"sea","locator":"1940-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"lend","locator":"1940-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"英国抵挡了德国空袭，开始争取地中海主动；长期战争又迫使它更依赖美国生产能力。","after":"北非战局将引来德国援军，美国援助则在1941年转化为租借制度。"},"relatedBattles":[]},{"id":"ww2-1941-01","date":"1941-01","title":"北非推进与皖南事变：盟友并非没有裂痕","theaters":["北非","中国"],"countries":["uk","it","cn","jp"],"people":["韦维尔","叶挺"],"story":["英联邦军在北非继续推进，巴迪亚等据点失守，意军危机加深。胜利打开更多空间，也使英国面临是否继续追击、还是把兵力调往其他战场的选择。","英国及英联邦部队继续在北非推进，意军在利比亚的防线动摇。但伦敦还必须兼顾希腊、马耳他与本土安全，胜利后的兵力分配面临争执。战争中的机会往往同时出现，而运输船、飞机和训练部队不能在不同战场无限复制。","中国发生皖南事变，新四军部队遭国民党军攻击，叶挺被扣。共同抗日并未消除内部矛盾，理解中国战场既要看合作抗敌，也要看关系破裂如何伤害共同抵抗。","中国发生皖南事变，新四军军部及所属部队遭到国民党军队袭击。国共关系遭受严重打击，中共中央重建新四军军部，继续坚持抗战。共同抵抗日本侵略的框架仍在，但内部政治冲突加深，不能用一致对外的概括抹去这一事实。"],"perspectives":[{"country":"uk","text":"北非成果需要与巴尔干援助等任务争夺兵力。"},{"country":"cn","text":"抗战统一战线遭严重冲击，但对日作战仍在继续。"}],"sources":[{"id":"nz","locator":"1941-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1941-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"北非胜利扩大了英国的行动选择，中国相持阶段的国共矛盾则继续积累。","after":"德国援军将进入北非，中英等国面对的都不只是前线作战，还有联盟与政治关系的约束。"},"relatedBattles":[]},{"id":"ww2-1941-02","date":"1941-02","title":"隆美尔抵达，沙漠战局重新打开","theaters":["北非","海战"],"countries":["de","it","uk"],"people":["隆美尔","韦维尔"],"story":["德国派部队进入北非支援意大利，隆美尔抵达利比亚。英国此前的胜利没有让战区永久稳定，新的指挥、装甲力量与空中支持开始改变对抗条件。","隆美尔率德国部队抵达北非，最初任务与意军危机相关，随后却迅速谋求反攻。装甲部队的速度需要港口卸载、长途公路运输和持续燃料供应支撑；轴心国每向东推进一段，补给距离便进一步拉长。","地中海运输仍决定双方补给。沙漠上的快速推进离不开燃油、零件和港口，任何将领的个人声望都不能代替这些条件；此后反复进退，将不断证明这一点。","北非不是只有德英将领较量的空旷棋盘。当地居民、殖民体系、意大利军队和来自英联邦多地的部队都卷入战争。理解此后的托布鲁克与阿拉曼，应把沙漠机动作战与地中海运输放在一起，否则很难解释进攻为何突然失去力量。"],"perspectives":[{"country":"de","text":"支援盟友也意味着承担另一条补给困难的战线。"},{"country":"uk","text":"需要在既有胜利后防止力量分散，保持北非后勤和预备队。"}],"sources":[{"id":"nz","locator":"1941-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1941-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意军在利比亚的失败迫使德国介入，英国此前的北非优势因此面临新的挑战。","after":"北非将重新拉锯，英国维持多个战场的能力越来越依赖跨大西洋援助。"},"relatedBattles":[]},{"id":"ww2-1941-03","date":"1941-03","title":"租借法：尚未参战的国家改变力量平衡","theaters":["外交","后方"],"countries":["us","uk","cn","su"],"people":["罗斯福"],"story":["11日，美国租借法生效，使政府能够向对其安全重要的国家提供物资。英国无力长期以现金购买军需的问题，获得新的制度性解决途径，援助随后也扩及中国和苏联等国。","租借法允许美国以出售、转让、租借等方式向其认为防卫关系美国安全的国家提供军需，突破了必须立即付款的限制。法律本身并不会把装备直接变成战场力量，工厂生产、船舶运输、港口和接收训练仍是漫长链条。","这不仅是运送武器，还包括车辆、粮食、原材料和运输支持。援助必须穿越海洋和边境才能变成战斗力，生产、航运和接收体系将成为联盟作战的重要基础。","美国因此更深地卷入援助同盟国的体系，却尚未正式成为交战国。国内反对参战的力量仍有影响，罗斯福需要在政治争论中扩大支持。租借物资后来支援英国、苏联、中国等国，联盟的基础不仅是共同声明，也逐步成为真实的生产与运输网络。"],"perspectives":[{"country":"us","text":"未正式参战却已越来越深地支持抗击轴心国。"},{"country":"uk","text":"获得长期物资来源，但航线防护仍决定援助能否抵达。"}],"sources":[{"id":"lend","locator":"1941-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"英国抵抗需要大量军需，却越来越难以按传统方式支付，美国安全观也正在变化。","after":"援助扩大之际，轴心国向巴尔干推进，英国必须在有限资源中再次选择战场。"},"relatedBattles":[]},{"id":"ww2-1941-04","date":"1941-04","title":"巴尔干遭侵，德苏中立与准备并行","theaters":["欧洲","北非","外交"],"countries":["de","uk","it","su","jp"],"people":["希特勒","隆美尔"],"story":["德国进攻南斯拉夫和希腊，盟军再度后撤，英国在地中海东部的处境恶化。北非德意军反攻并围困托布鲁克，英国需要在多个危险方向同时应对。","德军进攻南斯拉夫与希腊，装甲、空降和航空兵快速打破防御。英国派往希腊的部队随后撤退，希腊本土遭占领，抵抗运动则在以后发展。德国取得东南欧优势，却也承担新的驻军、交通和占领负担。","苏联与日本签订中立条约，暂时降低彼此边境风险。两个国家各有战略重点，协定并不意味着全球冲突缓和，反而帮助它们分别处理西部与南方问题。","苏日中立条约暂时降低双方在远东方向立即开战的风险。对日本而言，这有利于把注意力转向南方；对苏联而言，避免同时应付东西两线具有重要意义。条约没有消除双方长期戒备，也不能直接等同于苏联已经能够完全放空远东防务。"],"perspectives":[{"country":"uk","text":"巴尔干、北非和海路压力叠加，兵力调配更加艰难。"},{"country":"su","text":"希望稳定远东，同时仍需判断德国在西部边境集结的意图。"}],"sources":[{"id":"nz","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"yugoslavia","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利在希腊受挫、南斯拉夫政局变化，使德国决定直接干预巴尔干。","after":"巴尔干胜利之后，德国仍面对克里特、海上战争与即将发动的对苏侵略。"},"relatedBattles":[]},{"id":"ww2-1941-05","date":"1941-05","title":"克里特空降与俾斯麦号沉没","theaters":["欧洲","海战"],"countries":["de","uk"],"people":["希特勒","丘吉尔"],"story":["德军空降克里特岛，付出严重损失后夺取控制。空降能越过海面障碍，却仍需夺取机场、运入增援与维持补给；新型作战方式的威力与脆弱同时显露。","德军以大规模空降进攻克里特，在高昂伤亡下夺取岛屿。守军与当地民众抵抗，英国海军在德军空袭下掩护撤退。行动表明空降能够取得突击效果，也暴露轻装部队在缺乏地面火力支援时的脆弱，胜利并不意味着方法可无限重复。","德国战列舰俾斯麦号进入大西洋后遭英国舰队追击并沉没。英国失去胡德号等损失同样沉重，海上较量并未因一艘主力舰的终结而结束，潜艇战争仍持续威胁航运。","德国战列舰“俾斯麦”号出航后击沉英国“胡德”号，随后遭英国海空力量持续追击并被击沉。英国不能容忍大型袭击舰威胁运输线，而德国水面舰艇突破封锁也十分困难。海空协同与情报追踪的重要性，远超过单舰吨位带来的想象。"],"perspectives":[{"country":"de","text":"海空行动取得部分成果，却损失难以轻易补充的力量。"},{"country":"uk","text":"保护航线和基地需要跨海空协作，海军优势并不意味着没有脆弱处。"}],"sources":[{"id":"nz","locator":"1941-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1941-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国控制巴尔干后继续争夺东地中海，大西洋运输战也没有因陆上胜利而停止。","after":"西方战争尚未结束，希特勒却将在6月开辟规模更大的苏德战场。"},"relatedBattles":[]},{"id":"ww2-1941-06","date":"1941-06","title":"巴巴罗萨：侵略把欧洲推入更深灾难","theaters":["东线","平民"],"countries":["de","su"],"people":["希特勒","斯大林","朱可夫"],"story":["6月22日，德国发动“巴巴罗萨”行动，沿漫长边界入侵苏联。空袭机场、装甲穿插与大规模包围迅速打乱苏军部署，大批部队被切断联系。斯大林此前对警报的判断、苏军部署和指挥问题，都加重了最初灾难。","德军分别向列宁格勒、莫斯科方向以及乌克兰推进，试图在苏联完成全面动员前摧毁其主力。但道路、铁路、车辆维修与燃料必须跟上前锋，连续包围也需要步兵跟进处理。推进地图上的箭头很快，运输系统的延伸却没有同样容易。","苏联在后撤中动员预备队、转移工厂并重建防线，英国宣布支持苏联，未来同盟关系开始改变。早期损失十分严重，不能因此倒推出苏联注定轻易获胜；但国家仍能组织人力与生产，说明占领大片土地并不等于战争已经结束。","这场侵略还带着纳粹的种族与殖民目标，战俘遭到虐待，特别行动队等在占领区实施屠杀。前线战役、后方工业与针对平民的犯罪同时展开。德国把战争推到更大规模，也把自己推向最初计划未能承担的长期消耗。"],"perspectives":[{"country":"su","text":"国家生存危机要求动员和调整，早期失误造成巨大代价。"},{"country":"de","text":"以征服与种族政策推动战争，无法用普通安全竞争解释或开脱。"}],"sources":[{"id":"ww2dates","locator":"1941-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1941-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"barbarossa","locator":"1941-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"德国未能迫使英国屈服，却仍决定以迅速击败苏联获取资源和战略优势。","after":"包围战不断给苏军造成损失，但德国对速胜的预期将受到空间、抵抗和补给的共同挑战。"},"relatedBattles":[]},{"id":"ww2-1941-07","date":"1941-07","title":"向基辅推进，日本南进引发制裁","theaters":["东线","亚洲","外交"],"countries":["de","su","jp","us","cn"],"people":["希特勒","斯大林","近卫文麿"],"story":["德军向苏联纵深推进，斯摩棱斯克等地交战使攻势继续付出损失。苏联防线反复重组，撤退与抵抗同时进行，战争逐渐显露超出短期计划的规模。","德军持续推进时，铁路轨距、道路条件、车辆损耗和油料供应逐渐限制行动。苏军一面后撤一面重新集结，城市与工业设备向内地转移。闪击战在战役层面的成功，开始面对一个更难回答的问题：怎样在广阔地域把军事胜利转成战争结束。","日本进入法属印度支那南部，美国冻结日本资产，石油供应受到严格限制。日方把继续侵略与获取南方资源连在一起，却不愿通过结束侵华来化解危机，美日谈判因而越来越难。","日本进一步进入法属印度支那南部，美英荷等国采取冻结资产等措施，美国对日石油供应随之中断。日本领导层把撤出侵略与继续扩张获取资源摆在天平上，最终没有放弃侵略政策。资源压力解释了决策环境，却不能替发动战争卸去责任。"],"perspectives":[{"country":"jp","text":"资源压力与既有侵略目标冲突，军部逐渐倾向进一步扩大战争。"},{"country":"us","text":"以经济手段遏止扩张，制裁又促使日本重新计算开战风险。"}],"sources":[{"id":"ww2dates","locator":"1941-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"苏德战场迅速扩大，日本则利用欧洲殖民国家的困境继续向东南亚推进。","after":"东线战争将继续消耗双方力量，太平洋危机则使美国越来越接近直接参战。"},"relatedBattles":[]},{"id":"ww2-1941-08","date":"1941-08","title":"大西洋宪章与围城逼近","theaters":["外交","东线"],"countries":["uk","us","su","de"],"people":["罗斯福","丘吉尔"],"story":["罗斯福与丘吉尔会晤，发表大西洋宪章，提出战后秩序的共同原则。美国仍未正式参战，双方已尝试说明战争为何而打、结束后应建立怎样的制度。","罗斯福与丘吉尔在北大西洋会晤，发表后来被称为《大西洋宪章》的原则声明，提出反对领土扩张、民族自主与建立更广泛安全安排等目标。美国尚未正式参战，这份声明已经把战后秩序纳入援英与共同抵抗的讨论。","东线德国继续推进，列宁格勒面临合围危险。关于民族自决的原则与英国等国殖民现实之间仍有矛盾；盟国的道义目标需要与其实际政策对照，而不能只把宣言当作已经实现的事实。","原则与现实之间存在明显距离：殖民地人民如何获得自主，英美理解并不完全相同；安全理想也尚未解决眼前运输和军需问题。同盟合作将同时依靠价值声明、具体物资以及不断讨价还价的战略协调，不能只看会晤照片或口号。"],"perspectives":[{"country":"us","text":"通过共同原则支持英国，同时顾及国内对直接参战的顾虑。"},{"country":"uk","text":"希望获得更牢固的美国支持，却不愿全面放弃帝国利益。"}],"sources":[{"id":"atlantic","locator":"1941-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1941-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"英美合作逐渐超出物资买卖，但仍需应对美国中立立场与英国帝国利益的限制。","after":"对未来秩序的讨论与战争暴力并行，东线的围城、包围和屠杀在9月更加严酷。"},"relatedBattles":[]},{"id":"ww2-1941-09","date":"1941-09","title":"列宁格勒被围，基辅与巴比亚尔","theaters":["东线","平民"],"countries":["su","de"],"people":["斯大林","朱可夫"],"story":["列宁格勒陆上通道遭切断，长期围城开始，居民此后承受饥饿、寒冷与轰炸。基辅方向苏军遭到重大围歼，军事损失与乌克兰占领区的灾难同时扩大。","列宁格勒陆上联系被切断，居民在围困中面临饥饿、炮击和严寒，拉多加湖方向成为维持城市生命的重要通道。基辅方向苏军则遭到大规模包围，德国取得重大军事胜利，但苏联国家和军队并未因此失去继续作战的能力。","29日至30日，纳粹在基辅附近巴比亚尔大规模杀害犹太人。这些枪杀不是与战线无关的偶然暴行，而是侵略和种族灭绝政策在占领区实施的直接体现。","基辅附近巴比亚尔发生针对犹太人的大规模屠杀。受害者被驱赶至杀戮地点，屠杀由有组织的武装和占领体系实施。把东线只描述成坦克与将军的较量，会掩盖侵略战争与种族灭绝如何在占领区直接结合。"],"perspectives":[{"country":"su","text":"一面组织前线抵抗，一面面对城市供给和人口生存危机。"},{"country":"de","text":"军队推进与党卫队、警察等杀戮机制相互联系，责任不能只推给少数个人。"}],"sources":[{"id":"ww2dates","locator":"1941-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1941-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"barbarossa","locator":"1941-09相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"德国夏季攻势仍在取得战役胜利，苏联也在重建防线和转移工业。","after":"德军将把主要攻势指向莫斯科，但它已经耗去大量时间、车辆和人员。"},"relatedBattles":[]},{"id":"ww2-1941-10","date":"1941-10","title":"莫斯科方向与东京内阁：两场决策逼近终点","theaters":["东线","外交"],"countries":["de","su","jp","us"],"people":["希特勒","斯大林","东条英机"],"story":["德军发动台风行动，试图攻取莫斯科，苏军在维亚济马等地遭受严重损失。首都方向的危机迫使苏联加紧组织防御，泥泞、道路与日渐拉长的补给线也限制德军。","德军“台风”行动再次包围大量苏军，莫斯科一度面临严重危机。泥泞道路、拉长的运输线与持续抵抗使推进变慢，苏联则组织预备队、构筑防线并维持国家机关运作。城市能否守住，取决于兵力、供应与组织，不能简单归结为冬天是否到来。","东条英机在日本组阁，美日交涉继续，却无法调和侵华、撤军与资源政策上的冲突。两个战场看似相距遥远，实际上都显示以扩大军事行动解决既有困境的危险。","日本东条英机组阁，美日谈判继续，却与军事准备同时推进。日本要求维持侵略成果，美国要求改变对华和东南亚政策，双方核心分歧难以化解。政治与军方的期限安排不断压缩谈判空间，太平洋战争的危险已非常具体。"],"perspectives":[{"country":"su","text":"必须守住政治与交通中心，并把新部队投入防线。"},{"country":"jp","text":"政府更替未改变侵略目标的根本约束，外交选择继续收窄。"}],"sources":[{"id":"ww2dates","locator":"1941-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"东线速胜没有实现，日本又拒绝以撤出侵略换取经济关系恢复。","after":"莫斯科方向的最后突击与日本的最后开战准备，将在11月同时逼近临界点。"},"relatedBattles":[]},{"id":"ww2-1941-11","date":"1941-11","title":"莫斯科最后突击，北非再度反攻","theaters":["东线","北非"],"countries":["de","su","uk","jp","us"],"people":["朱可夫","隆美尔"],"story":["德军重新向莫斯科推进，却在损失、补给和冬季条件下越来越难维持攻势。苏军的抵抗、工业转移与增援同样关键，不能把德国受阻只归因于天气。","德军再次逼近莫斯科，但部队疲惫、装备损耗和补给困难不断累积。苏军继续投入预备力量，城市及其周边防御没有崩溃。德国仍能在地图上看到目标，却越来越难把部队保持在能够持续进攻的状态。","英国在北非发动十字军行动，争取解托布鲁克之围。太平洋方向，日本舰队已驶向珍珠港，谈判仍在进行，外交表面与军事准备之间出现危险反差。","英国在北非发动“十字军”行动，试图解除托布鲁克之围，战局反复显示沙漠推进与补给的脆弱。与此同时，日本航母突击部队秘密驶向夏威夷，海陆军也准备向东南亚多处发动进攻；珍珠港是整个南进战争计划的一环，不是孤立袭击。"],"perspectives":[{"country":"de","text":"在未能速胜后仍试图取得决定性结果，部队承受力逼近极限。"},{"country":"uk","text":"重新争夺北非主动，同时要准备应对远东风险。"}],"sources":[{"id":"nz","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国在东线消耗积累，英国争取北非主动，日本则接近把谈判失败转化为战争。","after":"12月的莫斯科反攻和珍珠港袭击将同时改变战争规模与同盟关系。"},"relatedBattles":[]},{"id":"ww2-1941-12","date":"1941-12","title":"莫斯科反攻、珍珠港与真正全球化的战争","theaters":["东线","太平洋","外交"],"countries":["su","de","jp","us","uk","cn"],"people":["罗斯福","山本五十六","朱可夫","丘吉尔"],"story":["苏军在莫斯科方向反攻，击退德军，德国无法在1941年结束对苏战争。几乎同时，7日日本袭击夏威夷珍珠港；按亚洲当地时间，8日前后日军又向马来亚、香港、菲律宾等地展开进攻。","苏军在莫斯科方向发动反攻，迫使德军后退，德国短期击溃苏联的目标破产。反攻没有立即结束东线战争，苏军同样面临损失和运输困难，但德国此后必须准备一场远超原先设想的长期消耗战。","日本袭击珍珠港并进攻东南亚等地，美国对日宣战，德国、意大利随后对美宣战。珍珠港遭受重创，但美国航母未在港内，工业和修复能力也没有被摧毁。日本赢得最初行动空间，却把战争对手扩大为拥有巨大生产能力的联盟，全球各战场由此更紧密地连在一起。","美国对日宣战，德国、意大利随后对美宣战，中国正式对日、德、意宣战，欧洲与亚洲战争更加紧密连成全球冲突。珍珠港重创美国部分舰艇，却没有摧毁其工业与长期动员能力。","日本希望通过突袭和建立广阔防御圈迫使对手妥协，实际上唤起了资源更强大的敌手。此后应同时阅读太平洋舰队作战、中国长期抵抗、苏德陆战与跨大西洋补给，才能理解联盟如何形成合力。"],"perspectives":[{"country":"us","text":"从援助者转为正式交战国，需要同时制定欧洲与太平洋战略。"},{"country":"cn","text":"长期抗战进入更广泛的同盟合作，外援机会增加，但运输与协调仍受限制。"}],"sources":[{"id":"ww2dates","locator":"1941-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"barbarossa","locator":"1941-12相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"德国与日本都试图通过决定性一击解决战略困境，却低估了对手持续组织战争的能力。","after":"共同敌人促成联合国家合作，但最初几个月，同盟国仍将接连承受失败。"},"relatedBattles":[]},{"id":"ww2-1942-01","date":"1942-01","title":"联合国家宣言与万湖会议","theaters":["外交","平民"],"countries":["us","uk","su","cn","de","jp"],"people":["罗斯福","丘吉尔","海德里希"],"story":["1日，中美英苏等26国签署联合国家宣言，承诺共同对抗轴心国、不单独媾和。联盟开始形成政治框架，但各国对优先战场和战后利益仍有分歧。","《联合国家宣言》把不同制度和利益的国家联合在继续抗击轴心国、不单独媾和的承诺下。它不是今天联合国组织已经成立，却为后来合作提供名称和政治基础。共同宣言仍需通过分配船舶、军需和进攻方向，才能变成实际的同盟力量。","20日，纳粹官员在万湖会议上协调驱逐与屠杀欧洲犹太人的行政合作。大规模杀戮此前已经进行，会议并不是种族灭绝突然开始的唯一决策点，而是扩大并组织犯罪的重要环节。","柏林近郊的万湖会议协调对欧洲犹太人实施灭绝的行政安排。屠杀在会议前已经发生，会议不能被误写为种族灭绝的唯一起点；它显示不同政府部门如何参与组织驱逐与杀害。战争扩大使纳粹控制更多人口，也使犯罪机器扩张。"],"perspectives":[{"country":"cn","text":"成为共同宣言签署国之一，国际地位提升与战场困境同时存在。"},{"country":"de","text":"官僚协调使杀戮跨部门运转，行政语言掩盖不了犯罪实质。"}],"sources":[{"id":"wannsee","locator":"1942-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"美国和苏联先后加入战争，反轴心国合作需要共同承诺，而纳粹暴力也正在升级。","after":"共同阵线刚刚形成，东南亚的接连失败却使同盟国面临严峻考验。"},"relatedBattles":[]},{"id":"ww2-1942-02","date":"1942-02","title":"新加坡陷落，日裔美国人遭强制拘禁","theaters":["亚洲","后方"],"countries":["jp","uk","us"],"people":["山下奉文","珀西瓦尔","罗斯福"],"story":["15日，新加坡守军向日军投降，英国在东南亚遭受重大失败。海军基地声望无法弥补陆上防御、空中力量和指挥判断的缺陷，殖民统治的不可战胜形象受到打击。","新加坡被称为英国在远东的重要堡垒，但防御不能只靠海岸炮台。日军从马来半岛陆路推进，突破后从北面进攻新加坡；守军在空中支援、指挥、补给和部署上陷入困境，最终投降。殖民体系宣称的安全与优势因此遭到沉重打击。","美国总统签署9066号行政命令，此后大量日裔居民被迫迁离和拘禁。战争恐惧、种族偏见与国家权力结合，损害了许多公民的权利，反法西斯战争中的盟国内部同样存在必须反思的不义。","美国政府授权将日裔居民等从西海岸指定地区强制迁移，许多美国公民也遭拘禁。安全恐慌和长期种族偏见交织，使公民权利被集体剥夺。把同盟国的抵抗正当性与其内部不公同时记录，才能避免将战争写成毫无阴影的胜利故事。"],"perspectives":[{"country":"uk","text":"必须重建远东防线，也面临殖民威信动摇。"},{"country":"us","text":"动员战争不应成为以族裔代替个体证据、剥夺权利的理由。"}],"sources":[{"id":"nz","locator":"1942-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1942-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本利用战争初期的海空优势快速推进，同盟国还没有建立有效联合防御。","after":"新加坡失陷后，缅甸和菲律宾的局势进一步恶化，中国外援通道也受到威胁。"},"relatedBattles":[]},{"id":"ww2-1942-03","date":"1942-03","title":"仰光失守，通往中国的道路被切断","theaters":["亚洲","中国"],"countries":["jp","uk","cn","us"],"people":["史迪威","蒋介石"],"story":["日军进入仰光，缅甸战局恶化。这里不仅是英国殖民地的港口，也连接通向中国的运输体系；港口失守，使中国坚持长期抗战所依赖的国际补给受到直接威胁。中国远征军进入缅甸，与英军共同对日作战。","合作面对着现实障碍：各军指挥关系复杂，对保卫哪些地区、何时撤退、撤向哪里并不总能一致。军需紧缺和道路困难，使决定更加急迫。战区之间的联系不再只是会议上的共同目标，而是运输车能否通行、部队能否得到弹药的具体问题。","麦克阿瑟奉命离开菲律宾前往澳大利亚，留下的守军继续抵抗。澳大利亚逐步成为盟军在西南太平洋的重要基地，英美被迫在退却中重新安排战略。撤出指挥官并不意味着留下者同时获得安全，许多军人和平民随后经历俘虏与暴力。","日本占领范围快速扩大，守备与海运负担也随之增长。同盟国此时还不能立即反攻，但正在寻找维持中国抵抗、保住澳大利亚方向基地的新办法。接下来缅甸的全面撤退与新的空运体系，会把这些难题进一步推到眼前。"],"perspectives":[{"country":"cn","text":"必须在援缅、保卫运输线与本土作战之间分配有限力量。"},{"country":"jp","text":"快速推进扩大占领范围，也把补给线和守备任务拉得更长。"}],"sources":[{"id":"nz","locator":"1942-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1942-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"新加坡失陷撕开东南亚防御，中国、英国和美国需要在退却中重新组织合作。","after":"菲律宾守军将遭遇投降与虐待，缅甸撤退也把中国补给问题推向更艰难的阶段。"},"relatedBattles":[]},{"id":"ww2-1942-04","date":"1942-04","title":"巴丹投降与杜立特空袭","theaters":["太平洋","中国"],"countries":["us","jp","cn"],"people":["杜立特","麦克阿瑟"],"story":["巴丹守军投降后，战俘遭受死亡行军等严重虐待。军事失败之后的人道灾难，是理解日本占领与军队责任不可分割的一部分。","巴丹守军在饥饿、疾病和缺乏补给中坚持后投降，日军随后强迫大批战俘长途行进，沿途施以殴打、杀害并拒绝基本照料。“巴丹死亡行军”必须作为战俘遭虐待的战争罪行理解，不能只是战役结束后的一个名称。","18日，美军轰炸机从航母起飞空袭日本，随后飞向中国方向。行动提升美国士气，军事破坏有限，却带来深远反应；中国部分地区又遭日军报复性军事行动与暴行，战争的象征收益与他处承担的代价并不对称。","杜立特率轰炸机从航母起飞空袭日本，军事破坏有限，却改变了日本社会对本土安全的认识。部分机组人员在中国军民帮助下脱险，日军随后在中国实施残酷报复。一次振奋美国士气的行动，同时给中国平民带来巨大代价，跨战场联系在这里格外鲜明。"],"perspectives":[{"country":"us","text":"以有限突袭争取士气和主动，但无法单靠一次行动改变战局。"},{"country":"cn","text":"援助飞行员与承受报复的经历，体现盟国行动后果可能由不同群体分担。"}],"sources":[{"id":"nz","locator":"1942-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本初期攻势接连得手，美国急需恢复主动，同盟国守军则在孤立中耗尽资源。","after":"日本寻求扩大防御圈，航母舰队的对决将在珊瑚海与中途岛决定下一阶段主动权。"},"relatedBattles":[]},{"id":"ww2-1942-05","date":"1942-05","title":"珊瑚海与缅甸撤退：海路被拦，陆路仍险","theaters":["太平洋","亚洲"],"countries":["us","jp","uk","cn"],"people":["尼米兹","史迪威"],"story":["珊瑚海海战中，美日航母航空兵交战，日本从海上夺取莫尔兹比港的计划受阻。舰队可以在彼此不直接目视的情况下作战，侦察与飞机调度成为核心。","珊瑚海海战主要由舰载机实施攻击，交战主力舰队没有像传统海战那样彼此炮击。盟军虽然损失重要舰艇，却阻止日本经海路夺取莫尔兹比港的企图，日本也有航母受损或航空兵损耗，影响后续部署。战果需要同时从战术损失和战略目标判断。","缅甸盟军继续撤退，中国部队一部分退入印度，另一部分艰难回国，运输线中断加重中国处境。海上的一次阻击，并没有立即解除陆地盟友的困境。","缅甸战局恶化，中国远征军和英军撤退，部分部队穿越环境恶劣的地区，伤亡严重。滇缅公路中断后，通往中国的“驼峰”空运逐步承担更大任务。地图上一条道路被切断，意味着飞行员、运输人员和前线军队都必须改变维持战争的方式。"],"perspectives":[{"country":"us","text":"航母成为阻止日军推进的重要工具，损失仍需工业体系补充。"},{"country":"cn","text":"远征失利与交通切断，使后方补给和作战协调更为艰难。"}],"sources":[{"id":"nz","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本继续向南太平洋扩张，中国外援陆路则因缅甸失守而断裂。","after":"海空力量将在中途岛再次集中，北非战局却在同一时期向轴心国倾斜。"},"relatedBattles":[]},{"id":"ww2-1942-06","date":"1942-06","title":"中途岛与托布鲁克：转折并非同时发生","theaters":["太平洋","北非"],"countries":["us","jp","uk","de","it"],"people":["尼米兹","南云忠一","隆美尔"],"story":["日本试图进攻中途岛，引出并消灭美国航母力量。美国利用通信情报判断日军目标，由尼米兹集中有限航母兵力迎战。情报提供了预警和部署机会，却不能替代侦察、飞行员攻击与舰队在战斗中的判断。","交战中双方不断寻找对方航母，舰载机需要在搜索、护航、攻击和返航之间安排时间。美军多轮攻击付出严重损失后，俯冲轰炸机击中日军航母；日本最终损失四艘主力航母，美国也失去约克城号等力量。不能把复杂过程压成一条毫无悬念的密码胜利。","损失不只是舰体：训练有素的航空和舰上人员、甲板运作经验与后续补充都关系长期能力。日本仍保有强大舰队，却更难按原先节奏继续扩张；美国则开始获得争取主动的条件，随后瓜岛战役还要检验能否把机会变成持续反攻。","北非却传来相反战报。德意军攻占托布鲁克，向埃及推进，英国再次面对保卫苏伊士方向的危机。一个战场的胜利不是全球局势已经全面逆转，盟军必须在不同方向的需求间分配船舶、飞机和增援，才能逐步把资源优势变成共同优势。"],"perspectives":[{"country":"jp","text":"航母和训练有素的人员损失，削弱持续扩张能力。"},{"country":"uk","text":"必须守住埃及方向，补救指挥和补给上的危机。"}],"sources":[{"id":"nz","locator":"1942-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本希望消灭美国航母威胁，隆美尔则试图把北非战术胜利扩展为战略突破。","after":"轴心军在非洲与苏联南部同时推进，但距离、燃料和兵力分散将逐渐暴露问题。"},"relatedBattles":["battle-midway-1942"]},{"id":"ww2-1942-07","date":"1942-07","title":"斯大林格勒方向与第一次阿拉曼","theaters":["东线","北非"],"countries":["su","de","uk","it"],"people":["斯大林","保卢斯","奥金莱克"],"story":["德军夏季攻势向苏联南部展开，目标牵涉高加索石油与伏尔加交通。扩大目标使兵力分散，苏军后撤中重新设防，斯大林格勒逐渐成为关键焦点。","德国“蓝色方案”把南方攻势指向高加索油田和伏尔加河方向。石油对德国战争能力极其重要，但同时追求多个目标使部队分散、补给线拉长。斯大林格勒既关系交通与工业，也被双方赋予政治象征意义，最终吸收越来越多兵力。","北非英国在阿拉曼方向遏止德意军推进，通向埃及腹地的道路未被打开。两个战场都说明，进攻的地理终点还没有到达，补给与兵力的承受终点却可能先行出现。","北非的第一次阿拉曼战役阻止轴心军继续向东推进。阿拉曼地形缩小了大范围迂回的空间，双方开始围绕阵地、雷区和补给积聚力量。德国与意大利尚未全面失去主动，但此前快速推进的节奏已经受到限制。"],"perspectives":[{"country":"de","text":"企图同时夺取资源与交通中心，却面临长距离补给压力。"},{"country":"su","text":"在严重危机中继续动员，城市守备与外围重组同时进行。"}],"sources":[{"id":"ww2dates","locator":"1942-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-07相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"托布鲁克失陷和东线夏季攻势使轴心国看似接近更大突破。","after":"德国的目标将越来越集中到斯大林格勒，太平洋的瓜达尔卡纳尔又打开新的消耗战。"},"relatedBattles":[]},{"id":"ww2-1942-08","date":"1942-08","title":"瓜达尔卡纳尔登陆，伏尔加河畔战斗逼近","theaters":["太平洋","东线"],"countries":["us","jp","su","de"],"people":["范德格里夫","崔可夫"],"story":["7日，美军登陆瓜达尔卡纳尔等岛屿，争夺机场和海上交通。战斗很快由登陆成功转为长期补给与岛周海空争夺，驻岛士兵能否获得粮弹成为核心。","美军登陆瓜达尔卡纳尔岛，夺取未完成的日军机场并加以使用。此后岛上防御与周边海空战紧密相连：谁能送来粮食、弹药与增援，谁才能维持地面战斗。航母和巡洋舰损失之外，运输船与补给效率同样决定战役走向。","斯大林格勒遭猛烈空袭，城市破坏和居民苦难迅速扩大，德军逐步逼近城区。海岛与工业城市的战斗形态不同，却都把军事目标与平民生活彻底搅在一起。","德军抵达斯大林格勒，空袭摧毁大片城区，平民承受灾难，苏军仍从伏尔加河东岸向城内输送人员与物资。城市废墟使进攻无法简单依靠装甲速度解决，德军被逐步吸入近距离争夺，侧翼却由战力和装备较弱的盟军部队承担。"],"perspectives":[{"country":"us","text":"首次重要反攻需要持续运输支持，登陆并非战役结束。"},{"country":"su","text":"保卫城市与转运居民、伤员、部队面临巨大压力。"}],"sources":[{"id":"ww2dates","locator":"1942-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-08相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"中途岛削弱日本航母力量，德国南方攻势则把战线延伸到伏尔加河与高加索。","after":"瓜岛和斯大林格勒都将成为补给、意志与兵力消耗的持久较量。"},"relatedBattles":[]},{"id":"ww2-1942-09","date":"1942-09","title":"街道与丛林：攻势陷入近距离消耗","theaters":["东线","太平洋"],"countries":["su","de","us","jp"],"people":["崔可夫","保卢斯"],"story":["斯大林格勒市区出现持续街巷和工厂争夺，苏军依靠伏尔加河通道维持兵员与物资。德军即使占住许多街区，也未能把城市抵抗完全消灭。","斯大林格勒的工厂、车站和住宅成为反复争夺的据点，苏军缩小与德军的距离，削弱德国航空与炮火的使用效果。城内防御的意义不仅是守住象征，它也使德军主力持续投入正面，为苏军在城外准备反攻争取时间。","瓜岛日军反复攻击美军阵地，在运输困难与作战失利中不断消耗。远距离指挥把小范围战斗当作必须赢得的关键，双方都被迫向局部投入越来越多资源，消耗本身开始改变全局。","瓜岛上日军试图夺回机场，美军依托机场航空兵威胁日军海运，日方则大量依赖夜间舰艇输送。快速军舰能够带来人员，却难以稳定运输足够重装备和补给。双方的战术表现必须放在这个运输困境中理解，地面进攻并非独立发生。"],"perspectives":[{"country":"su","text":"守住有限阵地为外围筹划反攻争取时间。"},{"country":"jp","text":"低估守军与补给困难，增援未能形成可持续优势。"}],"sources":[{"id":"ww2dates","locator":"1942-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-09相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"8月打开的两个战场都没有迅速结束，进攻者开始陷入难以退出的消耗。","after":"同盟国一面坚持防御，一面集结反攻力量，10月至11月的行动将逐步改变局势。"},"relatedBattles":[]},{"id":"ww2-1942-10","date":"1942-10","title":"阿拉曼反攻：准备工作走到前台","theaters":["北非","太平洋"],"countries":["uk","de","it","us","jp"],"people":["蒙哥马利","隆美尔"],"story":["23日，英国第八集团军在阿拉曼发起进攻。集中补给、炮兵、工程破障与兵力组织，为突破德意防线提供基础，胜利不能只用两名将领的个人较量解释。","第二次阿拉曼战役在充分准备后展开，英军以火力、工兵、装甲和步兵配合穿越雷区，反复消耗轴心军防御。蒙哥马利的指挥依赖此前积累的兵力和供应优势，突破也并非在第一夜就轻易完成，持续压力最终迫使对手撤退。","瓜岛海空战仍在继续，双方航母与舰船继续遭受损失。到这一阶段，轴心国还能进行激烈作战，却越来越难以补充人员、航空兵与航运损失，持续生产和训练体系的差距开始显现。","瓜岛日军再次发动地面进攻，同时争夺周边海域的战斗继续消耗双方舰艇与航空兵。美国也付出昂贵代价，却逐步获得更有利的补给条件。北非和太平洋的变化共同说明，稳定积累并运用资源，开始比最初的进攻冲劲更加重要。"],"perspectives":[{"country":"uk","text":"准备和后勤让兵力优势有条件转为实际成果。"},{"country":"de","text":"北非防御受到持续压力，资源补充又与欧洲其他战场竞争。"}],"sources":[{"id":"nz","locator":"1942-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-10相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"轴心国推进放缓后，同盟国在若干关键地区有了准备反攻的时间。","after":"11月将同时出现北非登陆、苏军大包围和瓜岛海战，转折由多场行动叠加形成。"},"relatedBattles":[]},{"id":"ww2-1942-11","date":"1942-11","title":"三个战场的转向：包围、登陆与海上补给","theaters":["东线","北非","太平洋"],"countries":["su","de","uk","us","it","jp"],"people":["朱可夫","华西列夫斯基","艾森豪威尔","蒙哥马利"],"story":["阿拉曼胜利后德意军后撤，11月8日英美“火炬”行动在法属北非登陆。盟军不只是面对轴心军，也要处理维希法国部队的抵抗与立场变化。德国随后占领法国南部，北非战局改变又牵动欧洲政治与军事部署。","轴心国仍向突尼斯增援，企图保住北非最后立足点；英美与从埃及向西推进的英军则寻求夹击。登陆本身没有马上结束北非战争，港口、道路、山地和冬季条件都将限制行动，新到战场的部队也仍需学习协同。","19日苏军发动“天王星”行动，没有一味冲击斯大林格勒城内最强正面，而是攻击轴心国较薄弱的侧翼。23日前后，德军第六集团军等部遭合围。城内坚守牵住德军主力，城外积聚的苏军由此把战局从争城转成围歼。","希特勒要求被围部队固守，空运保障却难以满足实际需求。德军面临突围、等待解救与继续消耗的选择；此前越深入城市，重新转移就越困难。包围圈并非战斗的终点，解围与阻击将在12月继续。","太平洋瓜岛附近海战又削弱日本输送重装备和支援岛上攻势的能力。三条战线并不是同一场战役，却在同一时期迫使轴心国更多地应付对手主动行动。所谓转折，正由不同地区长期积累的准备、抵抗和消耗共同形成。"],"perspectives":[{"country":"su","text":"将城市坚守转化为外围包围，战略主动开始明显变化。"},{"country":"us","text":"首次大规模进入北非，需要在实战中学习联盟协调与陆战。"}],"sources":[{"id":"ww2dates","locator":"1942-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-11相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"夏季以来的消耗暴露轴心军兵力和补给弱点，同盟国开始把积累的力量投入反攻。","after":"被围德军等待解救，轴心国在北非增援突尼斯，转折之后仍有激烈争夺。"},"relatedBattles":["battle-stalingrad"]},{"id":"ww2-1942-12","date":"1942-12","title":"解围失败，反应堆启动：战争的两种未来","theaters":["东线","后方"],"countries":["de","su","us"],"people":["曼施坦因","保卢斯","费米"],"story":["德军尝试从外线解救斯大林格勒被围部队，未能接通包围圈；苏军继续扩大压力，空运也不足以维持被围大军。坚持守城的命令，把士兵命运与越来越不现实的期待绑在一起。","德军从外围发动解围攻势，却未能与斯大林格勒被围部队会合。苏军扩大对德军侧翼与后方的打击，解围力量不得不考虑自身安全。被围部队缺乏燃料、补给和撤出命令，空中运输的承诺无法弥补实际运力与恶劣条件的差距。","芝加哥出现受控核链式反应的重要实验进展，为曼哈顿计划提供基础。此时核武器尚未用于战场，科研、工业和秘密国家工程却已开始构成另一条将深刻影响战争结局与战后安全的线索。","费米团队在芝加哥实现可控核链式反应，为核武器研制跨出关键一步。实验本身还不是原子弹，制造武器仍需巨大的工业、材料和工程体系。前线战局与实验室成果处于不同空间，却将在1945年以极其严峻的方式交汇。"],"perspectives":[{"country":"de","text":"政治命令、军事判断和补给现实之间的冲突愈加尖锐。"},{"country":"us","text":"投入巨大科研资源的同时，也将面临这种武器如何使用的道德与政治问题。"}],"sources":[{"id":"nz","locator":"1942-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"atomic","locator":"1942-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1942-12相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"11月的大包围并未立刻结束斯大林格勒战役，双方仍围绕突破与封锁作最后努力。","after":"解围失败使被围德军结局逐渐明朗，同盟国也开始讨论下一阶段进攻和战争目标。"},"relatedBattles":[]},{"id":"ww2-1943-01","date":"1943-01","title":"卡萨布兰卡与列宁格勒通道","theaters":["外交","东线"],"countries":["us","uk","su","de"],"people":["罗斯福","丘吉尔"],"story":["罗斯福与丘吉尔在卡萨布兰卡讨论战争方向，提出要求轴心国无条件投降。盟国需要说明如何结束战争，也仍在争论先攻意大利还是尽早跨海进入法国。","卡萨布兰卡会议协调英美战略，决定继续推进地中海作战，并提出要求轴心国无条件投降。这个口号意在显示继续战争的决心，也涉及怎样防止单独媾和及如何处置战败国；同盟内部对优先战场和战后安排仍有不同考虑。","苏军打通通往列宁格勒的有限陆上走廊，改善围城居民与守军处境，但围困尚未完全解除。斯大林格勒包围圈继续缩小，德国大军的末日已近，平民与士兵的苦难却未因胜利接近而立即结束。","苏军在列宁格勒方向打通狭窄陆上走廊，改善了城市补给条件，但围城尚未完全结束。居民此前承受的饥饿和大量死亡，不能被一项军事突破轻轻带过。前线逐渐反攻的同时，解救城市和恢复普通人的生存条件仍需长期努力。"],"perspectives":[{"country":"uk","text":"主张地中海行动，需与美国对跨海进攻的期待协调。"},{"country":"su","text":"希望西方分担德军压力，同时继续以自身陆上攻势改变战局。"}],"sources":[{"id":"nz","locator":"1943-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1943-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1943-01相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"斯大林格勒包围收紧，同盟国开始筹划怎样把局部转折扩展成连续攻势。","after":"2月斯大林格勒与瓜岛将先后迎来阶段性结局，但同盟国在北非仍需学习如何作战。"},"relatedBattles":[]},{"id":"ww2-1943-02","date":"1943-02","title":"斯大林格勒投降，瓜岛日军撤离","theaters":["东线","太平洋","北非"],"countries":["su","de","us","jp"],"people":["保卢斯","崔可夫"],"story":["2月2日，斯大林格勒最后被围德军投降，保卢斯此前已成为苏军战俘。德国失去重要军队，纳粹宣传也无法继续维持此前的胜利叙事。苏联获得巨大鼓舞，付出的却是城市毁坏和军民沉重牺牲，胜利不能只用投降人数表达。","从夏季退却到冬季合围，苏军不断调整组织和作战方式。城内部队牵制德军，外围集结的力量攻击侧翼，持续补给与预备队投入支撑反攻。它不是预先安排好的一场诱敌神话，也不意味着今后苏军每次进攻都会成功。","日本同月完成瓜岛撤军，承认无法以可接受的代价夺回机场。海军仍能实施撤离，但此前长期运输不足已经使岛上部队深受饥饿、疾病和伤亡之苦。退出局部战场保存了一些力量，却把进一步争取主动的机会交给了同盟国。","北非卡塞林隘口一带，美军遭德国装甲部队打击，暴露部署、指挥和兵种协同不足。同月的两场重大胜利与一次明显挫折并置，可以看到同盟国正在变强，也仍要学习；战略趋势并不会自动保护具体部队免于失败。"],"perspectives":[{"country":"su","text":"城市防御与外围反攻结合取得成果，伤亡和重建代价极其巨大。"},{"country":"jp","text":"放弃难以补给的阵地，战略防御压力从此持续扩大。"}],"sources":[{"id":"ww2dates","locator":"1943-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"stalingrad-deep","locator":"1943-02相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"被围德军已经无力恢复补给，日本也越来越难以维持瓜岛部队。","after":"同盟国的主动权正在扩大，德军3月的哈尔科夫反击却将提醒对手不能低估其作战能力。"},"relatedBattles":["battle-stalingrad"]},{"id":"ww2-1943-03","date":"1943-03","title":"哈尔科夫反击：转折之后仍有反复","theaters":["东线","亚洲"],"countries":["de","su","us","jp"],"people":["曼施坦因","史迪威"],"story":["德军反击夺回哈尔科夫，表明斯大林格勒之后德国仍保有强大战役能力。苏军推进过快、战线展开和补给问题提供了机会，战争转折并不意味着之后每一次交战都必然获胜。","苏军冬季攻势在连续推进后出现补给拉长与部队疲惫，德军利用这一时机在哈尔科夫方向反击并重新夺城。曼施泰因的作战显示德军仍有机动作战能力，也说明一次决定性胜利不能免除后续进攻的风险与组织问题。","缅甸等地盟军探索远程渗透和改善作战方法，运输与疾病依然制约行动。各战区都在积累经验，而下一轮大规模决战正在准备。","缅甸地区的英军作战与深入敌后的行动，继续探索在丛林、山地和交通困难条件下的战争方式。这些经验涉及空中补给、疾病防治和小部队行动，但代价高昂，不能把勇敢的远程渗透直接等同于全战区的战略成功。"],"perspectives":[{"country":"de","text":"局部反击恢复一定态势，却无法重新获得1941年的总体条件。"},{"country":"su","text":"需要巩固防御与预备队，避免胜利后的过度延伸。"}],"sources":[{"id":"ww2dates","locator":"1943-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"斯大林格勒和瓜岛的胜利鼓舞同盟国，持续推进却也使弱点暴露。","after":"东线逐渐形成库尔斯克突出部，双方将用数月时间准备下一轮大会战。"},"relatedBattles":[]},{"id":"ww2-1943-04","date":"1943-04","title":"华沙隔都起义：被迫害者不是没有抵抗","theaters":["平民","东线"],"countries":["pl","de","su"],"people":["莫尔德哈伊·阿涅莱维奇"],"story":["19日，华沙隔都中的犹太抵抗者在德军准备进一步驱逐时起义。武器与补给极为有限，抵抗面对的是国家组织的屠杀机器，不能用正规军胜负标准衡量其意义。","华沙隔都内的犹太抵抗者在面临驱逐和杀害时举起武器。武器匮乏、外援有限，他们仍利用街巷、地下掩体和隐蔽通道抵抗德军。起义无法以常规军事胜负衡量，它是被剥夺生存权的人对灭绝政策的反抗，也是留给后世的重要见证。","纳粹镇压并毁坏隔都，幸存者仍面临被捕和杀害。同期卡廷屠杀墓地的发现引发波兰流亡政府与苏联关系危机，盟国内部对责任和未来安排的冲突也不能因共同抗德而略去。","德国公布卡廷森林发现波兰军官遗骸，苏联否认责任，并与要求调查的波兰流亡政府断交。杀害波兰战俘的责任后来得到苏方承认。战争中的宣传利用与案件真实责任必须分开判断：揭露者的动机并不能使罪行证据失去意义。"],"perspectives":[{"country":"pl","text":"犹太居民的抵抗与波兰国家命运相互交织，但各群体经历并不相同。"},{"country":"su","text":"与波兰关系恶化影响战后政治安排，历史责任须以证据辨认。"}],"sources":[{"id":"ghetto","locator":"1943-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"katyn","locator":"1943-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"纳粹对犹太人的驱逐和杀害持续升级，波兰人民同时承受占领与大国安排的伤害。","after":"同盟合作仍在推进，但波兰问题和如何面对暴行证据的分歧，将延续到战后。"},"relatedBattles":[]},{"id":"ww2-1943-05","date":"1943-05","title":"突尼斯投降，大西洋运输形势改善","theaters":["北非","海战"],"countries":["uk","us","de","it"],"people":["艾森豪威尔","蒙哥马利"],"story":["轴心国在突尼斯的部队投降，北非战役主要阶段结束。盟军从东西两个方向压缩对手，海空力量与补给优势终于使轴心国难以继续维持立足点。","轴心国在突尼斯的部队投降，北非战事告一段落。英美从东西两侧推进，与海空拦截共同削弱对手的增援和补给，最终使轴心国失去北非立足点。胜利打开进攻地中海岛屿的机会，也需要继续处理法国各派和当地社会的政治关系。","大西洋反潜在护航、航空、雷达与情报协作下取得明显进展，德国潜艇损失加重。安全抵达的货物与部队，为后来登陆欧洲提供条件，海战的成果正在转化为大陆作战能力。","大西洋护航战出现重要转折。雷达、远程巡逻机、护航航母、密码情报和训练改进共同压缩潜艇活动空间，德国潜艇遭受严重损失。不是某一项技术单独赢得海战，而是一套协同系统逐步成熟，使同盟国的工业产能更可靠地抵达战场。"],"perspectives":[{"country":"us","text":"北非实战与跨国指挥经验，为更大规模行动铺路。"},{"country":"de","text":"潜艇无法切断盟国海运，长期资源竞争更加不利。"}],"sources":[{"id":"nz","locator":"1943-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1943-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"北非轴心军已被压缩到狭小区域，长期运输战也开始显现同盟国组织与技术积累的成效。","after":"运输改善支撑更多跨海行动，库尔斯克和西西里的大战准备同时进入最后阶段。"},"relatedBattles":[]},{"id":"ww2-1943-06","date":"1943-06","title":"库尔斯克之前：等待也是战争的一部分","theaters":["东线","后方"],"countries":["su","de","us","uk"],"people":["朱可夫","希特勒"],"story":["德军准备攻击库尔斯克突出部，苏军修筑纵深防御、布雷并集结预备队。情报与准备使防守不再只是被动等待，工业恢复和兵力组织开始改变下一次决战的条件。","德军准备切断库尔斯克突出部，苏军则根据情报构筑纵深防线，配置雷区、炮兵、反坦克阵地与预备部队。双方都明白即将交战，但知道对手可能进攻，不等于战斗可以轻松取胜；工事、训练和后续反攻准备仍需落实。","西方盟军筹备西西里登陆，争论和计划必须落实为船只、训练、港口与航空保障。一个月没有新的决定性会战，也不等于战争停顿，未来战果常由这些不显眼的准备决定。","英美在地中海集结兵力准备登陆西西里，计划同时涉及海空掩护、登陆运输和欺骗行动。苏联仍希望尽快在法国开辟第二战场，英美则选择先在地中海行动。联盟的共同目标之下，始终存在时间表、风险与资源分配的争论。"],"perspectives":[{"country":"su","text":"准备承受进攻后转入反击，依靠纵深和预备力量。"},{"country":"de","text":"推迟进攻有利于装备补充，也给对手更多筑垒时间。"}],"sources":[{"id":"ww2dates","locator":"1943-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"北非胜利使英美能向欧洲进军，东线则在春季拉锯后积聚下一场大会战的力量。","after":"7月两场大行动几乎同时展开，德国与意大利将面对彼此牵动的危机。"},"relatedBattles":[]},{"id":"ww2-1943-07","date":"1943-07","title":"库尔斯克、西西里与墨索里尼倒台","theaters":["东线","欧洲"],"countries":["su","de","uk","us","it"],"people":["朱可夫","希特勒","墨索里尼"],"story":["5日，德军进攻库尔斯克，苏军在纵深防御中阻击并转入反攻。装甲战只是整个会战的一部分，炮兵、步兵、工事与预备队同样重要，不能以一场坦克遭遇概括全部。","德军进攻库尔斯克突出部，遭遇苏军预先构筑的多层防御，苏军随后发动反攻。普罗霍罗夫卡等装甲战十分激烈，但整场会战不能压缩成单日坦克对撞，也不宜沿用未经核实的最大数量和战损传说。重要变化是德军未能重获东线战略主动。","英美登陆西西里，意大利军事失利加剧国内政治危机，墨索里尼被解除职务并被捕。德国因此既要考虑东线，又要应付盟国可能退出战争的风险。意大利法西斯政权动摇，不等于意大利人民马上获得和平，德国干预将使半岛继续成为战场。","盟军登陆西西里，意大利统治集团的危机加剧。25日，墨索里尼被解除职务并遭逮捕，法西斯政权失去原有支撑，但德国不会因此放弃控制意大利。","军事失利如何传导到政治更替，在这一月格外清楚。更换领导人并没有立即带来全国和平，意大利即将面对占领、内战式冲突和长期前线。"],"perspectives":[{"country":"it","text":"战争失败促成政权危机，退出轴心国的道路仍有巨大风险。"},{"country":"su","text":"在阻击后扩大反攻，德军越来越难恢复东线战略主动。"}],"sources":[{"id":"ww2dates","locator":"1943-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"双方经过数月准备，东线决战与地中海登陆同时检验轴心国承受多线战争的能力。","after":"西西里战事延续，意大利新政府秘密寻求停战，苏军则持续扩大反攻。"},"relatedBattles":[]},{"id":"ww2-1943-08","date":"1943-08","title":"西西里战役结束，意大利秘密谈判","theaters":["欧洲","东线"],"countries":["it","de","uk","us","su"],"people":["巴多格里奥","艾森豪威尔"],"story":["盟军完成对西西里的主要占领，轴心国部分部队撤回意大利本土。守军撤离保存了继续防御的力量，因此占岛胜利并不意味着下一阶段登陆会轻易完成。","同盟国完成对西西里的占领，但德意部分部队撤往意大利本土，战争没有在海峡边结束。意大利政府一面与盟军秘密谈判，一面担心德国报复。军事转向、政治合法性与保全国土的愿望相互冲突，局面远比宣布退出战争复杂。","意大利政府与盟军秘密接触，德国则加强防备。苏军收复哈尔科夫并继续向西推进，两个方向共同挤压轴心国，联盟合作与各国自救也在同时改变政治关系。","东线苏军收复奥廖尔、别尔哥罗德和哈尔科夫等地，反攻使德军不得不继续后撤。工业生产、部队补充和作战经验积累，让苏军能够持续组织大规模行动；与此同时，解放区破坏严重，战争对社会的损伤并未随战线移动而消失。"],"perspectives":[{"country":"it","text":"试图退出战争，却必须面对德国军队和本国部队安全问题。"},{"country":"de","text":"准备在盟友倒向对手时直接接管关键地区。"}],"sources":[{"id":"ww2dates","locator":"1943-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"库尔斯克之后德军失去进一步推进机会，西西里登陆又动摇了意大利继续参战的政治基础。","after":"意大利停战公开后，德国将迅速占领关键地区，盟军登陆本土仍需付出重大代价。"},"relatedBattles":[]},{"id":"ww2-1943-09","date":"1943-09","title":"意大利停战，却没有停止战斗","theaters":["欧洲","东线"],"countries":["it","de","us","uk","su"],"people":["巴多格里奥","墨索里尼"],"story":["意大利与盟军停战安排公布，盟军在萨莱诺等地登陆。德国迅速解除大量意军武装并占领关键地区，获救的墨索里尼在北方建立依附德国的政权，意大利国土成为长期战场。","意大利停战消息公布后，德军迅速解除许多意军武装并控制大片地区，部分意大利军人和平民转入抵抗。盟军在萨莱诺登陆时遭遇德军强烈反击，建立滩头并不等于能够直接挺进罗马，半岛山地与狭窄道路有利于层层防守。","苏军向第聂伯河推进，需要在宽阔河流与德军防御前建立桥头堡。地图上连续后退的箭头，背后仍是极为困难的渡河、运输与近距离作战。","苏军向第聂伯河推进并争取渡河立足点，撤退德军破坏交通与设施，民众承受战火和强制迁移。渡河需要船只、工兵、火力与后续补给配合，不能只用冲锋场面概括。东线与意大利都在提醒读者：地图上前进的一条线，背后是复杂而昂贵的组织工作。"],"perspectives":[{"country":"it","text":"退出原有联盟并不等于军民脱离战争，许多士兵成为被俘或遭杀害者。"},{"country":"su","text":"追击成果需要通过工程、补给和步兵作战才能维持。"}],"sources":[{"id":"ww2dates","locator":"1943-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利试图脱离战争，苏军则把夏季反攻推进到更宽广的地域。","after":"意大利成为新的拉锯战场，同盟国接下来还要协调1944年的进攻与战后安排。"},"relatedBattles":[]},{"id":"ww2-1943-10","date":"1943-10","title":"意大利对德宣战，殖民地饥荒持续","theaters":["欧洲","后方"],"countries":["it","uk","de"],"people":["巴多格里奥"],"story":["意大利政府对德宣战，部分力量转而与盟军合作，北方抵抗运动也逐步发展。政权、军队与居民的选择分裂，不能再用一个国旗概括所有人的政治立场。","意大利王国政府对德宣战，与南部盟军合作，北部则出现德国控制下的墨索里尼政权。国家分裂、占领与抵抗相互交织，意大利人既继续承受外国军队作战，也卷入内部政治暴力。退出轴心国并没有自动终结战争。","孟加拉饥荒在战争环境下造成灾难，粮食供应、运输、价格与殖民治理的失误相互作用。对英国战争史的阅读，不能只停在伦敦防空与北非胜利，也应看到帝国臣民承受的严重苦难。","孟加拉饥荒造成巨大平民灾难，战争运输、殖民治理、市场失灵、粮食分配和救济不足等因素交织。研究对各因素权重仍有讨论，不能把灾难只归于自然歉收，也不应编造单一决定性原因。战争中的资源分配，会直接决定远离前线者的生死。"],"perspectives":[{"country":"it","text":"共同交战与被占领处境并存，国家重建的政治问题逐渐出现。"},{"country":"uk","text":"战争资源调配与殖民治理对平民生存负有责任，相关解释须结合多方面研究。"}],"sources":[{"id":"nz","locator":"1943-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"bengal","locator":"1943-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利停战带来新的占领与内部分裂，全球战争也不断挤压殖民地民众的生存条件。","after":"同盟国领导人将在开罗和德黑兰讨论胜利路径，亚洲战场与战后主权问题进入高层议程。"},"relatedBattles":[]},{"id":"ww2-1943-11","date":"1943-11","title":"开罗与德黑兰：盟国开始谈论战后","theaters":["外交","中国","东线"],"countries":["cn","us","uk","su","de","jp"],"people":["蒋介石","罗斯福","丘吉尔","斯大林"],"story":["中美英领导人在开罗会晤，讨论对日战争与战后安排，相关宣言于12月1日发表。随后美英苏在德黑兰商讨跨海进攻法国等问题，盟国对战场分工逐渐形成更明确安排。","开罗会议讨论对日战争及相关战后安排，蒋介石与罗斯福、丘吉尔会谈；德黑兰会议则由美英苏领导人协调欧洲战略。苏联要求跨海峡进攻，英美就1944年实施作出承诺，东线进攻与西线登陆开始形成更具体的配合。","苏军收复基辅，中国常德会战也在进行。外交桌上的方案仍依赖前线流血与运输资源才能兑现，各国参与程度与核心利益不同，多国合作并不意味着没有分歧。","中国常德地区激战，苏军收复基辅，会议之外各战场仍在付出代价。联盟协调不能代替各国自身的抵抗，却会影响武器流向、进攻时间与战后地位。中国战场的长期牵制和国际政治中的国家地位，在这里需要联系起来阅读。"],"perspectives":[{"country":"cn","text":"通过开罗会议参与亚洲战后安排，同时仍在本土承受日军攻势。"},{"country":"su","text":"要求西方开辟法国战线，并讨论东欧等战后安全问题。"}],"sources":[{"id":"cairo","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"tehran","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"各地区反攻取得进展，同盟国需要把分散行动变成1944年更协调的战略。","after":"开罗宣言将正式公布，已经承诺的战略安排也将接受下一年战场现实的检验。"},"relatedBattles":[]},{"id":"ww2-1943-12","date":"1943-12","title":"宣言发表，意大利山地仍难越过","theaters":["外交","欧洲","中国"],"countries":["cn","jp","us","uk","de"],"people":["蒋介石","罗斯福","丘吉尔"],"story":["开罗宣言发表，提出日本归还从中国窃取的领土等战后目标。宣言确立政治方向，但实现它仍取决于继续对日作战与后来受降、接收等安排。","《开罗宣言》公布，阐明对日战争目标和有关被日本夺取领土的安排。它是重要政治文件，与后来《波茨坦公告》及日本投降文件相衔接；具体文字、文件性质与后续实施应分开辨明，不能用一句口号代替全部外交和法律过程。","常德会战结束后中国继续作战，意大利前线则陷入冬季山地与河流防御。盟军虽然总体占优，仍要面对一次次局部僵持，战争结束的政治设想与前线实际距离尚远。","常德战事在激烈争夺后进入新的阶段，意大利前线则在山地、河流和冬季天气中进展缓慢。反攻年份的结束并没有带来各处同步胜利，同盟国仍需积累登陆艇、运输船、航空力量和训练部队，才能把会议决定落实到1944年的行动。"],"perspectives":[{"country":"cn","text":"战后主权诉求获得重要表达，抗战本身仍未结束。"},{"country":"uk","text":"同时筹备法国登陆和意大利推进，资源优先次序需要不断调整。"}],"sources":[{"id":"cairo","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"11月的领导人会议形成战略与政治安排，但主要战场仍在持续作战。","after":"1944年将出现更大规模的多线进攻，年初首先要突破列宁格勒与意大利的僵局。"},"relatedBattles":[]},{"id":"ww2-1944-01","date":"1944-01","title":"列宁格勒解围，安齐奥登陆","theaters":["东线","欧洲"],"countries":["su","de","uk","us"],"people":["朱可夫","艾森豪威尔"],"story":["苏军攻势彻底解除列宁格勒长期围困，城市与居民遭受的损失却无法简单用一场胜利弥补。幸存者面临医疗、营养与重建，胜利之后的人道任务立即开始。","苏军发动大规模攻势，迫使德军撤离列宁格勒周边，长期围困终于被解除。胜利不只是战线向前移动，也是幸存者重新获得较安全生活条件的开始；饥饿、失亲与城市破坏留下的创伤，却远远超出军事解围的日期。","盟军在安齐奥登陆，希望从侧后突破意大利防线，却很快受到德军围堵。越过第一道海岸并不等于切断敌军退路，登陆成功与战役突破仍是两个不同阶段。","盟军在安齐奥登陆，企图绕过意大利中部防线、威胁德军后方。登陆初期的机会没有迅速转化为纵深突破，德军集结反击，滩头陷入长期苦战。两栖行动能越过正面工事，却不能免除指挥判断、兵力和补给对结果的制约。"],"perspectives":[{"country":"su","text":"围城结束具有重大象征与实际意义，城市创伤延续更久。"},{"country":"us","text":"必须把滩头补给和指挥判断转化为纵深行动，不能只计算登陆兵力。"}],"sources":[{"id":"nz","locator":"1944-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1944-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"同盟国计划扩大进攻，先要在长期僵持的城市和防线打开通路。","after":"意大利正面突破仍然困难，太平洋则通过逐岛推进逐渐逼近日本防御纵深。"},"relatedBattles":[]},{"id":"ww2-1944-02","date":"1944-02","title":"卡西诺修道院被炸，残垣仍成战场","theaters":["欧洲","太平洋"],"countries":["uk","us","de","jp"],"people":["弗赖伯格","尼米兹"],"story":["盟军轰炸卡西诺修道院，试图解除对防线的威胁，却造成文化遗产毁坏和人员伤亡。废墟随后仍便于防御，军事判断与预期后果之间出现令人警醒的反差。","卡西诺一带山地扼守通向罗马的道路，河流、观察高地与坚固阵地使盟军多次攻击受挫。修道院遭轰炸后成为战争破坏文化遗产的典型事件，废墟又提供了防御位置。军事必要性的判断、情报和人道代价，在此构成沉重问题。","太平洋美军在马绍尔群岛推进并袭击特鲁克基地，逐步削弱日本外围体系。选择绕过哪些据点、夺取哪些机场，需要结合运输和后续行动，而不是一岛不漏地正面攻占。","美军攻占马绍尔群岛重要据点，并空袭特鲁克基地，继续采用绕过部分强固据点、切断其联系的推进方式。所谓跳岛并非没有代价，而是把有限登陆能力集中到更有战略价值的位置，让孤立日军难以影响下一步行动。"],"perspectives":[{"country":"uk","text":"多国部队参与意大利作战，受限地形使火力优势难以直接转为突破。"},{"country":"jp","text":"基地遭袭与海上交通损失，削弱整个防御圈的相互支援。"}],"sources":[{"id":"nz","locator":"1944-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利地形限制快速推进，太平洋的海空优势则让盟军能够选择部分进攻方向。","after":"日本将在缅印边境主动进攻，欧洲占领区的迫害也因德国扩大控制而更加严酷。"},"relatedBattles":[]},{"id":"ww2-1944-03","date":"1944-03","title":"日军进攻印度方向，补给成为赌注","theaters":["亚洲","欧洲"],"countries":["jp","uk","cn","de"],"people":["牟田口廉也","威廉·斯利姆"],"story":["日军从缅甸向英帕尔、科希马方向进攻，希望打乱盟军基地和交通。越过山地后，日军必须依靠极困难的运输维持作战，夺取敌方物资的期待难以替代可靠补给。","日军向英帕尔和科希马进攻，企图进入印度并切断盟军在缅甸方向的行动。山地道路、雨季和长距离运输使日军补给计划极不可靠，英印军则利用空运维持被围部队。双方意志都重要，但能够把食物和弹药送到阵地的方式决定了持续作战的可能。","卡西诺继续激战，德国又占领匈牙利，进一步扩大对当地犹太人的迫害与驱逐。军事战线的变化与种族灭绝的推进同时发生，不能把欧洲战争只读成盟军逐步前进的地图。","德军占领匈牙利，削弱其政府试图摆脱德国控制的空间，并推动对匈牙利犹太人的大规模驱逐。即使德国战局恶化，灭绝政策仍继续动员铁路、官僚和警察资源。军事失败将近，并不意味着受迫害者的危险已经减少。"],"perspectives":[{"country":"jp","text":"冒险进攻依赖薄弱后勤，把兵员暴露于饥饿和疾病。"},{"country":"uk","text":"利用空运、坚守与增援消耗对手，缅印战局逐步改变。"}],"sources":[{"id":"nz","locator":"1944-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1944-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"同盟国逐步逼近轴心国核心地区，德国和日本仍试图用新的行动改变不利态势。","after":"缅印攻势的补给问题日趋严重，日本同时又在中国发动规模巨大的“一号作战”。"},"relatedBattles":["imphal-kohima"]},{"id":"ww2-1944-04","date":"1944-04","title":"一号作战：世界转折没有让中国战场轻松","theaters":["中国","亚洲"],"countries":["cn","jp","uk"],"people":["蒋介石","威廉·斯利姆"],"story":["日本在中国发动一号作战，企图打通大陆交通并摧毁相关航空基地，攻势从河南扩向湖南、广西。中国军队在多处遭受严重失败，大片地区及民众面临占领和迁徙。","日军在中国发动“一号作战”，试图打通大陆交通线并摧毁美军在华航空基地，首先向河南等地推进。国民党正面战场在指挥、训练、补给和社会动员等方面积累的问题集中暴露，中国军民又承受大规模国土失陷和流离失所。","与此同时，英帕尔、科希马地区盟军仍与日军激战。日本在不同战区继续投入攻势，说明总体战略劣势并未使其立即丧失进攻能力，中国承受的战争压力也没有因欧洲盟军准备登陆而消失。","缅印战场日军继续围攻英帕尔和科希马，补给不足逐步转成饥饿和疾病。两场攻势看似都在扩大日本控制，实际也持续消耗其已经紧张的人力与运输资源。判断战争态势不能只看某个月推进了多少公里，还要看能否维持占领与后续作战。"],"perspectives":[{"country":"cn","text":"需要面对军队组织、补给与治理问题造成的危机，也仍保持长期抵抗。"},{"country":"jp","text":"用大规模陆上进攻争取交通和基地，代价是更长战线与更深消耗。"}],"sources":[{"id":"china","locator":"1944-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本希望以中国和缅印的攻势破坏盟军基地、运输和反攻准备。","after":"中国将承受继续失地的压力，缅印及滇西的盟军反攻则逐步改变另一条战线。"},"relatedBattles":[]},{"id":"ww2-1944-05","date":"1944-05","title":"卡西诺突破与滇西反攻","theaters":["欧洲","中国","亚洲"],"countries":["uk","us","de","cn","jp"],"people":["亚历山大","史迪威"],"story":["盟军在卡西诺及意大利防线上取得突破，安齐奥部队也向外推进。长期准备、多国部队协同和对地形的适应，终于使此前停滞的战线开始移动。","盟军在意大利扩大攻势，突破卡西诺地区防线，并与安齐奥部队联系。来自多个国家和地区的部队共同作战，突破依赖长期消耗、侧翼机动和相互配合。此前看似停滞的战线，需要一次次补充和调整才可能转动。","中国军队在滇西等地反攻，试图恢复对外交通，与驻印部队在缅北的作战相互联系。打通一条道路意味着夺取高地、渡过河流并重建运输设施，其代价不能用一个“会师”词语概括。","中国军队在滇西反攻，向怒江以西日军据点推进，与缅北盟军作战相呼应，目标包括重建通往中国的陆路联系。山地坚固据点、雨季和运输困难使作战异常艰苦，打通补给线所需的时间，远长于地图上画出一条道路的瞬间。"],"perspectives":[{"country":"cn","text":"在本土承受日军攻势的同时，仍需为外援通道投入力量。"},{"country":"uk","text":"意大利突破改善局势，法国登陆准备仍占据更高战略优先级。"}],"sources":[{"id":"nz","locator":"1944-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1944-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"意大利和缅印战场经历长期准备，反攻力量开始逐步汇聚。","after":"6月诺曼底与白俄罗斯的大攻势，将使德国面临更沉重的东西两线压力。"},"relatedBattles":[]},{"id":"ww2-1944-06","date":"1944-06","title":"诺曼底与巴格拉季昂：两面压力终于汇合","theaters":["西线","东线","太平洋"],"countries":["us","uk","fr","su","de","jp"],"people":["艾森豪威尔","蒙哥马利","朱可夫","罗科索夫斯基"],"story":["6月6日，盟军在诺曼底登陆。此前数月的集结、训练、气象研判与欺骗计划，都围绕同一个难题：怎样把足够力量送过英吉利海峡，并在德国增援到来前站稳。空降兵先争夺道路和桥梁，海上部队随后冲向滩头。","各海滩并非经历相同，奥马哈尤其伤亡沉重。火力掩护、工兵清障、基层指挥和后续增援逐渐打开通路，登陆场才得以扩大。进攻者必须把车辆、燃料、炮弹与伤员运输接续起来，否则第一天站住的部队仍可能陷入孤立。","人工港帮助卸载，风暴又损坏设施；瑟堡港口遭破坏，修复也需要时间。卡昂、树篱地带与道路节点的争夺将延续数周。登陆不是胜利影片中的最后一幕，而是一个庞大运输与地面作战体系刚开始在法国运转。","22日苏军发动“巴格拉季昂”行动，在白俄罗斯重创德国中央集团军群。德军同时应对东线大突破和西线登陆，更难集中预备队。德黑兰等会议中的协调承诺，如今变成来自不同方向的实际军事压力。","太平洋美军进攻塞班，菲律宾海海战重创日本海军航空兵。不同战区各有自身准备和原因，却共同使轴心国越来越缺乏恢复力量的时间。理解6月的意义，需要将这三幅战场图放在一起，也记住每一处仍有大量军民死伤。"],"perspectives":[{"country":"su","text":"以大规模陆上进攻牵制并摧毁德军，不是等待西线代替自己完成战争。"},{"country":"us","text":"同时承担欧洲登陆和太平洋推进，工业与海运能力成为协同基础。"}],"sources":[{"id":"ww2dates","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"dday-deception","locator":"1944-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"},{"id":"dday-supply","locator":"1944-06相关战区过程与战略背景；仅支持对应主题，不覆盖本月全部战场。"}],"continuity":{"before":"同盟国此前承诺的协调进攻进入实施阶段，工业、训练和运输积累集中转化为行动。","after":"滩头还不是通向德国的坦途，诺曼底需突破树篱地带，苏军也将继续向西推进。"},"relatedBattles":["battle-normandy"]},{"id":"ww2-1944-07","date":"1944-07","title":"突破法国防线，德国政变失败","theaters":["西线","东线","后方"],"countries":["us","uk","fr","de","su","jp"],"people":["艾森豪威尔","希特勒","施陶芬贝格"],"story":["盟军在诺曼底持续作战后，通过眼镜蛇行动等突破进入法国纵深；苏军也向波兰方向推进。德国同时在多处后撤，前线失利加剧统治内部危机。","美军“眼镜蛇”行动打开诺曼底突破口，盟军由滩头拉锯转向更大范围机动。此前数周战斗消耗德军，空地火力与地面推进终于形成突破条件。德国军官对希特勒的刺杀和政变尝试失败，纳粹随后展开严酷镇压，独裁统治并未因内部反抗自动瓦解。","20日，施陶芬贝格等人的刺杀希特勒与政变失败，纳粹随后严厉清洗。日本塞班失守，东条内阁倒台，军事挫折在不同轴心国都传入政治核心，却未立即结束这些政权继续战争的决定。","美军夺取塞班，使日本本土更直接地处于远程轰炸威胁下，东条内阁辞职。岛上军民遭受惨重伤亡，大批平民死亡也与日军控制、战争恐惧和宣传有关。失去岛屿是军事危机，也是普通人生活世界的毁灭。"],"perspectives":[{"country":"de","text":"部分精英反抗并未成功，纳粹镇压使继续战争的体制仍维持。"},{"country":"jp","text":"丧失重要防御位置后更换内阁，却仍未接受投降。"}],"sources":[{"id":"ww2dates","locator":"1944-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"诺曼底登陆和苏军夏季攻势逐步发展，日本的外层防御也被连续突破。","after":"盟军将解放巴黎，华沙的起义与塞班的陷落则提醒人们，前线接近未必意味着平民立即获救。"},"relatedBattles":[]},{"id":"ww2-1944-08","date":"1944-08","title":"巴黎解放，华沙却在孤立中燃烧","theaters":["西线","东线"],"countries":["fr","pl","de","su","us","uk"],"people":["戴高乐","艾森豪威尔"],"story":["巴黎起义后，自由法国和盟军进入城市，首都解放成为恢复法国政治地位的重要时刻。法国抵抗、盟军推进与国家重建相互联系，胜利既是军事成果，也是政治合法性的重塑。","巴黎在抵抗组织起义和盟军推进中获得解放，法国恢复政治权威的问题随即浮现。东欧的罗马尼亚转向对德作战，苏军继续推进，德国南翼形势恶化。城市解放与盟国转换共同加快纳粹控制体系瓦解。","华沙国内军起义却未获足够外援，德军残酷镇压，苏军停在维斯瓦河另一侧的局面引发长期争议。罗马尼亚又发生政变并退出原轴心立场，同一月的解放、失败与转向呈现战争末期不同命运。","华沙起义者希望在德军撤退前夺回首都，既抵抗占领，也争取战后政治地位。苏军停在维斯瓦河附近，军事消耗、补给条件与政治意图如何影响其行动，研究中存在争论；可以确定的是起义未获足够援助，德军镇压给城市与居民造成灾难。"],"perspectives":[{"country":"fr","text":"争取以本国力量参与解放，有助恢复战后独立政治地位。"},{"country":"pl","text":"对自主解放和国家前途的追求，陷入德军镇压与盟国战略政治关系的夹缝。"}],"sources":[{"id":"ww2dates","locator":"1944-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国防线在多处后撤，各国抵抗者开始争取解放与战后自主的机会。","after":"西线补给困难逐渐限制追击，华沙仍在孤立作战，胜利的地理差异愈发明显。"},"relatedBattles":[]},{"id":"ww2-1944-09","date":"1944-09","title":"市场花园受挫，胜利仍受交通约束","theaters":["西线","东线"],"countries":["uk","us","de","su"],"people":["蒙哥马利"],"story":["盟军发动市场花园行动，试图通过空降夺桥并以地面部队快速推进。阿纳姆等地受阻，使跨越莱茵河的目标未能实现，远距离补给与狭窄交通轴线放大了风险。","“市场花园”行动试图以空降兵夺桥、地面装甲纵队快速接应，绕过德军防线进入德国。阿纳姆方向未能按计划打通，通信、距离、道路和德军抵抗等问题叠加，部分空降部队被迫撤出。大胆计划必须依赖所有环节同时衔接，任何延误都会层层放大。","芬兰与苏联停战，欧洲联盟结构继续变化。西方盟军推进接近德国边境后，也必须处理港口、铁路和燃料供应，战线越接近敌方本土，并不意味着后勤问题会自动减少。","芬兰与苏联停战，并需驱逐境内德军，随后在拉普兰与昔日合作的德国交战。小国脱离战争往往仍要付出领土、赔偿和新的战斗代价。轴心体系正在解体，但各国的退出路径并不相同，也没有整齐划一的和平时刻。"],"perspectives":[{"country":"uk","text":"冒险跨越障碍失败，说明资源优势仍需可靠计划与情报支持。"},{"country":"de","text":"局部防御仍可取得成果，但难以改变总体两线压力。"}],"sources":[{"id":"ww2dates","locator":"1944-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"盟军夏季快速推进后，港口、补给和桥梁成为继续进攻的关键限制。","after":"西线仍需打开安特卫普通航，太平洋则将围绕菲律宾展开更大规模海陆作战。"},"relatedBattles":[]},{"id":"ww2-1944-10","date":"1944-10","title":"莱特湾与华沙起义的结局","theaters":["太平洋","东线"],"countries":["us","jp","pl","de"],"people":["麦克阿瑟","尼米兹"],"story":["美军登陆莱特，莱特湾海战使日本联合舰队遭受重大损失，难以再以原有方式组织大规模舰队决战。日本逐渐扩大特攻等手段，战争把人的生命更直接当作一次性武器。","麦克阿瑟率部登陆莱特岛，日本海军试图以复杂的分进合击破坏登陆，莱特湾周边爆发多场海战。舰队行动、航母诱敌与登陆支援相互牵动，日军遭受重大损失，海军持续实施大规模作战的能力进一步衰退，特攻作战开始扩大使用。","华沙起义投降，城市和居民遭到进一步破坏。法国解放的喜悦无法代表所有被占领社会，战争末期仍有大量人在接近胜利时失去家园和生命。","华沙起义在持续两个月后失败，幸存居民被驱逐，城市遭到系统性破坏。它与巴黎解放形成令人沉痛的对照：同样抵抗占领，不同军事地理与政治处境带来不同结局。记录胜利时，不能让未能获救者从战争叙述中消失。"],"perspectives":[{"country":"us","text":"重返菲律宾具有战略与政治意义，后续地面战争仍将造成深重损失。"},{"country":"jp","text":"海军力量衰退后转向更绝望的手段，不能将其浪漫化为纯粹勇武。"}],"sources":[{"id":"ww2dates","locator":"1944-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"盟军逐渐切断日本海上联系，欧洲抵抗运动却并非都能与外部援军及时会合。","after":"运输与工业将更深地影响最后阶段战争，安特卫普港和远程轰炸都在11月显现作用。"},"relatedBattles":[]},{"id":"ww2-1944-11","date":"1944-11","title":"斯海尔德航道打开，东京进入轰炸范围","theaters":["西线","太平洋"],"countries":["uk","us","de","jp","cn"],"people":["艾森豪威尔"],"story":["盟军清理斯海尔德河口后，安特卫普港得以更有效投入补给，支持西线持续作战。夺取港口城市与真正使用港口不是一回事，航道、障碍和运输体系必须一并解决。","盟军清除斯海尔德河口德军后，安特卫普港终于能够接收补给。占领港口与真正使用港口之间隔着航道、岸防和运输组织，这一差别解释了盟军秋季推进为何放缓。稳定供应为之后继续向德国本土作战提供重要条件。","美军从马里亚纳群岛出动B-29攻击日本本土，远程空战进一步扩大。中国一号作战仍在向南推进，世界范围的盟国优势与某些地方居民继续遭受占领的现实并存。","从马里亚纳群岛起飞的B-29开始轰炸东京，战略空战逐渐逼近日本城市社会；在中国，“一号作战”仍造成严重损失。日本在大陆取得局部进展，却无法消除海运、航空和工业上的总体劣势，前线占地与国家战争能力进一步出现背离。"],"perspectives":[{"country":"us","text":"基地与运输工程使远程轰炸成为持续行动，而非孤立突袭。"},{"country":"cn","text":"日军继续推进造成失土与迁徙，战争胜负趋势不能掩盖中国的即时苦难。"}],"sources":[{"id":"nz","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"夏秋攻势后，盟军需要把新占领地区转化为可靠基地与运输体系。","after":"德国将在阿登发动最后一次大型西线反攻，试图打乱盟军继续进攻的安排。"},"relatedBattles":[]},{"id":"ww2-1944-12","date":"1944-12","title":"阿登反攻：最后的豪赌","theaters":["西线","东线"],"countries":["de","us","uk","su"],"people":["希特勒","艾森豪威尔","巴顿"],"story":["16日，德军在阿登发动反攻，试图分割盟军并改变西线局面。初期突然性造成危机，巴斯托涅等地坚守与盟军调动逐渐遏制进攻，天气改善后盟军航空兵作用增强。","德军利用恶劣天气在阿登发动突袭，企图突破后向安特卫普推进，分割盟军。盟军初期遭受冲击，巴斯托涅等交通节点成为争夺焦点。德军燃料短缺和道路拥堵逐渐暴露，天气转好后盟军航空兵恢复行动，攻势未能达到战略目标。","德国难以补充燃油和损失，最后的大规模西线攻势最终消耗了更多防御资源。苏军围攻布达佩斯，欧洲战争继续逼近轴心国核心，年末的反击延长苦难，却未能改变资源与力量的总体对比。","苏军包围布达佩斯，德军与匈牙利守军继续顽抗，城市平民陷入围城灾难。纳粹明知总体局势不利仍拒绝结束战争，把更多资源与生命投入延长抵抗。战争最后阶段的破坏并非胜负已定便自然减少，反而常因绝望和强制统治更加残酷。"],"perspectives":[{"country":"de","text":"政治愿望驱动高风险攻势，把有限预备队再次投入难以持续的作战。"},{"country":"us","text":"危机考验机动、补给和指挥协调，最终依靠整体资源恢复主动。"}],"sources":[{"id":"ww2dates","locator":"1944-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"盟军已逼近德国及其盟国核心地区，希特勒仍试图用一次冒险夺回主动。","after":"阿登失败耗尽更多德国预备力量，苏军1945年初的大攻势将进一步压缩其战争空间。"},"relatedBattles":[]},{"id":"ww2-1945-01","date":"1945-01","title":"维斯瓦—奥得攻势与奥斯维辛解放","theaters":["东线","平民"],"countries":["su","de","pl","us","uk"],"people":["朱可夫","科涅夫"],"story":["苏军从维斯瓦河方向大举推进，迅速逼近德国核心地区。纳粹在撤退中驱赶集中营囚犯进行死亡行军，许多人在严寒、饥饿和杀戮中死亡，解放到来前的最后阶段仍极其致命。","苏军从维斯瓦河一带发起攻势，快速推进至奥得河方向，德国东部居民大规模逃难。军事崩溃、报复恐惧和冬季迁徙交织，纳粹此前发动侵略造成的灾难又以新的形式波及更广人群，但解释这些苦难不能颠倒侵略责任。","27日，苏军进入奥斯维辛，发现幸存者与大规模犯罪遗迹。战争结束不能让死者复生，保存档案、证言和物证成为随后追究责任与抵抗否认的重要基础。","苏军进入奥斯维辛集中营及灭绝营设施，发现幸存者与大规模犯罪证据。此前纳粹已强迫许多囚犯向西转移，死亡行军继续夺走生命。解放营地不只是一个军事日期，幸存者此后仍需面对疾病、失亲和重建生活的漫长过程。"],"perspectives":[{"country":"su","text":"军事推进与接触大屠杀遗址同时发生，救护和记录成为新任务。"},{"country":"pl","text":"国土上的灭绝营与长期占领留下深重创伤，国家前途仍受战后政治影响。"}],"sources":[{"id":"holocaust","locator":"1945-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1945-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"阿登攻势失败后德国更难组织有效预备队，东线防御也在苏军攻势下瓦解。","after":"胜利临近，同盟国将讨论德国处置与战后安排，而城市与岛屿上的战斗仍未结束。"},"relatedBattles":[]},{"id":"ww2-1945-02","date":"1945-02","title":"雅尔塔、硫黄岛与德累斯顿","theaters":["外交","太平洋","平民"],"countries":["us","uk","su","de","jp"],"people":["罗斯福","丘吉尔","斯大林"],"story":["美英苏领导人在雅尔塔讨论德国占领、联合国和欧洲战后安排，并商谈苏联对日参战。合作仍围绕击败共同敌人，波兰等地政治问题却已显示潜在冲突，亚洲相关秘密安排也影响其他国家利益。","雅尔塔会议讨论德国占领、波兰及欧洲战后安排、联合国组织和苏联对日参战等问题。共同敌人仍在，但各国已经为战后安全和影响力布局。会议文件与后来执行之间存在差距，不能把整个冷战简单归结为一场会议预先写定。","美军登陆硫黄岛，德累斯顿遭盟军猛烈空袭。会议桌上的秩序规划与前线、城市中的死亡同时存在，讨论战略必要性不能省略平民伤亡与决策争议。","美军登陆硫黄岛，遭遇日军纵深工事与坑道抵抗，代价高昂；欧洲德累斯顿遭到英美轰炸，引发持续的人道与军事必要性争论。越接近战争终点，普通人和前线士兵仍可能面对最惨烈的时刻，最后胜利不能使这些代价失去讨论空间。"],"perspectives":[{"country":"su","text":"寻求战后安全和影响范围，相关要求与其他国家主权诉求存在冲突。"},{"country":"us","text":"准备结束欧洲战争并对日作战，同时面对不同武力手段的伦理问题。"}],"sources":[{"id":"yalta","locator":"1945-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国败局越来越清楚，同盟合作的重点逐渐同时面向终战与战后。","after":"盟军将跨越莱茵河，日本城市则遭受更大规模燃烧弹攻击，战争末期的暴力持续升级。"},"relatedBattles":[]},{"id":"ww2-1945-03","date":"1945-03","title":"越过莱茵河，东京遭大规模燃烧弹轰炸","theaters":["西线","太平洋"],"countries":["us","uk","de","jp"],"people":["艾森豪威尔","李梅"],"story":["盟军在雷马根等处跨越莱茵河，德国西部防御进一步瓦解。渡河之后仍需占领地区、接收俘虏并维持补给，推进速度与组织能力密切相关。","盟军取得莱茵河桥头堡并扩大渡河，德国西部防御体系加速崩溃。桥梁、渡河器材、空中支援和持续运输把此前受阻的推进变成大规模深入，德国已难以同时封堵东西两线。不同部队的进攻节奏仍需协调，战争结束并非没有最后的组织问题。","东京在大规模燃烧弹空袭中遭到严重毁坏，大量平民死亡。对日本工业和战争能力的打击，与密集木结构居民区承受的灾难同时发生，空袭史不能只按投弹吨数和摧毁面积书写。","美军对东京实施大规模低空燃烧弹轰炸，密集木结构城区遭到毁灭性破坏，大量平民死亡。工业与居民空间交错被用作轰炸论证的一部分，但并不能消除对平民灾难和作战方式的伦理追问。这一过程也构成理解8月日本投降处境的重要背景。"],"perspectives":[{"country":"us","text":"空中力量取得压倒性优势，也承担攻击人口密集城市的决策责任。"},{"country":"jp","text":"普通居民面对火灾与失所，政府仍未停止战争。"}],"sources":[{"id":"ww2dates","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国与日本的防御圈持续收缩，同盟国的技术和运输优势更直接地作用于对手本土。","after":"4月柏林与冲绳将成为焦点，战争如何结束的问题已与战后制度建设同时展开。"},"relatedBattles":[]},{"id":"ww2-1945-04","date":"1945-04","title":"柏林陷落前，领导人更替与联合国筹建","theaters":["东线","西线","外交","亚洲"],"countries":["su","de","us","uk","cn","jp"],"people":["朱可夫","罗斯福","杜鲁门","希特勒"],"story":["苏军发动柏林攻势，德军在城市周围与内部继续抵抗，30日希特勒自杀。美苏部队在易北河会合，德国被军事分割，纳粹统治的终结已经临近。","苏军攻入柏林，街巷战将军人、平民、强征人员和城市设施一同卷入毁灭。希特勒在月底自杀，仍未结束所有战场的抵抗；领导层意图、军队投降与实际停火之间存在时间差。中国战场也继续作战，不能把欧洲的终局当成世界战争已经结束。","罗斯福去世，杜鲁门接任美国总统；旧金山会议开幕，筹建联合国。亚洲冲绳登陆与中国湘西等地战斗仍在继续，欧洲胜利在望并不意味着世界各地已能停止付出生命。","罗斯福去世，杜鲁门接任美国总统；旧金山会议开始筹建联合国。冲绳战役同时造成军民惨重伤亡，岛上居民被夹在军事防御、强制措施和进攻火力之间。一边设计避免下一场战争的制度，一边仍在承受当前战争的极端暴力，是这个月的深刻张力。"],"perspectives":[{"country":"us","text":"新总统接手核计划、对日战争和战后外交等重大决策。"},{"country":"cn","text":"参与新国际组织筹建，同时仍需在本土和亚洲战场继续抵抗日本。"}],"sources":[{"id":"ww2dates","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"un","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"盟军已突破德国边境，日本也面临冲绳方向威胁，同盟国领导层与战后安排同时发生变化。","after":"德国将于5月投降，但亚洲战争仍继续，同盟国还要面对怎样迫使日本结束战争。"},"relatedBattles":[]},{"id":"ww2-1945-05","date":"1945-05","title":"德国投降，战争尚未在亚洲结束","theaters":["欧洲","亚洲"],"countries":["de","su","uk","us","cn","jp"],"people":["邓尼茨","艾森豪威尔"],"story":["德国在兰斯与柏林先后签署投降文件，欧洲中部时间8日深夜生效，莫斯科已经进入9日，因此不同国家纪念日有差异。柏林守军此前已投降，欧洲战争主要阶段结束。","德国投降文件先在兰斯签署，随后在柏林再次签署，生效时间与时区差异使欧洲5月8日、苏联等地5月9日分别成为纪念日。部分地区仍有残余战斗和混乱，战俘、流离失所者与幸存者需要救济，胜利之后立即出现庞大的重建任务。","盟军面对幸存者、流亡人口、战俘和被毁城市，解放与救援立即转为重建任务。缅甸仰光被收复，亚洲战事仍在进行，欧洲的庆祝必须与尚未结束的对日战争并列阅读。","缅甸仰光被盟军收复，亚洲运输与作战形势继续改变。欧洲结束战争释放了部分资源，却不能马上消除太平洋和中国战场的抵抗与伤亡。各国公众对回家、复员和尽快结束战争的期待，也将影响后续决策环境。"],"perspectives":[{"country":"de","text":"纳粹统治结束后，去纳粹化、责任追究与社会重建成为艰难任务。"},{"country":"cn","text":"对德胜利改善总体局势，但中国军民仍未等到抗战结束。"}],"sources":[{"id":"ww2dates","locator":"1945-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"柏林陷落与纳粹领导层崩溃使德国全面投降成为现实，亚洲攻势仍在继续。","after":"冲绳战役尚未结束，新国际组织的宪章则将在6月签署。"},"relatedBattles":[]},{"id":"ww2-1945-06","date":"1945-06","title":"冲绳战役结束，联合国宪章签署","theaters":["太平洋","外交"],"countries":["us","jp","cn","uk","su"],"people":["杜鲁门"],"story":["冲绳主要战斗结束，美军、日军与当地平民都付出巨大代价，居民遭战争和日军控制逼入绝境的经历必须保留。盟军继续讨论如何迫使日本投降，登陆本土的成本只是其中一个考虑。","冲绳大规模有组织战斗接近结束，军民遭受极其沉重损失，零星抵抗仍然持续。美军获得接近日本本土的重要基地，也从战役中估计进一步登陆可能面临的代价。不能把这种估计当作此后任何手段都无须讨论的充分理由，战争决策仍需分辨事实、预期与伦理判断。","26日，联合国宪章在旧金山签署，集体安全、人权与国际合作被写入新的制度框架。制度由战争灾难催生，却仍需国家行为支持，不能把签字等同于今后自然不会再发生战争。","《联合国宪章》在旧金山签署，提出集体安全和国际合作框架。它在10月生效，6月签字并不是组织已完成全部运行程序。大国合作、安理会安排与主权原则带着战争经验，也带着各国利益的妥协，和平制度从来不是凭一纸文件自动实现。"],"perspectives":[{"country":"jp","text":"本土附近战败与平民灾难未能立即改变政府决策。"},{"country":"cn","text":"作为创始参与国之一进入新国际制度，也期待主权与战后恢复。"}],"sources":[{"id":"nz","locator":"1945-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"un","locator":"1945-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"欧洲胜利后，对日战争与战后制度建设成为同盟国同时面对的任务。","after":"7月波茨坦会议将进一步讨论德国处置，并向日本提出投降要求。"},"relatedBattles":[]},{"id":"ww2-1945-07","date":"1945-07","title":"波茨坦与核试验：结束战争的选择","theaters":["外交","后方"],"countries":["us","uk","su","cn","jp"],"people":["杜鲁门","斯大林","丘吉尔","艾德礼"],"story":["16日，美国进行首次核爆炸试验；随后波茨坦会议讨论德国与战后安排，英国大选又使艾德礼接替丘吉尔参加会议。共同敌人消失后，盟国在欧洲利益上的分歧更加明显。","美英苏在波茨坦讨论德国占领与战后安排，美英中发布《波茨坦公告》敦促日本投降。文件提出消除军国主义势力、解除武装等要求，苏联当时尚未对日宣战，没有列名最初发布者。公告与日本政府内部决策，需联系前线、外交和皇室地位问题理解。","26日，中美英发表波茨坦公告，要求日本投降，苏联当时尚未对日宣战，没有作为最初署名国。日本领导层继续寻求不愿放弃的条件，原子弹、苏联行动与军事封锁正共同逼近最终抉择。","美国在新墨西哥完成首次核试验，原子弹从研究和工业工程变成可以实际使用的武器。与此同时，对日本城市的常规轰炸、海上封锁与准备入侵仍在进行。决策者面前并不是一个孤立按钮，而是一组已经造成重大灾难、仍可能继续升级的政策选择。"],"perspectives":[{"country":"us","text":"拥有新武器并不消除使用它的伦理与外交责任。"},{"country":"jp","text":"仍试图保留条件、寻求调停，低估继续拖延给军民带来的风险。"}],"sources":[{"id":"potsdam","locator":"1945-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"atomic","locator":"1945-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"德国败后同盟国着手安排欧洲秩序，日本领导层仍未接受终战条件。","after":"8月的原子弹攻击、苏联参战及日本内部决策将迅速改变局势，具体作用不能简化为单一原因。"},"relatedBattles":[]},{"id":"ww2-1945-08","date":"1945-08","title":"广岛、苏联参战、长崎与日本接受投降","theaters":["太平洋","中国","外交","平民"],"countries":["us","jp","su","cn","uk"],"people":["杜鲁门","裕仁","斯大林"],"story":["6日美国在广岛投下原子弹；8日苏联对日宣战，9日起在中国东北等地进攻；9日美国又在长崎投下原子弹。几项重大冲击在数日内集中发生，日本希望借苏联调停的设想破灭，关东军也迅速陷入崩溃。","广岛、长崎的灾难不仅包括爆炸当时的死亡与城市破坏。烧伤、医疗体系被毁和辐射相关伤害继续影响幸存者，家人与生活网络同时瓦解。讨论武器与战争结局时，不能把这些人的长期经历压缩成一种抽象的战略效果。","日本最高决策层围绕是否接受投降条件、怎样理解皇室地位等问题发生争执，天皇介入促成接受《波茨坦公告》的决定。15日广播向民众宣布接受，军方内部仍有反对，命令传达到各地和落实停止作战又需要时间。","中国长期抗战、太平洋反攻、海上封锁、常规轰炸、苏联参战与核武器攻击共同构成终战背景。关于不同因素在日本决策中各占多大作用，研究存在争论；不能先设一个唯一原因，再把不符合的证据排除。","接受投降并不等于各地已完成缴械。中国等战区还需组织受降、救援、接收与恢复秩序，被俘人员和劳工也等待返乡。8月是政治决策与公开宣布的转折，正式签署和各地实施将在9月及以后继续。"],"perspectives":[{"country":"jp","text":"政府终于接受失败，居民既是战争动员对象，也承受国家坚持侵略的后果。"},{"country":"cn","text":"长期抵抗走向胜利，收复失地、处理战争遗产与重建仍将极其艰难。"}],"sources":[{"id":"surrender","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"potsdam","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"command","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本军事与经济处境恶化，波茨坦公告要求结束战争，苏联也准备履行对日参战承诺。","after":"接受投降之后，正式签署、各战区受降及战俘救济仍需在9月及以后落实。"},"relatedBattles":[]},{"id":"ww2-1945-09","date":"1945-09","title":"东京湾签字：中国受降与漫长的战后","theaters":["外交","中国","后方"],"countries":["jp","us","cn","uk","su","fr"],"people":["麦克阿瑟","徐永昌","何应钦","重光葵"],"story":["2日，日本代表在东京湾“密苏里”号签署投降书，同盟国代表接受，中国代表徐永昌在场签字。9日南京举行中国战区受降仪式。全球战争在通常采用的分期中结束，各战区的正式手续却有不同日期，不能混成一个时刻。","签字需要转化成实际行动：日军接到命令、放下武器，盟军和当地机构接收地区、照料被俘人员，运输系统安排遣返。许多地方基础设施已被破坏，居民流离失所，终战后的头几周仍可能充满饥饿、混乱与不安。","战俘与劳工返乡、失踪人员追寻、战争罪行调查和幸存者救济随后展开。罪行证据需要保存、核对和审判，不能因战争结束就失去追究责任的基础。重建不只是修好道路与工厂，也包括帮助人们重新获得安全与权利。","胜利还打开新的政治难题。殖民地人民要求独立，同盟国利益分歧重新显现，中国的和平与重建也面临严峻挑战。战时合作建立的制度能否约束新的冲突，需要此后不断实践，而不是由一纸投降书保证。","两次世界大战的故事最终回到人和制度：宣传如何压过事实，国家如何组织暴力，普通人怎样抵抗和救助，国际合作又为何失效或被重建。胜利需要纪念，战争发生的条件、责任与维持和平的具体办法，同样需要持续辨认。"],"perspectives":[{"country":"cn","text":"胜利带来主权恢复与新国际地位，长期破坏和内部矛盾仍待解决。"},{"country":"jp","text":"解除武装、占领改革和责任追究开始，社会必须面对侵略历史。"}],"sources":[{"id":"surrender","locator":"1945-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1945-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"continuity":{"before":"日本已经宣布接受投降条件，但国际和各战区的正式受降程序尚待完成。","after":"月度战史在这里结束；占领改革、战罪审判、去殖民化与冷战将继续塑造战后世界。"},"relatedBattles":[]}]}],"sources":[{"id":"nam14","title":"一战年度档案：1914","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1914/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam15","title":"一战年度档案：1915","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1915/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam16","title":"一战年度档案：1916","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1916/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam17","title":"一战年度档案：1917","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1917/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam18","title":"一战年度档案：1918","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1918/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"namtime","title":"第一次世界大战时间线","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/timeline/","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"armenian","title":"亚美尼亚种族灭绝：概述","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/the-armenian-genocide-1915-16-overview","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"usentry","title":"美国参加第一次世界大战","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/wwi","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"verdun","title":"一战整体与凡尔登战场背景","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/first-world-war","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"somme","title":"索姆河战役","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/battle-somme","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"chinaWW1","title":"十四点原则与中国山东问题","publisher":"美国国家一战博物馆","url":"https://www.theworldwar.org/learn/peace/fourteen-points","note":"结合一战年度时间线与中国参战、华工条目阅读。"},{"id":"fourteen","title":"威尔逊十四点原则","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/fourteen-points","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"peace","title":"巴黎和会与凡尔赛条约","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/paris-peace","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"china","title":"抗战大事记","publisher":"人民日报资料／中央纪委网站刊载","url":"https://m.ccdi.gov.cn/content/3e/04/4363.html","note":"以文中相应年月定位，并与本站既有抗战战役、党史资料交叉阅读；不照搬个别战果口径。"},{"id":"mao38","title":"中国共产党一百年大事记","publisher":"中共中央党史和文献研究院","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml","note":"定位1938年《论持久战》；亦参照本站既有1938年党史资料。"},{"id":"pearl","title":"中国、日本、美国与通向珍珠港之路","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/pearl-harbor","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"holocaust","title":"纳粹迫害与大屠杀时间线","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/timeline/holocaust","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"prewar","title":"第二次世界大战关键日期：前史及战争","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"nanjing","title":"南京大屠杀案罪行调查表","publisher":"国家档案局／南京市档案馆","url":"https://www.saac.gov.cn/zt/2014-12/11/content_77660.htm","note":"1946年调查材料的档案展陈；个别证言是具体个案，不据此推算整体人数。"},{"id":"ww2dates","title":"第二次世界大战关键日期","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates","note":"用于日期交叉核对；个别事件起讫口径与其他编年资料有差别，不把简表视为完整战史。"},{"id":"neutral","title":"美国1930年代中立法","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1921-1936/neutrality-acts","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"winter","title":"冬季战争80周年史事说明","publisher":"芬兰总理办公室","url":"https://valtioneuvosto.fi/en/-/winter-war-began-80-years-ago-today","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"sea","title":"大西洋战役概述","publisher":"美国海军历史与遗产司令部","url":"https://www.history.navy.mil/content/history/nhhc/browse-by-topic/wars-conflicts-and-operations/world-war-ii/1942/atlantic/overview.html","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"home","title":"二战美国后方编年选录","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/home-front-selected-chronology","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"lend","title":"租借法与盟国援助","publisher":"美国国务院历史办公室存档","url":"https://2001-2009.state.gov/r/pa/ho/time/wwii/81508.htm","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"yugoslavia","title":"轴心国入侵南斯拉夫","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/axis-invasion-of-yugoslavia","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"nz","title":"第二次世界大战逐年时间线","publisher":"新西兰文化与遗产部 NZ History","url":"https://nzhistory.govt.nz/war/second-world-war/timeline","note":"按日期主题定位；时间线存在个别错误或口径差异，须与专题档案及其他官方编年交叉核对。"},{"id":"pacific","title":"二战整体与太平洋战场导读","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/second-world-war","note":"用于战场进程，不把概述中的简化日期替代具体事件起讫。"},{"id":"dunkirk","title":"敦刻尔克史实说明","publisher":"帝国战争博物馆","url":"https://www.iwm.org.uk/sites/default/files/press-release/dunkirk_film_2017_fact_sheet_and_iwm_resources_available.pdf","note":"不同资料对末批撤运日有口径差异，本文按跨5—6月叙述，未照搬单一截止日。"},{"id":"atlantic","title":"大西洋会议与宪章","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/atlantic-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"wannsee","title":"万湖会议与会议记录","publisher":"万湖会议纪念教育馆","url":"https://www.ghwk.de/de/konferenz","note":"会议协调既在进行的种族灭绝，不是把屠杀起点简单定在会议当天。"},{"id":"atomic","title":"曼哈顿计划","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/war/topics/manhattan-project","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"ghetto","title":"华沙隔都起义","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/warsaw-ghetto-uprising","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"katyn","title":"卡廷罪行史料专题说明","publisher":"德国联邦独裁历史研究基金会","url":"https://www.bundesstiftung-aufarbeitung.de/de/stiftung/aktuelles/neues-online-dossier-zum-verbrechen-von-katyn","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"bengal","title":"Hungry Bengal: War, Famine and the End of Empire","publisher":"Janam Mukherjee／牛津大学出版社","url":"https://academic.oup.com/book/2861","note":"史学专著摘要；饥荒因果涉及供应、价格、殖民政策与战争，多种研究有不同解释，本文不写未核定死亡总数。"},{"id":"cairo","title":"开罗与德黑兰会议外交文件集","publisher":"美国国务院历史办公室 FRUS","url":"https://history.state.gov/historicaldocuments/frus1943CairoTehran","note":"定位1943年12月1日开罗公报及相关会议文件。"},{"id":"tehran","title":"德黑兰会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/tehran-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"yalta","title":"雅尔塔会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/yalta-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"un","title":"联合国宪章","publisher":"联合国","url":"https://www.un.org/en/about-us/un-charter","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"potsdam","title":"波茨坦会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/potsdam-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"command","title":"Command Decisions：日本投降决策讨论","publisher":"美国陆军军事史中心","url":"https://history.army.mil/portals/143/Images/Publications/catalog/70-7.pdf","note":"书末关于日本投降因素的讨论；不同研究意见并列，不能以单因解释。部分网络环境可能无法打开军史网站。"},{"id":"surrender","title":"日本投降书：原件与释文","publisher":"美国国家档案馆","url":"https://www.archives.gov/milestone-documents/surrender-of-japan","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"nam15deep","title":"1915：早期战壕战","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/1915-early-trench-battles","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"nam17deep","title":"1917：僵持的一年","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/1917-year-stalemate","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"nam18deep","title":"1918：胜利之年","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/1918-victory","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"barbarossa","title":"巴巴罗萨行动与苏德战场","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/war/articles/operation-barbarossa","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"stalingrad-deep","title":"斯大林格勒：试验、适应与实施","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/war/articles/stalingrad-experimentation-adaptation-implementation","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"dday-deception","title":"诺曼底登陆：坚忍行动与欺骗计划","publisher":"英国遗产组织","url":"https://www.english-heritage.org.uk/visit/places/dover-castle/history-and-stories/d-day-deception/","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"},{"id":"dday-supply","title":"纪念诺曼底：情报、准备与人工港","publisher":"英格兰历史遗产保护局","url":"https://historicengland.org.uk/whats-new/features/commemorating-d-day/","note":"专题解释资料；与本月原有编年及档案交叉阅读，衔接文字和主题路径为本站编辑归纳。"}],"countries":[{"id":"de","name":"德国","views":{"ww1":"一战中的德国试图以快速击败法国解除两线压力，未能速胜后越来越依赖消耗、潜艇与强化动员。封锁、粮食短缺和军队损耗最终与革命相连，不能把失败归咎于所谓后方背叛。","ww2":"纳粹德国通过独裁、扩军和对外侵略追求支配欧洲，战争与种族灭绝、强迫劳动和资源掠夺相互连接。理解其战略计算，不意味着接受其宣传，更不能把纳粹政府、所有德国居民与抵抗者混为一个声音。"}},{"id":"uk","name":"英国及帝国","views":{"ww1":"英国从维护比利时中立与欧洲均势走入大战，依靠海军、金融和帝国资源支持西线。印度、非洲、加拿大、澳新等地部队和劳工的贡献，以及殖民统治的不平等，同样是这一视角的组成部分。","ww2":"法国失守后，英国守住本土并维持海运，逐步依靠美苏等盟国合作转入反攻。防空与社会动员值得研究，殖民地饥荒、种族等级和帝国利益也不可被胜利叙事遮蔽。"}},{"id":"fr","name":"法国","views":{"ww1":"本土遭到入侵，使收复领土与阻止德国再攻成为核心诉求。凡尔登、索姆河和1917年军队危机显示，士兵不是无穷资源，继续抵抗需要指挥、待遇与政治信任共同支撑。","ww2":"1940年失败带来占领与维希合作政权，也出现自由法国和地下抵抗。法国不是从战争中消失，而是在不同政治选择中持续存在，解放又与重建国家合法性联系起来。"}},{"id":"ru","name":"俄国／苏维埃俄国","views":{"ww1":"俄国为维护巴尔干影响与盟国关系参战，军事损失、运输困难和政治危机推动1917年两次革命。布尔什维克以严苛和约退出大战，仍未获得国内稳定和平。"}},{"id":"ah","name":"奥匈帝国","views":{"ww1":"帝国试图以打击塞尔维亚维护边疆统治，却在俄国、巴尔干和意大利战线长期消耗。依赖德国援助、粮食与民族政治危机逐步交织，最终帝国框架瓦解。"}},{"id":"rs","name":"塞尔维亚","views":{"ww1":"开战的直接压力来自奥匈，军民在抵抗、占领、撤退和流亡中承受重大损失。保存的军队此后继续作战，小国经历不能只当作大国外交的开场背景。"}},{"id":"ot","name":"奥斯曼帝国","views":{"ww1":"帝国加入同盟国后在海峡、高加索、两河与巴勒斯坦等地作战，加里波利防御与最终失败并存。亚美尼亚种族灭绝及对居民的暴力，是政权责任的核心问题，不能被军事成败掩盖。"}},{"id":"us","name":"美国","views":{"ww1":"美国先保持中立，金融贸易与潜艇冲突逐渐拉近其与协约国关系，1917年参战后需要时间形成远征能力。威尔逊推动和平原则，国内政治却阻止美国加入国际联盟。","ww2":"从有限援助转向正式参战，美国依靠工业、海运与联盟协调同时支撑欧洲和太平洋战场。反法西斯目标与国内种族不平等、日裔拘禁及城市轰炸的争议，需要一并审视。"}},{"id":"it","name":"意大利","views":{"ww1":"1915年转入协约国阵营，领土诉求使国家走进长期山地作战。卡波雷托失利与后来的防御重整，显示领导决策和士兵承受力的重要；战后不满也被法西斯政治利用。","ww2":"法西斯政权通过殖民侵略和对英法作战追求帝国地位，准备与资源却难支撑目标。1943年转向停战后，国土仍遭德国占领，并出现抵抗与合作政权并存的复杂局面。"}},{"id":"cn","name":"中国","views":{"ww1":"日本借对德战争占领青岛并扩大山东权益，中国的中立未能阻止战火。1917年参战和华工服务表达国际参与，巴黎和会的山东问题却显示弱国在胜方内部同样缺乏平等。","ww2":"中国从1931年局部抗战、1937年全面抗战走向1945年胜利。正面战场、敌后战场与社会动员长期牵制日本，合作抗日也伴随内部矛盾；失土、屠杀、轰炸、迁移与经济破坏构成军民的共同重负。"}},{"id":"jp","name":"日本","views":{"ww1":"日本对德作战并扩大东亚与太平洋权益，是协约国成员，但自身地区目标与其他盟国并不完全相同。山东问题将战时扩张延伸到战后争端。","ww2":"日本帝国通过侵华与南进夺取领土和资源，所谓解放亚洲的宣传与殖民占领、强迫劳动及暴行相矛盾。舰队失利、交通破坏和同盟压力最终迫使投降，平民受难不应被用来抹去侵略责任。"}},{"id":"su","name":"苏联","views":{"ww2":"苏联先与德国签订协定并参与东欧势力划分，1941年遭德国入侵后进行决定性的长期抵抗。工业转移、社会动员与军事学习支撑反攻；国家的伟大牺牲不抹去苏联自身的镇压与对他国主权的侵犯。"}},{"id":"pl","name":"波兰","views":{"ww2":"1939年遭德苏分割，占领不意味着国家与社会停止抵抗。犹太居民面对种族灭绝，地下军队与海外部队继续作战；1944年华沙起义与1945年后的政治安排，使解放和完全自主之间仍有距离。"}}],"people":[{"name":"威廉二世","life":"1859—1941","role":"德国皇帝","bio":"德国皇帝，参与帝国外交与战争决策。1914年支持奥匈，战争中军方权力逐渐上升；1918年退位并流亡。研究他可追踪君主声望、军国政治和统帅部权力如何共同影响国家选择。","wars":["ww1"]},{"name":"尼古拉二世","life":"1868—1918","role":"俄国皇帝","bio":"战争中亲任最高统帅，把王朝声望与军事成败直接相连。1917年退位，次年在俄国内战环境下被杀。其经历连接战场失利、后方供给与君主制崩溃。","wars":["ww1"]},{"name":"威尔逊","life":"1856—1924","role":"美国总统","bio":"带领美国从中立转向参战，提出十四点原则并推动国际联盟。巴黎和会中的妥协及美国国内批准失败，显示国际理想需要实际权力、联盟协调与国内政治支持。","wars":["ww1"]},{"name":"霞飞","life":"1852—1931","role":"法国将领","bio":"1914年在边境失利后重组部署，指挥体系下的马恩河反击遏止德军。后来长期攻势的损失引发争议，1916年离开主要指挥岗位，体现初期成功不能保证始终适应战争变化。","wars":["ww1"]},{"name":"贝当","life":"1856—1951","role":"法国将领；后任维希政权首脑","bio":"一战参与凡尔登防御，1917年处理法军军心危机；二战法国失败后领导维希政权并与纳粹德国合作，战后因叛国被判刑。人物评价必须区分阶段，不能以早年军功遮蔽后来责任。","wars":["ww1","ww2"]},{"name":"黑格","life":"1861—1928","role":"英国远征军统帅","bio":"主持索姆河、第三次伊普尔及1918年相关行动。其指挥涉及高昂伤亡、战略约束与军队学习，评价存在长期争论，既不能只以绰号否定，也不能仅以最终胜利消解代价。","wars":["ww1"]},{"name":"兴登堡","life":"1847—1934","role":"德国统帅；后任总统","bio":"一战由东线胜利获得声望，1916年与鲁登道夫掌握更大军事权力。后任德国总统并于1933年任命希特勒为总理，其政治生涯连接帝国战争与魏玛危机。","wars":["ww1"]},{"name":"鲁登道夫","life":"1865—1937","role":"德国军事领导人","bio":"与兴登堡共同强化战争统筹，支持冒险战略并组织1918年春季攻势。失败后参与极端民族主义政治，是理解统帅部责任及战败神话的重要人物。","wars":["ww1"]},{"name":"福煦","life":"1851—1929","role":"协约国统帅","bio":"1918年在危机中加强英法等军队统一协调，参与组织反攻与停战。其作用主要在联盟统筹，不能把盟军整体工业、兵员与各国部队贡献压缩为个人天才。","wars":["ww1"]},{"name":"克列孟梭","life":"1841—1929","role":"法国总理","bio":"1917年再度执政，推动继续作战与联盟协调，战后在巴黎和会强调法国安全。其政策反映法国被入侵经验，也与其他战胜国的均势和国际组织主张发生冲突。","wars":["ww1"]},{"name":"劳合·乔治","life":"1863—1945","role":"英国首相","bio":"1916年出任首相，重视军需与战争统筹，后来参与巴黎和会。在军事指挥、国家经济和帝国利益之间的权衡，是理解英国长期作战的重要切口。","wars":["ww1"]},{"name":"列宁","life":"1870—1924","role":"布尔什维克领导人","bio":"主张反对继续帝国主义战争，1917年革命后推动退出大战，接受布列斯特和约以保住新政权。退出国际战争与国内和平并不等同，俄国仍经历内战与政治暴力。","wars":["ww1"]},{"name":"穆斯塔法·凯末尔","life":"1881—1938","role":"奥斯曼将领；土耳其共和国创建者","bio":"参与加里波利防御，战后成为土耳其民族运动与建国的重要领导者。其一战角色与后来共和国政治应分阶段理解，不能把后来的国家身份直接套回1915年的帝国军队。","wars":["ww1"]},{"name":"希特勒","life":"1889—1945","role":"纳粹德国独裁者","bio":"通过独裁、种族主义与侵略扩张把德国带入世界战争，负有发动侵略与推动种族灭绝的核心责任。1945年在柏林自杀。叙述他的战略判断是为了辨认责任和机制，不能接受其自我辩解。","wars":["ww2"]},{"name":"墨索里尼","life":"1883—1945","role":"意大利法西斯独裁者","bio":"通过镇压与帝国扩张建立法西斯统治，侵略埃塞俄比亚并加入世界大战。1943年倒台后依靠德国在北方维持合作政权，1945年被意大利游击队处决。","wars":["ww2"]},{"name":"罗斯福","life":"1882—1945","role":"美国总统","bio":"推动租借援助、战争动员及同盟合作，参与战后国际组织规划。其政府同时实施日裔拘禁等侵犯权利政策。1945年4月去世，未亲历欧洲与对日战争最终胜利。","wars":["ww2"]},{"name":"丘吉尔","life":"1874—1965","role":"英国政治家、战时首相","bio":"一战参与推动达达尼尔行动，二战1940年出任首相，坚持对德战争并与美苏合作。其领导与演说作用需连同帝国政策、资源依赖和盟军整体贡献一起理解。","wars":["ww1","ww2"]},{"name":"斯大林","life":"1878—1953","role":"苏联领导人","bio":"参与德苏协定、苏联战争动员及盟国外交，苏军在巨大牺牲中击败德国的重要力量。战前清洗、初期判断失误、镇压与对他国主权的侵害也属于其责任，不能用胜利替代全面评价。","wars":["ww2"]},{"name":"蒋介石","life":"1887—1975","role":"中国战时主要政治军事领导人","bio":"领导国民政府的长期抗战，参与正面战场指挥及开罗等同盟外交。抗战贡献与军事失利、统治问题及国共摩擦须一并考察，中国军民和其他抗日力量的作用不能归于个人。","wars":["ww2"]},{"name":"毛泽东","life":"1893—1976","role":"中国共产党领导人","bio":"推动抗日民族统一战线与敌后抗战战略，1938年《论持久战》分析长期抵抗的条件与阶段。其战争论述应与根据地、群众动员和实际战局相联系，不能理解为预知每一场战役的详细结果。","wars":["ww2"]},{"name":"彭德怀","life":"1898—1974","role":"中国共产党军事领导人","bio":"抗战期间参与领导八路军作战，组织百团大战等敌后行动。其经历有助理解铁路破袭、根据地生存与日军报复性进攻之间的关系，并应区别战果、损失和长期承受能力。","wars":["ww2"]},{"name":"杜鲁门","life":"1884—1972","role":"美国总统","bio":"1945年继任总统，参与波茨坦会议、对日战争终结与战后政策。其任内原子弹用于日本城市，决策背景、其他选择和对平民后果的争议，应以资料和不同研究审慎比较。","wars":["ww2"]},{"name":"裕仁","life":"1901—1989","role":"日本天皇","bio":"作为日本帝国国家体制核心，与军政决策的关系是战争责任研究的重要问题。1945年参与接受投降的决策并广播宣布，不能以最后终战介入遮蔽更长战争期间的责任讨论。","wars":["ww2"]},{"name":"艾森豪威尔","life":"1890—1969","role":"盟军统帅","bio":"指挥北非等联合行动，担任西北欧盟军最高统帅并组织诺曼底登陆与后续推进。其关键工作包括多国协调、资源分配和政治军事关系，而非独自决定每一场战斗。","wars":["ww2"]},{"name":"朱可夫","life":"1896—1974","role":"苏联将领","bio":"在莫斯科防御、苏军战略反攻与柏林作战等方面发挥重要作用。与其他统帅、部队和工业动员共同构成苏军胜利条件，人物声望不能替代对具体战役责任与代价的讨论。","wars":["ww2"]},{"name":"尼米兹","life":"1885—1966","role":"美国海军将领","bio":"统筹太平洋重要海军行动，中途岛及中太平洋推进是核心关联。其指挥依赖情报、舰队人员、航母航空兵与巨大后勤生产体系，胜利不应被简化为单一灵感。","wars":["ww2"]},{"name":"山本五十六","life":"1884—1943","role":"日本海军将领","bio":"参与策划珍珠港突袭并统率联合舰队。突袭的战术成果没有消除日本长期资源劣势，中途岛等行动又造成严重损失；理解其顾虑不等于把侵略决策包装成无奈。","wars":["ww2"]},{"name":"隆美尔","life":"1891—1944","role":"德国将领","bio":"以北非机动作战著名，后参与西欧防御。战果与失利都受补给、海空力量和轴心资源限制；个人军事声誉不能把所属政权的侵略性质和占领责任从叙述中抽去。","wars":["ww2"]},{"name":"蒙哥马利","life":"1887—1976","role":"英国将领","bio":"指挥阿拉曼等行动，参与诺曼底及西欧战役，也与市场花园受挫相关。重视准备和兵力集中是其特点，仍需放在盟国资源与多国指挥关系中评价。","wars":["ww2"]},{"name":"麦克阿瑟","life":"1880—1964","role":"美国将领","bio":"参与菲律宾防御、撤至澳大利亚后组织西南太平洋推进，1945年主持接受日本投降并领导占领。个人承诺和形象与战略选择交织，菲律宾居民和部队承受的代价同样重要。","wars":["ww2"]},{"name":"戴高乐","life":"1890—1970","role":"自由法国领导人","bio":"1940年从伦敦号召继续抵抗，组织自由法国，争取法国参与解放与战后安排的地位。其行动显示政府停战后国家抵抗仍可延续，也涉及法国不同政治力量间的竞争。","wars":["ww2"]}],"paths":[{"id":"decisions","war":"ww1","title":"速胜的幻灭","question":"一场局部危机，怎样变成长达四年的战争？","intro":"从外交选择进入战场，再看速胜失效后各国如何越陷越深。节点之间既有因果推进，也有战略环境的变化。","steps":[{"date":"1914-06","connection":"从刺杀与巴尔干背景开始，辨认危机仍有其他走向的时刻。"},{"date":"1914-07","connection":"局部冲突经过最后通牒、动员与联盟决策，被推向欧洲战争。"},{"date":"1914-08","connection":"战争计划落地后，侵入比利时与东线交战扩大了冲突范围。"},{"date":"1914-09","connection":"马恩河挫败速胜企图，运动战逐步转成阵地对峙。"},{"date":"1915-03","connection":"面对战壕，各军寻找突破办法，火力与步兵协同仍有缺口。"},{"date":"1916-07","connection":"索姆河体现长期消耗的代价，也推动战术和组织调整。"},{"date":"1917-04","connection":"法国攻势受挫，美国参战，国内承受力与外部资源同时改变。"},{"date":"1918-03","connection":"德国试图在美军大规模到来前决胜，却再次面对补给和消耗限制。"},{"date":"1918-11","connection":"军事失败与社会政治危机交汇，停战终于成为现实。"}]},{"id":"trenches","war":"ww1","title":"战壕、工厂与后方","question":"为什么勇敢和一次突破都不足以结束战争？","intro":"把火炮、步兵、坦克与运输放回同一条线，也看见为前线持续供给的人。","steps":[{"date":"1914-10","connection":"机动包抄未能结束西线战争，连续战壕逐渐成形。"},{"date":"1915-05","connection":"火炮与炮弹需求推动军需动员，后方开始深刻改变前线能力。"},{"date":"1916-02","connection":"凡尔登把补给道路、部队轮换与长期承受力推到中心。"},{"date":"1916-07","connection":"索姆河集中暴露炮击、工事和步兵推进的复杂关系。"},{"date":"1916-09","connection":"坦克首次投入索姆河战场，技术试验尚不能单独改变战局。"},{"date":"1917-11","connection":"康布雷试验更紧密的兵种配合，初期突破仍需后续保障。"},{"date":"1918-08","connection":"亚眠的协同进攻反映数年积累，连续攻势开始压倒德军。"}]},{"id":"russia","war":"ww1","title":"东线与革命","question":"前线的消耗，怎样进入国家和社会内部？","intro":"沿俄国的军事危机、革命与退出战争阅读，再回看东线变化怎样影响西线。革命有自身根源，不能归为某一场败仗的直接结果。","steps":[{"date":"1914-08","connection":"东线开战便出现巨大损失，协约国的多线战略与俄军处境相连。"},{"date":"1915-08","connection":"持续后撤扩大国土、人口和军队的压力。"},{"date":"1916-06","connection":"勃鲁西洛夫攻势取得突破，也付出高昂消耗。"},{"date":"1917-03","connection":"战争压力与长期政治矛盾交汇，二月革命按公历发生于3月。"},{"date":"1917-07","connection":"临时政府继续战争，攻势失败进一步削弱权威。"},{"date":"1917-11","connection":"十月革命按公历发生于11月，新政权转向争取停战。"},{"date":"1918-03","connection":"布列斯特和约使俄国退出大战，德国得以调动更多兵力向西。"},{"date":"1918-04","connection":"东线释放的兵力不能保证西线取胜，德国仍陷入消耗与后勤困境。"}]},{"id":"oceans","war":"ww1","title":"封锁、潜艇与美国","question":"海上的较量，怎样改变陆地上的力量对比？","intro":"从海运、潜艇与外交追到美国参战，理解工业资源怎样经过运输转化为战场力量。","steps":[{"date":"1914-12","connection":"欧洲以外的战事与海上封锁，显示战争从开端就具有全球联系。"},{"date":"1915-02","connection":"德国扩大潜艇战，希望削弱英国依赖的进口与海运。"},{"date":"1915-05","connection":"卢西塔尼亚号沉没使平民伤亡与美国中立问题更加尖锐。"},{"date":"1916-05","connection":"日德兰海战没有使德国摆脱英国海上优势。"},{"date":"1917-02","connection":"无限制潜艇战重新升级，美国与德国关系急剧恶化。"},{"date":"1917-04","connection":"美国参战把金融、工业与后续兵力投入协约国一方。"},{"date":"1917-05","connection":"护航等措施逐步应对潜艇威胁，援助能否到达成为关键。"},{"date":"1918-07","connection":"美国兵力开始更直接地作用于战场，德国时间窗口不断缩小。"}]},{"id":"peace","war":"ww1","title":"帝国边缘与未竟和平","question":"战争的世界性，为什么不能只用西线来解释？","intro":"从殖民地、奥斯曼帝国与中国参战走向和会，追问停战之后谁获得发言权、谁仍被排除。","steps":[{"date":"1914-11","connection":"奥斯曼帝国参战扩大冲突空间，欧洲之外的社会被更深卷入。"},{"date":"1915-04","connection":"达达尼尔战役与亚美尼亚种族灭绝，呈现帝国战争的不同面向。"},{"date":"1916-06","connection":"阿拉伯起义等进程使反抗与大国利益相互交织。"},{"date":"1917-08","connection":"中国参战与华工贡献，使中国更深进入大战及战后权益交涉。"},{"date":"1918-01","connection":"十四点原则提出新的和平语言，实际承诺与利益安排仍有距离。"},{"date":"1918-10","connection":"帝国解体加速，但新边界与民族问题并未自然解决。"},{"date":"1919-01","connection":"巴黎和会开始，胜利者内部也为安全、赔偿和殖民问题争论。"},{"date":"1919-06","connection":"凡尔赛条约与山东问题显示和平的妥协与不平等，影响继续延伸。"}]},{"id":"aggression","war":"ww2","title":"从侵略到全球战争","question":"一次次退让与冒险，如何把地区危机连在一起？","intro":"将亚洲与欧洲前史并置，辨认不同侵略者的选择及国际秩序失效；这是一条比较阅读线，不把不同地区说成单一因果链。","steps":[{"date":"1931-09","connection":"从东北遭侵略开始，看集体安全承诺与实际行动之间的缺口。"},{"date":"1933-01","connection":"纳粹巩固独裁，使对外扩张与对内迫害获得国家机器支持。"},{"date":"1935-10","connection":"意大利侵略埃塞俄比亚，再次暴露国联制裁的局限。"},{"date":"1937-07","connection":"日本扩大对华侵略，中国进入全民族抗战。"},{"date":"1938-09","connection":"慕尼黑让步未能满足纳粹扩张野心。"},{"date":"1939-03","connection":"德国占领捷克地区，突破此前宣称的有限要求。"},{"date":"1939-08","connection":"德苏协定及秘密安排改变进攻波兰的外交条件。"},{"date":"1939-09","connection":"德国侵略波兰，英法宣战，欧洲战争爆发。"},{"date":"1941-06","connection":"德国进攻苏联，把战争规模与暴力程度进一步扩大。"},{"date":"1941-12","connection":"日本对美英等国开战，地区战场进一步连成全球战争。"}]},{"id":"china-resistance","war":"ww2","title":"中国的长期抵抗","question":"从城市防御到敌后与交通线，抗战怎样坚持下来？","intro":"贯通主要会战、战略认识、敌后战场与国际补给，保留失利、牺牲和政治冲突，避免把长期抗战写成一串胜利名单。","steps":[{"date":"1931-09","connection":"东北抵抗与侵略长期化，是理解全面抗战不可省略的前史。"},{"date":"1937-07","connection":"卢沟桥事变后，军队与社会进入更大范围的抗战动员。"},{"date":"1937-08","connection":"淞沪会战消耗巨大，也把坚持抵抗的战略问题推向全国。"},{"date":"1937-12","connection":"南京大屠杀必须辨明侵略责任，城市失陷没有结束抗战。"},{"date":"1938-04","connection":"台儿庄胜利振奋信心，却没有消除长期力量差距。"},{"date":"1938-05","connection":"《论持久战》系统讨论怎样在战争过程中改变力量对比。"},{"date":"1938-10","connection":"武汉失守后，正面战场、敌后战场与内迁动员更加重要。"},{"date":"1940-08","connection":"百团大战把交通线、根据地和军民动员放在同一幅图景中。"},{"date":"1942-03","connection":"缅甸战事使中国长期抵抗与国际援助通道直接相连。"},{"date":"1944-04","connection":"一号作战造成严重失地，提示后期战局仍然复杂艰难。"},{"date":"1944-05","connection":"滇西反攻争取打通外援道路，展示跨战场协同的具体困难。"},{"date":"1945-08","connection":"长期抵抗与国际战局变化共同通向日本接受投降。"},{"date":"1945-09","connection":"中国战区正式受降，战争结束与和平重建之间仍有距离。"}]},{"id":"east-front","war":"ww2","title":"从莫斯科到柏林","question":"德军的速胜，为什么转成苏联的持续反攻？","intro":"追踪战役转折，也追踪工厂转移、补给、预备队与作战经验，避免用天气或某位统帅解释整场战争。","steps":[{"date":"1941-06","connection":"突袭与包围造成苏军灾难，苏联仍组织动员和工业转移。"},{"date":"1941-09","connection":"围城、基辅包围与占领区屠杀共同构成东线的严酷现实。"},{"date":"1941-12","connection":"莫斯科反攻击破短期结束战争的企图。"},{"date":"1942-07","connection":"德国转向南方资源与交通目标，兵力和补给被进一步拉长。"},{"date":"1942-09","connection":"城内防御牵制德军，城外反攻准备逐步成熟。"},{"date":"1942-11","connection":"天王星行动攻击薄弱侧翼，完成对斯大林格勒德军的合围。"},{"date":"1943-02","connection":"投降标志重大转折，苏军仍需应对后续作战风险。"},{"date":"1943-07","connection":"库尔斯克之后，苏军取得并持续扩大东线主动权。"},{"date":"1944-06","connection":"巴格拉季昂行动重创德军，与西线登陆形成战略夹击。"},{"date":"1945-01","connection":"维斯瓦—奥得河攻势把战线推进到德国核心地区。"},{"date":"1945-04","connection":"柏林战役通向纳粹政权覆灭，也留下最后阶段的巨大伤亡。"}]},{"id":"pacific-islands","war":"ww2","title":"太平洋的距离与补给","question":"为什么航母、机场和运输船要放在一起看？","intro":"从日本初期扩张到逐岛反攻，沿基地、空中力量和海运的联系阅读，也看见岛屿居民与战俘的代价。","steps":[{"date":"1941-12","connection":"珍珠港与南进攻势相连，日本寻求暂时排除美国干预。"},{"date":"1942-02","connection":"新加坡陷落显示同盟国初期防御崩溃，日本占领负担同时扩大。"},{"date":"1942-05","connection":"珊瑚海阻止海路进攻莫尔兹比港，航母消耗影响下一步部署。"},{"date":"1942-06","connection":"中途岛重创日本主力航母，改变继续扩张的条件。"},{"date":"1942-08","connection":"瓜岛机场成为海空与地面争夺的中心，战斗进入长期消耗。"},{"date":"1942-11","connection":"海战削弱日本增援能力，补给困境日益决定岛上处境。"},{"date":"1943-02","connection":"日本撤出瓜岛，同盟国开始扩大反攻。"},{"date":"1944-06","connection":"菲律宾海海战进一步削弱日本舰载航空兵。"},{"date":"1944-10","connection":"莱特湾作战打击日本舰队，也推动特攻扩大使用。"},{"date":"1945-06","connection":"冲绳的惨重代价使终战方式成为更尖锐的问题。"},{"date":"1945-08","connection":"原子弹、苏联参战与日本决策交汇，战争终于走向结束。"}]},{"id":"supplies","war":"ww2","title":"看不见的战线：生产与运输","question":"装备造出来以后，怎样真正到达前线？","intro":"以资源流动贯通大西洋、北非、缅印与诺曼底。联系在于共同的战争组织问题，不把相距遥远的行动都说成直接互为原因。","steps":[{"date":"1940-01","connection":"英国配给把战争运输压力传入普通家庭。"},{"date":"1940-12","connection":"长期抵抗促使美国提出更明确的军需支援方向。"},{"date":"1941-03","connection":"租借法把援助从传统买卖扩展为更大规模的合作。"},{"date":"1942-05","connection":"滇缅公路中断，空运成为支援中国的重要方式。"},{"date":"1942-10","connection":"阿拉曼的准备与火力运用，建立在长期供应积累上。"},{"date":"1943-05","connection":"大西洋反潜体系逐步成熟，使同盟国运力更可靠。"},{"date":"1944-03","connection":"缅印作战突出空运与地面补给的巨大差别。"},{"date":"1944-06","connection":"诺曼底登陆之后，持续卸载和运输决定滩头能否壮大。"},{"date":"1944-11","connection":"安特卫普真正通航，揭示占领港口与使用港口并非一回事。"}]},{"id":"civilians","war":"ww2","title":"被战争吞没的日常","question":"看见战场之外的人，才能完整理解战争吗？","intro":"沿制度性迫害、城市灾难、饥荒、抵抗与解放阅读。不同罪行、责任与处境需要分别辨明，不用笼统苦难抹平差异。","steps":[{"date":"1933-01","connection":"独裁建立和权利剥夺，为后续制度性暴力创造条件。"},{"date":"1937-12","connection":"南京大屠杀留下必须保存与核对的侵略罪行证据。"},{"date":"1938-11","connection":"反犹暴行公开升级，逃离迫害者却难以获得接纳。"},{"date":"1941-09","connection":"东线侵略与种族灭绝在占领区直接结合。"},{"date":"1942-01","connection":"万湖会议体现官僚、运输与警察体系参与灭绝政策。"},{"date":"1943-04","connection":"华沙隔都起义展示被迫害者的抵抗与尊严。"},{"date":"1943-10","connection":"孟加拉饥荒提示战争资源分配与殖民治理的平民代价。"},{"date":"1944-08","connection":"巴黎与华沙的不同处境，使解放不再只是同一个结局。"},{"date":"1945-01","connection":"解放奥斯维辛之后，幸存者仍面对疾病与失亲。"},{"date":"1945-03","connection":"东京大轰炸把平民伤亡与作战方式的讨论推到眼前。"},{"date":"1945-09","connection":"救济、审判、记忆和重建，让终战故事继续延伸。"}]},{"id":"alliance-peace","war":"ww2","title":"同盟与和平的难题","question":"共同赢得战争以后，怎样共同安排和平？","intro":"把宣言、会议与实际作战相互对照，理解合作的成果，也保留殖民地、波兰及战后利益冲突。","steps":[{"date":"1941-08","connection":"大西洋宪章提出共同原则，但原则与帝国现实之间存在张力。"},{"date":"1942-01","connection":"联合国家宣言形成共同抵抗承诺，具体资源仍需协调。"},{"date":"1943-01","connection":"卡萨布兰卡讨论继续进攻与无条件投降目标。"},{"date":"1943-11","connection":"开罗与德黑兰把亚洲、欧洲战略及战后安排连接起来。"},{"date":"1943-12","connection":"开罗宣言公布，政治承诺还需战争胜利和后续文件落实。"},{"date":"1944-06","connection":"东西两线大攻势将会议承诺转化为实际行动。"},{"date":"1945-02","connection":"雅尔塔讨论占领、波兰、联合国及苏联对日参战。"},{"date":"1945-06","connection":"联合国宪章签署，制度设计包含战争经验与大国妥协。"},{"date":"1945-07","connection":"波茨坦讨论德国处置并向日本提出投降要求。"},{"date":"1945-09","connection":"正式受降结束世界大战，去殖民化与新的国际矛盾仍在展开。"}]}],"note":"逐月叙事为史实基础上的原创整理；国家处境是编辑解读，不是虚构当事人自述。主战期每月连续，前史与余波选编；并非逐日全史。无虚构对白、现场感官细节或人物内心独白。"};
